VN.registerScenario("ch04", [

  /* ===============================================
     Scene 1: arcadia_arrival ― 聖都アルカディア (EP55)
     =============================================== */
  { label: "arcadia_arrival" },
  { chapter: { no: "第四章", title: "教国編" } },
  { bg: "arcadia_lower" },
  { bgm: "town" },
  { text: "あれから一週間程経った。俺達は点々と教国の街を巡り、最終的には教国の首都である聖都アルカディアを訪れていた。" },
  { text: "砂岩や煉瓦造りの家が立ち並び、人の行き来も多く、豊かさが垣間見える。一応は、此処が旅の終着点である。長期滞在することになるだろう。" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "center", id: "akatsuki", expr: "normal" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "思ったより安いんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "何がです？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "宿賃だ、王都と帝都に比べるとな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "あまりお金は気にしなくても結構ですよ、この世界では優秀な才能があれば幾らでも稼げますから" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうかもしれないがな……やっぱり男としてプライドがあるだろ……" },
  { chara: { slot: "center", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そういうものなんですか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、そうだ、そういう物なんだ" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふふふ……我に身を守って貰ってる時点でご主人の男としてのプライドはズタズタのボロボロなのではないか？" },
  { text: "そんな風にアカツキと話していると、クロセルが割って入ってくる。ギロリと鋭い目付きでクロセルへと視線を移す。" },
  { text: "今日も今日とてなんとも挑発的な態度だ。ニヤニヤと嫌な笑みを顔に貼り付けている。取り敢えず一発殴りたい。" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "チッ……こればっかりは否定出来ないから腹が立つな……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふははー！この世は才能が全てだ、肝に銘じておくが良い、ご主人" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くっ……くそっ！オラァ！" },
  { se: "rumble" },
  { fx: "shake" },
  { text: "安い挑発だ。乗るのも馬鹿らしい。取り敢えず、行き場の無い怒りを抱えた俺は、壁に拳を叩き付ける。幸運にも穴は開かなかったが、建物がギシッと嫌な音を立てた。" },
  { chara: { slot: "center", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "人を傷付けられないからと言って物に当たるのは止めて下さいね……" },
  { chara: { slot: "right", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……悪かった" },
  { text: "アカツキの叱責で我に返る。彼女の言う通りだ。俺は項垂れ、反省する。" },
  { chara: { slot: "center", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ヤマトさんにはヤマトさんで出来る事がありますから、例え才能が無くとも……あまり落ち込まないで下さい" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、そうだな……俺にだって出来ることはある、分かってるさ……" },
  { chara: { slot: "left", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人……我も少し言い過ぎた、すまないな……" },
  { chara: { slot: "right", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "いや、クロセルの言う事は事実だ、俺は事実から目を逸らしてるだけだ、だから気にするな" },
  { text: "この世界では才能が全て。それは今まで何度も痛感してきた事だ。だから、今更落ち込むことなど無い。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、んじゃ取り敢えずこの話は終わりだ、今日は……そうだな……ギルドに行ってみるか" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私は他に用事があるので別行動で" },
  { chara: { slot: "center", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "私はティア様を見てるよ、ヤマト様とクロセルさんで行ってくると良い" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "了解、じゃあ行くぞ、クロセル" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、分かったぞ、ご主人" },
  { hide: "akatsuki" },
  { hide: "el" },
  { text: "アカツキ、エル、ティアの三人と別れると、俺はクロセルを連れて宿を出た。目的地は冒険者ギルドだ。他の主要都市には必ずあったのだから、聖都にもある筈。勿論、地図なんて物は無い為、まずは道を尋ねる所から始めることになる。という訳で、俺とクロセルの二人は、行き交う人から冒険者ギルドの場所を聞き込みながら進むのであった。だが、こうして聞き込みをしていると、関係の無い噂話の類も入ってくる。それは、例えば……" },
  { bgm: "mystery2" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "公国が滅びた？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ……確かに魔王は公国を攻め込むと言っていたが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それにしたって早すぎないか？魔王が誕生してからまだ一週間程度だぞ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "公国は魔王領と隣り合わせ、何の障害もなく魔王の軍勢が進軍したとすれば……確かに今頃公国が滅びていてもおかしな話ではない" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なるほどな、でも“何の障害もない”訳が無いだろ……公国だって攻め込まれる事が分かっていたなら対応して迎え撃ったはずだ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "迎え撃ったからと言って、進軍を抑止出来たとは限らないのだぞ、それほどまでに、力量差が歴然としていたのかもしれん" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "馬鹿げてる、所詮は信憑性の無い噂話だ" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そうだな……今はまだ、噂話に過ぎない……" },
  { text: "それっきり、クロセルは口を噤んだ。信じられなかった。あの皇帝、いや魔王が、一つの国を容易に滅ぼすだけの力を持っているという事実が。もし、その話が本当ならば。教国も……安全では無いのかもしれない。" },
  { text: "俺は……本当に奴から逃れられるのだろうか？こんなこと、考えていても仕方がない。俺は思考を一旦放棄し、今現在に集中する。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ん……？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どうした？ご主人" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、避けるぞ" },
  { se: "rumble" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "あっわわっ……ご主人！？" },
  { text: "後方から車輪が激しく回転する音。同時に辺りが騒がしくなる。振り向いている時間すら惜しいと、俺は道の脇へと移動し、クロセルの手を引いて抱き寄せる。" },
  { text: "そして一呼吸の後。今までクロセルが居た場所を、一台の馬車が全速力で駆け抜けていった。" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ったく……危ないな……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "あれは、馬車か……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こんな人の往来の多い場所をあんな速度で駆け抜けていくとか、頭おかしいだろ、何をあんな急いでたんだか……" },
  { chara: { slot: "left", id: "crocell", expr: "blush" } },
  { name: "クロセル", who: "crocell", expr: "blush", text: "助かったぞ、ご主人……そ、それより、早く離してくれぬか、苦しいぞ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、悪かった" },
  { text: "抱き締めていたクロセルを腕の中から解放すると、走り去っていく馬車の背へと視線を移す。誰が乗っているかまでは遠くてよく見えないが……なんとも嫌な予感がする。" },
  { text: "言うなれば、事件の匂いって奴だろうか。尤も、俺は自分に関係の無い事件にまで関わる気はない。そういうお節介は勇者の仕事だ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……行くか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "追わないのか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "必要無い、俺達は無関係だ" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ……ご主人がそう言うのなら" },
  { text: "あの馬車について、クロセルも何か思う所があったらしい。だが、無関係な物は無関係だ。下手に関わって不利益を被るのはお断りだ。俺は引き続き、ギルドの方へと歩みを進めた。" },
  { text: "そして、数十分程、聖都を彷徨い歩いただろうか。俺達はギルドに辿り着いた。当然、その造りはタルフの村のそれとは別物。その施設の本質は同様であっても、その外見は似ても似つかない。" },
  { text: "タルフの村のギルドのように周囲から別段浮いているということもなく、辺りの建物と同じ、砂岩と煉瓦で作られた建物である。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そこそこ、まずまず、少しだけ、辺りと比較して相対的に、大きな建物……ってぐらいだな、感想は" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "無理に持ち上げる必要はないのだぞ……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……ぶっちゃけてしまえば拍子抜けする小ささだな、タルフの村のギルドの方が此処よりでかいだろ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "教国では殆ど魔物が出ないからな、他国に比べるとギルドの必要性が薄いのだろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか、なるほどな" },
  { text: "タルフの村では、確かに魔物に関する依頼が多かった。冒険者もしっかりと武装し、戦闘を想定した装いの者が殆どだった様に思える。それに対し、教国の冒険者は、良く言えば平和的と言うか……非武装の人間も多く居る。" },
  { text: "というか、見る限り、そもそもの冒険者人口が少なそうだ。此処に来る途中の街には、そもそもギルドが無い場所も多かった。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "というか……この様子だとギルドの依頼で生計を立てるのって……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、些か難しいな、我の本領を発揮出来ないのは痛い" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "だよな……" },
  { text: "ギルドに入り、依頼の一覧へと目を移す。一応、俺達の出来そうな依頼もあるにはあったが、どれも報酬が微小か、達成が難しそうな物ばかりだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "流石は神の国、悪党退治の依頼も無い辺り、治安も良いみたいだな……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "教国は我々が住むには少し、平和過ぎたかもしれん" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "別の方法で収入を得た方が良さそうだ、流石にこれじゃ依頼で食ってくのは厳しいだろ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "同意する、何か他の方法を考えねばな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "んじゃ、取り敢えず今日の所は引き上げるとするか" },
  { text: "そう結論付けると、俺達は足早にギルドを後にした。そして、帰路の途中。俺達は喧騒を切り裂いて、耳にへばり付くある声に気が付く。その声は俺にとっては耳障りで、どうも癇に障る。俺は声の方向を見た。" },
  { bgm: "holy" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "誰だ？あいつ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ……聖教会の者か？どうやら演説をしているようだな" },
  { text: "視線の先に居たのは……爺だった。長い白髪に高い帽子を被った、老齢の男。服装から鑑みるに、クロセルの言う聖教会の者で間違い無いのだろう。" },
  { text: "何か言っているが……どうも此処からでは上手く聞き取れない。不快な声だけが意味を持たずに耳に届く。" },
  { name: "通行人", text: "君達、イヴ様を知らないのか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あ？誰だお前" },
  { name: "通行人", text: "いや、大した者じゃないよ、イヴ様を指差して『誰だ？』なんて言ってるからつい気になってね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "イヴって……男だろあいつ" },
  { name: "通行人", text: "どういうことだい？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ……いや、気にすんな。で……イヴ様ってのは何なんだ？偉い人なのか？" },
  { name: "通行人", text: "聖教会教皇イヴ・エンド、この国で神様の次に偉いお方だ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ふーん……イヴェンか" },
  { name: "通行人", text: "変な略し方しないでくれよ……君達が何処から来たのか知らないけど、余り下手な事言ってると……聖教会に粛清されるよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "それはそれは、ご忠告どうも" },
  { text: "この良く知らない男の言うことを信じていい物か。いや、この男が俺に嘘をつく理由はない、信じても良いだろう。教皇イヴ・エンド、この国に於ける事実上のトップ……か。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "爺だけで、神は居ないみたいだな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "神は教会の奥深く、聖域と呼ばれる空間で生活していて、滅多な事では出てこないと聞いている、こんな場所に顔をだすことはあるまい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうなのか……なんか窮屈そうだな、神ってのも" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "人に崇め奉られる者というのは、常に窮屈に生きている物だ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "それは魔王的な体験談か？" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……かもしれんな" },
  { hide: "eve_end" },
  { text: "そう答え、クロセルは教皇を一瞥すると、興味を失ったかのように視線を落とし、歩き始める。俺も同じ様に教皇を一度だけ視界に収めると、クロセルの背を追って歩みを進めた。" },
  { bgm: "town" },
  { chara: { slot: "right", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "偶然と言えど、この国のトップの御尊顔を拝めたんだ、収穫はあったな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人は、あの教皇と関わりを持つ予定なのか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そういう訳じゃないが、俺達の身に何かあった時に頼ることになるかもしれないからな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "逆に、頼られる可能性もある……な" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あ、いや、その場合は助けてやる義理はないから放置するぞ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうだったな、助ける義理の無い人間は助けない、ご主人はそういう人だった" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだ、良く覚えとけ" },
  { text: "或いは、それは皮肉だったのかもしれない。だが、それは事実だ。俺は自分自身から目を逸らさない、だから痛くも痒くもない。" },
  { text: "俺は利己的な人間だ。利他的行動や人情とは縁のない人間だ。そして、俺はそれを悪く思ってはいない。どんな人間であろうと、俺は俺だ。悪く思うことも嫌うことも無い。俺は英雄の器ではないのだ。勇者の人格ではないのだ。" },
  { text: "──なら俺は何なのだろう。悪人か？｜咎人《とがびと》なのか？それなら納得はゆく。確かにかつて俺は悪人だったのだから、今でも悪人であるのは道理が通っていると言える。そう、俺は悪なのだ。例え人を傷害する事が無くても、俺は……悪なのだ。" },
  { chara: { slot: "left", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人……" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "再三言うが、心を読むな……" },
  { text: "クロセルは不満そうな声を漏らす。何故だ？俺が悪人で何が問題なのだろう。クロセルだってかつて魔王だったのだ。悪人だ。──本当にそうか？俺はクロセルを指差して、お前は悪だと言えるのか？否だ。俺には出来ない。" },
  { text: "俺にとって、クロセルは悪ではないのだ。そうか、同じなのか。きっとクロセルは優しいから、俺を悪だと認められないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセル、お前は優しいな" },
  { chara: { slot: "left", id: "crocell", expr: "blush" } },
  { name: "クロセル", who: "crocell", expr: "blush", text: "それを言うならご主人も同じだろう、ご主人も優しいのだ" },
  { chara: { slot: "right", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "優しい悪人ねぇ……まぁ、そういうのも悪くないのかもな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "むむむ……悪人と言う所は譲らないのだな……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだな、そこは譲れない" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "まぁ……良いだろう、及第点だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それはどうも" },
  { text: "クロセルが諦めたように溜息を吐く。それに合わせて、俺は自嘲するように鼻で笑った。そして俺達は足並みを揃えて、帰路を歩んだのであった。" },
  { hide: "all" },

  /* ===============================================
     Scene 2: floating_city_night ― 浮遊都市 (EP56)
     =============================================== */
  { label: "floating_city_night" },
  { fade: "out" },
  { bg: "arcadia_lower_night" },
  { fade: "in" },
  { bgm: "daily" },
  { text: "あれから暫く街を巡り、俺達は日が暮れる前に宿に戻ってきた。" },
  { chara: [
      { slot: "left", id: "el", expr: "smile" },
      { slot: "center", id: "tia", expr: "laugh" },
      { slot: "rcenter", id: "yamato", expr: "normal" },
      { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ただいま" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、戻ったぞ" },
  { text: "それから少しして、声が聞こえたのかエルとティアが部屋から出てきて出迎えてくれた。少し辺りを見渡してみるが、アカツキはどうやらまだ帰っていないようで姿が見えない。" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様、クロセルさん、おかえりなさい" },
  { name: "ティア", who: "tia", expr: "normal", text: "おかえり！ヤマト！" },
  { name: "エル", who: "el", expr: "sad", text: "ギルドの方はどうでした？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……それなんだが……" },
  { text: "俺は冒険者ギルドで生計を立てるのは難しいことをエルに説明した。" },
  { chara: { slot: "left", id: "el", expr: "sad" } },
  { name: "エル", who: "el", expr: "sad", text: "そうか……それは困ったな……いつまでもアカツキさんに頼る訳にもいかないし" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "全く同感だ、教国の需要に沿った何か良い商売でも無いのか……？" },
  { text: "腕を組み宙に視線を注ぎながら思考を巡らせる。エルも指を口元に当てながら黙想、何か良い案が無いか考えてくれているようだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキに頼らず何かをするとして、俺達が持っているアドバンテージは魔法使いが多いことぐらいだよな" },
  { chara: { slot: "left", id: "el", expr: "normal" } },
  { name: "エル", who: "el", expr: "normal", text: "そうだね、魔法の才能を持つ人間はそれだけで貴重だ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "魔法ならわたしに任せて！何でも出来るわよ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうなんだよ……やろうと思えばティアとクロセルの魔法で何でも出来そうだし……選択肢が多すぎて最善策が思いつかないタイプのあれだな……" },
  { chara: { slot: "left", id: "el", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっふっふ……我ほどの力があれば略奪など造作も無いぞ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "おいやめろ元魔王、折角教国まで逃げてきたのにこっちでもお尋ね者になったら困るだろ" },
  { text: "そんな風に三人で話していると、突如として後ろから肩を叩かれる。話に夢中で警戒を怠っていた。だが仮に敵だとしたら俺は既に殺されている筈。ということは……" },
  { hide: "all" },
  { chara: { slot: "center", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "貴方がそれを言うんですか……元ヤンのヤマトさん？" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "アカツキか……戻ってきたなら声ぐらいかけろよ、心臓に悪い" },
  { text: "振り向くと、案の定アカツキが立っていた。その手には謎の書類が握られている。用事があると言っていたが、何の用事だったのだろう。" },
  { chara: { slot: "center", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "全く……やっぱりヤマトさん達に任せたら碌な事にならなそうですね" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "おいおい酷くないか？俺だって頑張って考えてるんだぞ" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうだぞ！ご主人は馬鹿なりに無い知恵を絞って何の役にも立たない案を出してくれていてだな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おいクロセル、殴るぞ？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふはははは！無駄だと言うのに！学習能力が無いのか？哀れなご主人……" },
  { chara: { slot: "left", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "あはは……確かにこの調子だとまともに話し合いにならないからアカツキさんが来てくれて助かったよ" },
  { text: "俺とクロセルが睨み合ってる中、エルはそれを何処か温かい視線で見守りながら、やがてアカツキに視線を移す。そして、アカツキの持つ書類と顔を交互に何度か見ると、笑顔を浮かべて言葉を続けた。" },
  { chara: { slot: "center", id: "akatsuki", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "アカツキさん、ギルドでの収入は見込めないことを想定して、既に何か収入を得る方法を考えてくれてたんでしょ？" },
  { chara: { slot: "center", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "エルさんも中々に察しが良いですね、そうですよ、新しい商売に向けて、ちょっと買い物をしてきました" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう、流石はアカツキだな、それでその商売ってなんだ？" },
  { name: "アカツキ", who: "akatsuki", expr: "laugh", text: "それは明日のお楽しみとしましょうか、今日はもう日が暮れましたし休むことにしましょう" },
  { chara: { slot: "left", id: "tia", expr: "laugh" } },
  { name: "ティア", who: "tia", expr: "laugh", text: "えーわたし何のお仕事をするのか知りたい！" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ティア様ごめんなさい、説明の為に外に出る必要があるのですが、比較的治安が良いと言えど夜間外出は危険ですので……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "それにティア様にも明日から働いて貰う事になるのでゆっくり休んで下さい、お願いします" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だってさティア、明日はお前の出番もあるみたいだししっかり寝とけよ" },
  { name: "ティア", who: "tia", expr: "normal", text: "ヤマトがそう言うなら分かったわ！" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ティア様はヤマトさんの言葉だとすんなり従いますよね……というかどうして懐いてるのか不思議でなりません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺も不思議でならん、俺みたいな男は子供から嫌われる筈なんだがな" },
  { hide: "all" },
  { text: "アカツキは少し嫉妬したような目で俺を見ると、溜息を吐き、自分の部屋へと歩いていった。それに続いてエルがティアの手を引き部屋に戻り、最後はいつも通り俺とクロセルが残される。" },
  { chara: [
      { slot: "left", id: "crocell", expr: "laugh" },
      { slot: "right", id: "yamato", expr: "smirk" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "さて……俺はまだ眠くないし少し外の空気を吸ってくるか……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、我も着いて行くぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "来なくても良いんだぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっふ〜来て欲しい癖に何を言っている" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あーったく……勝手にしろ" },
  { text: "クロセルを睨み付けるが、それに全く動じずニヤニヤと笑みを浮かべる様子を見て、俺は諦めて視線を戻す。この世界に来てからどうも脅しが通用しない、俺が丸くなったのかこの世界の住人の肝が太いのか、どちらにせよやりにくくて仕方がない。" },
  { text: "俺は足早に宿から出て夜道を歩く。特に行き先は決めていない、夜風に当たりたかっただけだ。" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "昼間は暑いが夜は涼しいな、砂漠にしては寒暖差が少なすぎるぐらいだ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、この調子なら聖都でも快適に過ごせそうだな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "教国の首都は聖都って言うのか、それにしては聖なる感じはあまりしないが" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "聖都と言っても我々が居る此処は下層だからな、本当に神に関連する施設は中層、そして上層の聖教会に集約している" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "下層？中層？上層？なんだそれ" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人……気付かなかったのか……？あっちを見てみるが良い" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ん……どれどれ" },
  { text: "クロセルが指差したのは聖都の中心の方角……の空である。言われるがままに視線を移し、暗い夜闇に目を凝らしてみると……" },
  { bgm: "mystery2" },
  { fx: "flash" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "は？おい？何か空に浮いている！？どういうことだ！？" },
  { text: "そこには物体が浮いていた。否、あれはただの浮遊物体ではない。無数の建物がくっつき、都市を形成している。そしてそれが支えもなしに浮いているのだ。夜だから確信は持てないが、ほぼ確実にあれは浮いている。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "浮遊都市……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "更にその上にも巨大な建物が見えるであろう？それが聖教会だ" },
  { text: "言われた通り更に上を見てみると、なるほど確かに巨大な構造物が見える。遠すぎて良く確認できないが、此方は建物の集合体ではなく一つの建物が浮いているような感じだ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あれは魔法で浮いているのか……？" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "いや……あれも“神の創造物”だ、人智を超えた物である以上、理屈も何も無いのだろう" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "また“神”か、空なんて見上げないから昼間は気付かなかったな……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "最も、教会の人間ではない我々には縁のない物だがな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "もしかして中層って奴に住んでる奴らは全員教会の関係者なのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "その通りだ、教会の中でも一部の熱心な信徒だけが中層に住む権利を得られる" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そして上層は……まぁ予想はつくが聖教会の幹部格と“神”が住む場所って所か" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、その通りだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁそれなら確かに縁はなさそうだな……てか今日見た教皇って上層から下層に降りてきてたんだよな、ああも簡単に登り降り出来るのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "何かアクセスする手段があるのだろう、我は知らないが飛べば良いのでは無いか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや普通は飛べないから……" },
  { text: "そんな風に駄弁りながら空を眺めていると、何かが視界の中で小さく光る。不審に思い目を擦り、再び空を見上げるが何も見える様子はない。ただの錯覚だろうか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、今空が何か光らなかったか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うん……？我は気付かなかったな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら気の所為か……なんでもない" },
  { text: "クロセルが見ていないなら大方気の所為で間違いないのだろう。本当に見えていたのだとしても流れ星か何かの可能性もある。それに仮に何かが発光したのだとしても俺には関係のないことだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし……そろそろ部屋に戻るか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、そうだな、身体が冷え切る前に戻るとしよう" },
  { text: "そして俺はクロセルと二人で宿に戻り、明日に備えて眠りについたのであった。" },
  { hide: "all" },

  /* ===============================================
     Scene 3: bathhouse_project ― 新天地での商売と特訓 (EP57)
     =============================================== */
  { label: "bathhouse_project" },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "daily2" },
  { text: "あれから一晩が経った。そして俺達五人は先日の約束通り、アカツキに案内されるまま、聖都の一角に建つ、教国の建築様式に倣った古い建物の前に立っていた。立派ではあるが、かなり老朽化が進んでいる。" },
  { chara: [
      { slot: "farleft", id: "tia", expr: "surprised" },
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "center", id: "akatsuki", expr: "smile" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、着きました、皆さんお疲れ様です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "都心に意外と近いな、んで此処に何があるんだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ……見た所、何らかの施設跡のようだが" },
  { name: "ティア", who: "tia", expr: "normal", text: "なんなの？このお化け屋敷" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "まぁ見ての通り、この建物自体はただの中古物件です、今の所は" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほど、読めてきたな……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "察しが良いようで助かります。私、此処でちょっと商売をやろうと思いまして、その為に皆様の協力が必要なんです" },
  { text: "アカツキが手に持った書類の束をひらひらと振り、それを俺の方に差し出してくる。書いてある内容は単なる物件の契約書のようだ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "つーか……この建物借りたんじゃなくて買ったのか……これアカツキのポケットマネーだろ？流石に散財しすぎじゃないか……？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "これからリフォームも必要ですし、初期経費はもう少し嵩みますが、上手く行けば元は取れると思いますよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "大した自信だな、それで……その商売ってのは何なんだ？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まず前提としてティア様とクロセルさんの特技である魔術を活かそうと思いました、お二人ほどの才能があればそれを使って出来ることは無数です、そして中でも教国の需要と供給を鑑みて有効的な物は何か考えてみました" },
  { name: "ティア", who: "tia", expr: "laugh", text: "魔術ならわたしに任せて！" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっふっふ……残念だったな王女よ、我の方が魔術の才能は上なのだぞ、故に貴様の役目は無いのだ" },
  { chara: { slot: "farleft", id: "tia", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "おいクロセル、子供を虐めるなよ" },
  { text: "ドヤ顔をしながら胸を張っているクロセルと、恨めしそうな目でそれを見つめるティア。多分仲が悪い訳では無いのだが、いかんせんお互い子供っぽい所があるのが面倒な所だ。いやティアは年齢相応であって、クロセルの精神年齢が幼すぎるだけなのだが。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "お二人共に力を貸してもらいますから大丈夫ですよ……それで話の続きをしますね、祝福を受けた土地と言えど此処は砂漠です、水道も普及してませんし基本的に水は貴重です、水を使う贅沢な娯楽は存在しませんでした" },
  { chara: { slot: "lcenter", id: "el", expr: "normal" } },
  { name: "エル", who: "el", expr: "smile", text: "あっ……分かった、公衆浴場だね" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ご名答です、エルさん。クロセルさんとティアさんの魔法があれば、此処教国でも水は無限に使えます。それを利用して公衆浴場を開こうと思いまして" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "確かに此処でする商売としては理に適ってるな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "プールと悩んだんですが自由に泳げるプールを作れるだけの敷地は確保できなかったので、公衆浴場になりました" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "つまり、我は水を一杯作れば良いのだな？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうなりますね、水さえ用意できれば簡単に実現できます" },
  { chara: { slot: "farleft", id: "tia", expr: "laugh" } },
  { name: "ティア", who: "tia", expr: "laugh", text: "それぐらいなら朝飯前ね！わたしでも出来るわ！" },
  { chara: { slot: "lcenter", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "私の氷魔術は役に立てなそうだね、でも接客や清掃なら得意だよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エルは王宮に仕えてた元メイドだしな、この中で一番雑務には長けてるだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私は基本的にはエルさんと同じ業務内容に加え、施設の管理、運営が主な仕事になりますね" },
  { text: "一同やる気は十分。建物の改装が終わったら直ぐにでも営業を開始できそうだ。この商売が成功すれば教国での暮らしは盤石な物になる。俺も出来る限りの事で協力するべきだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺は何をすればいい" },
  { chara: { slot: "center", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "え？ヤマトさんですか？そうですね……" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "何意外そうな顔してんだよ……男である俺が何もせずお前らだけに任せておく訳にはいかねぇだろ、俺にも働かせろ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "そう……ですね……ヤマトさん何が出来ます？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺か？俺は……" },
  { text: "俺に出来ることを考えてみる。喧嘩……はディザビリティで封じられてる。恐喝……営業には使わない。勧誘……これぐらいか。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "広報とかなら出来るぞ、教国に公衆浴場なんて存在しない以上、軌道に乗るまでは広報活動が必要だろ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "あぁ、そうですね、それならヤマトさんにも出来そうです、お願いしますね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキ……さては俺にはそれ以外出来ないとか思ってたな？" },
  { chara: { slot: "center", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そんなことないですよ……？" },
  { text: "アカツキに顔を近付けると、すっと目を逸らされる。これは間違いなく黒だな。" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "はぁ……ったく、まぁ良い、事実だしな" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人……大丈夫だぞ、ご主人は何もしなくても我がご主人の面倒を見てやるからな……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "嬉しくない" },
  { text: "クロセルに拳を飛ばすが、それはクロセルの身体に触れる前にばしんと弾かれる。今となっては慣れた感覚だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "取り敢えず改装が終わるまでは休暇か……暇になるな" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、特訓の続きでもするか？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、そうするか、身体は継続的に動かしてないと鈍るからな" },
  { chara: { slot: "lcenter", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "じゃあ帰ろうか、ティアお嬢様歩ける？" },
  { name: "ティア", who: "tia", expr: "normal", text: "宿まで遠くないしわたしは大丈夫よ！" },
  { name: "エル", who: "el", expr: "smile", text: "うん、分かった" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私はもう少し残ります、改装工事をするのに大工の方と話し合わないといけないので" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか、大変だな、ご苦労さま" },
  { hide: "all" },
  { text: "そんな会話を軽く交わすと、俺達四人はアカツキを残し、宿に戻るのであった。そして、その次の日から再びクロセルとの特訓が始まった。場所は人通りの少ない下層の郊外だ。" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "right", id: "yamato", expr: "serious" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "こんな所で戦ってたら問題にならないか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむむ……これでも都心部からは結構離れたつもりなのだがな……多少の人通りがあるのはやむを得ないだろ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ王宮みたいにはいかないか、よし……いつでも良いぞ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人は守りの技術を磨きたいのだな？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、そうだな、攻める技術は俺には不要だ、体力の消費を最低限にしながら攻撃を受け流す技術が欲しい" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "なら此方から攻撃する故に、それを受け流すか躱してみるが良い" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おう、いつでも来い" },
  { se: "magic" },
  { text: "クロセルは武術の構えを取りながら、ぼそりと何かを呟くと、その身体が青い光に包まれる。見慣れた強化魔術だ。俺は四方位何処にでも動けるように体重を中央へと掛けた姿勢で硬直する。" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "いくぞ！ご主人！" },
  { fx: "shake" },
  { text: "クロセルの取った行動は愚直な突進。まずは距離を詰めねば格闘攻撃は当たらない。歴戦の戦士であればまずは読み合いから入るのが基本で、その過程をスキップするのは力量差に圧倒的な自信がある場合を除いて愚かな事である。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ、これは一般論であって……桁外れの分析の才能を持ったクロセルには関係ないことなんだがな" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "独り言とは余裕だな！舌を噛むぞ！" },
  { text: "クロセルはそのまま突き進み、やがて攻撃が当たる距離に入る。｜体躯《たいく》の差がある為、正確に言えば俺の攻撃が当たりクロセルの攻撃が届かない距離だ。だが俺は攻撃しない為、この距離におけるアドバンテージは殆ど関係ない。本当に大事な距離は……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "──此処だ" },
  { text: "低い姿勢のまま懐に飛び込んできたクロセルは右拳を放つ。だが俺の思考は常に筒抜けだ。届かないと分かっている攻撃をクロセルが放つだろうか？答えは否。このジャブはブラフ。本命の一撃は別にある。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……(なら、避ける必要はないな)" },
  { text: "視力の限界と戦いながら観察し、脳の限界と戦いながら高速で思考を回す。クロセルの拳を止めた俺に届く確実な一撃、それは何か。" },
  { text: "──即ち、死角からの攻撃だ。ブラフがブラフとして成立する為には、本命の一撃に重心、姿勢、筋力、思考などの要素を注がねばならない。つまり今のクロセルの拳に乗っているのは速度だけだ。ならば防御動作は必要ない。" },
  { text: "案の定、俺に放たれた拳は寸前で前進を止める。直ぐに攻撃をキャンセル出来るのはあの拳に威力が乗っていなかった証拠だ。次が恐らく本命の一撃。クロセルは畳んだ脚を伸ばし、飛び上がった。あの過剰な低姿勢は跳躍の予備動作だったのだ。" },
  { text: "そして俺はこの時点で既に行動を起こしていた。そうでも無ければ身体を強化したクロセルの攻撃に対処するには間に合わない。最後に使うのは直感。頭上を取ったクロセルが背後に回るか上から来るか横か前か、こればっかりは予測のしようがない。" },
  { text: "俺は前に向かって一歩駆けると、そのまま前転する。結果から言えば、クロセルの攻撃は跳躍から背後に回った上での回し蹴り。その一撃は転がった俺の頭上、空を切った。幸運にも読み勝った。分析の才能の未来予測を上回ったのだ。" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふむ……予想外だな……" },
  { text: "俺は転がった勢いのまま立ち上がり、距離を取りながら振り返ろうとするが……" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "とでも言うと思ったか！甘いぞご主人！" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っ……何処だ！？" },
  { text: "振り返った俺の視界にクロセルは居なかった。まずい、クロセルは俺の視界の死角に居る。次の攻撃が何処から来るか分からない。" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "一瞬と言えど敵から目を離したのが敗因だ！まだまだだな！" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うぐっ……" },
  { text: "後頭部に鈍い衝撃。視界が揺らぎバランスを崩す、その隙を的確に突くように更に背部に数発の追撃が行われる。立っていられなくなった俺は、思わずその場に膝をついた。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あの回し蹴りすらブラフ……かよ……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人であれば我の｜搦め手《からめて》を読んでくると思ったのでな、裏の裏を突いてみた" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁくそっ……ズルすぎるだろ……分析の才能" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ほら早く立ち上がれ、ご主人であればこの程度で倒れはしないだろう？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "当たり前だろ！覚えてやがれ……" },
  { text: "俺は立ち上がると、揺れる視界を定める為に軽く頭を抑える。数秒で平衡感覚を取り戻すと、ニヤけた笑みを顔に貼り付けたクロセルと対峙する。" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "身体強化の魔術と分析の才能と俺のディザビリティが無ければお前なんて……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ……確かに素手ばかりでは実戦で使えない場合も多いな、であれば……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あ？獲物を使う気か？俺は素手なんだしそれじゃ不利……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おい、ちょっと待て！クロセル！それって！" },
  { se: "magic" },
  { fx: "flash" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "──属性魔術……｜水弾《ウォーターボール》・｜雨《マシンガン》！" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "魔術はズルいだろおおおおおおおおおお！！！！？つか死ぬって！それ当たったら蜂の巣になるだろ！！！" },
  { text: "その後、クロセルの魔術の的当てが始まり、死ぬほど逃げ回ったのであった。つか数発当たった、治癒魔術が無ければ即死だった。" },
  { hide: "all" },

  /* ===============================================
     Scene 4: slave_auction ― オークション (EP58)
     =============================================== */
  { label: "slave_auction" },
  { fade: "out" },
  { bg: "arcadia_lower" },
  { fade: "in" },
  { bgm: "town" },
  { text: "あれから暫くの時が経った。その間、俺とクロセルは特訓に励み、教国での生活は平和その物だった。公衆浴場の改装工事も終わり、｜廃墟《はいきょ》であったあの建物は見違えるほど綺麗な施設となった。" },
  { chara: [
      { slot: "left", id: "tia", expr: "laugh" },
      { slot: "center", id: "akatsuki", expr: "smile" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ティア", who: "tia", expr: "normal", text: "すごーい！綺麗！" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "悪くないではないか、あの｜廃墟《はいきょ》が随分と見違えたな" },
  { name: "エル", who: "el", expr: "smile", text: "ほんと、立派だね" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "奮発しましたからね、後は備品を買い揃えればいつでも開店できますよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "忙しくなりそうだな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ある程度軌道に乗ったらヤマトさんの仕事は無くなりますから大丈夫ですよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや……それ全く嬉しくないんだが……" },
  { text: "公衆浴場の改装が終わり、｜廃墟《はいきょ》であったあの建物は見違えるほど綺麗な施設となった。王国の建築様式に近い辺り、アカツキが逐次細かく指示を出しながら改装したのだろう。異世界人らしい、時代錯誤な設備もあり、手がかかっている事が分かる。一体幾らしたのだろうか……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "あっ、それと居住スペースも用意したので、長くお世話になった宿とはおさらばですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これだけ広ければ居住スペースも確保出来るか、個室なのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "一応全員分部屋はありますけど……クロセルさんはヤマトさんと一緒に寝るんですよね？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ！そうなるな！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "今までは宿代が浮くから許してたが……まだ続けるのか？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "嬉しい癖に何を言っている" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いやたまには一人でゆっくり休みたいんだが……" },
  { chara: { slot: "left", id: "tia", expr: "angry" } },
  { name: "ティア", who: "tia", expr: "angry", text: "わたしもヤマトと一緒が良いわ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "駄目だ" },
  { name: "ティア", who: "tia", expr: "surprised", text: "えーなんで？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "駄目な物は駄目なんだよ" },
  { name: "ティア", who: "tia", expr: "surprised", text: "｜魔杖《まじょう》は良いのになんでわたしは駄目なの？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あーめんどくせー……アカツキこいつ説得してくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ティア様の言う通りだと思うんですが……" },
  { chara: { slot: "center", id: "el", expr: "cold_smile" } },
  { name: "エル", who: "el", expr: "cold_smile", text: "なら全員一緒に寝る？" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ははは……エル、冗談だろ？" },
  { name: "エル", who: "el", expr: "cold_smile", text: "冗談だよ" },
  { text: "笑顔のままぴくりとも表情を変えずに冗談を言い放つエルに少し恐怖を覚えた。心做しか目が怖いし、なんだか不穏な空気になってきた。これは俺が悪いのだろうか？" },
  { chara: { slot: "center", id: "el", expr: "smile" } },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "と……取り敢えず、買い物にでも行くか" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、公衆浴場の備品と生活備品が必要ですし" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "荷物持ちなら任せろ" },
  { name: "エル", who: "el", expr: "smile", text: "あっ……なら私も行くよ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我も着いていこう" },
  { name: "ティア", who: "tia", expr: "normal", text: "わたしも行くわ！" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "結局全員で動くことになるんだな……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私達王国のお尋ね者ですし、変に分かれて動くより安全ですからね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それもそうか、じゃあ行こうぜ" },
  { text: "そんな訳で、久々に全員揃って買い物に行くことになった。砂漠にあると言えど此処は教国の首都、殆どの物は買い揃えることが出来る。" },
  { chara: { slot: "left", id: "tia", expr: "laugh" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だからと言って不要な物は買うなよー……" },
  { name: "ティア", who: "tia", expr: "normal", text: "ヤマト！あそこでオークションがやってるわよ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前オークション好きだな……前に王宮を抜け出した時と既視感を感じるんだが……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "見るだけですからね、高価な品を買える程今はお金に余裕は無いので" },
  { text: "ティアが指差す方を見てみると、確かに大きな人集りが出来ている。少し背伸びをしてみるが、流石に見えなかった。これじゃあティアは何をやっているか見えないだろう。気は乗らないが、止むを得ないか。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ったく……見えないだろ、ほら、乗れよ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトありがとう！" },
  { name: "ヤマト", who: "yamato", text: "うぐっ……" },
  { text: "遠慮は一切無用、ティアは此方へ走り寄り、そのまま飛び乗ってきた。同時に首に結構な衝撃が走る。思わず声を漏らしてしまったが、ティアぐらいの子供であれば楽々持ち上げられた。これだと俺は見えないが、まぁ興味はないので別に構わないだろう。" },
  { chara: { slot: "center", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふむ、我も少し興味があるな" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "流石に二人は無理だぞ？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "案ずるな、こうすれば良い" },
  { text: "クロセルも背が小さい。ジャンプや背伸びじゃオークションの様子は見えないと思うが……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》──属性魔術 ｜風迅空歩《スカイウォーカー》！" },
  { se: "magic" },
  { text: "ふわりとクロセルの身体が浮き、宙を蹴るように数歩歩く。そして気が付けば、クロセルは俺の頭上へと立っていた。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あー……既視感二度目、そう言えばそんな魔術もあったな" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "あれ？我がこの魔術を使うのは初めてのはずなのだが" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "前にティアが……ってじゃあ肩車する必要無かったじゃねぇか" },
  { name: "ティア", who: "tia", expr: "normal", text: "えー魔術使うの大変だし……このままヤマトに乗ってるわね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ……気付くのが遅すぎたか……" },
  { name: "エル", who: "el", expr: "smile", text: "なんだかんだ言いつつ降ろさないヤマト様って優しいよね" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "あれぐらいはまともな男性であれば当然だと思いますけどね……" },
  { text: "そんな風に談笑していると、ふと此方へと視線が集まっていることに気が付く。辺りを見渡して、その視線の先を辿ってみると、そこには宙に浮いたクロセルが居た。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "そう言えば魔術の才能持ちって珍しいんだったよな……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "おっと……この視線は……我の放つ余りの威光に平伏しているのか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "オークションの｜野次馬《やじうま》だからな……珍しい物には目が無いんだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "本当はあまり目立ちたくないんですがね……" },
  { text: "アカツキがそんな不満を零したのと、クロセルが近付いてきた｜野次馬《やじうま》に話しかけられたのは同時だった。" },
  { name: "｜野次馬《やじうま》", text: "お嬢ちゃん魔術の才能持ってるのか、凄いね" },
  { name: "｜野次馬《やじうま》", text: "おいおい、確か空を飛ぶ魔術って確か風の魔術だったよな" },
  { name: "｜野次馬《やじうま》", text: "風の魔術と言えば、王国の王女様は風魔術が得意だって聞いたな" },
  { name: "｜野次馬《やじうま》", text: "もう少し……もう少し近付けばスカートが……" },
  { name: "｜野次馬《やじうま》", text: "そんなことよりお嬢ちゃん、暇ならちょっと付き合ってくれない？" },
  { text: "一度誰かが話し掛けたと思えば、それに便乗して四方八方から人が近付き、辺りに人混みが出来ていく。クロセルは満更でもない様子だが、俺やアカツキの心象としては悪目立ちしたくないのが本音だ。" },
  { text: "となると……此処は俺の出番か。" },
  { chara: { slot: "right", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁ！？お前ら何俺に無許可でこいつに話し掛けてんだ！？" },
  { name: "貴族風の男", text: "うん……？彼女は君の連れなのかい？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺はこいつの主人だ、俺の所有物に勝手に近付くんじゃねぇ！" },
  { name: "貴族風の男", text: "うわー怖いねぇ……この子君の奴隷なのか、酷いなぁ……ねぇ君、僕に着いてくればこんな野蛮な男の所よりずっと良い待遇で面倒を見てあげるよ？なんなら君の望みを幾らでも叶えてあげても良い" },
  { text: "綺麗な衣を纏った貴族風の男がそんな風にクロセルに声を掛ける。下心が見え見えで実に気持ち悪い。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "てめぇ、痛い目に遭わねぇと分からないか！？" },
  { text: "あぁ、イライラする。虫酸が走る。クロセルは俺の物だ。他の奴に渡すなど言語道断。絶対に許さない。気が付けば俺は、その男に掴み掛かっていた。" },
  { name: "貴族風の男", text: "暴力は良くないなぁ……僕は教会の人間だよ？もし怪我を負ったりしたら……只で済むとは思わない方が良い" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様、此処は抑えて……" },
  { chara: { slot: "center", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "クロセルさん、ヤマトさんが暴走する前に、お任せしますね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、そうだな" },
  { chara: { slot: "center", id: "crocell", expr: "laugh" } },
  { text: "クロセルは宙に浮いたまま、声を張り上げて言葉を続けた。" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "我はこの男の物だ、この男が貴様らを｜邪魔《じゃま》だと言うのなら、この男の言う事が聞けぬのなら、我が容赦しない" },
  { se: "flash" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "そう言いながら片手を振り上げると、口元が少し蠢く。それと同時に、クロセルの頭上からクロセルに向かって稲妻が落ちたかと思えば、巨大な雷鳴が鳴り響く。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "──我に近付くな、痛い目に遭いたくなければな" },
  { text: "彼女自身のカリスマ溢れる容姿に加え、魔術まで用いた見事な演出であった。言っていることは俺と全く同じだというのに、その影響力の差は歴然としていた。周囲の人間は完全に怯え、多くの者は言葉を失い沈黙していた。それはあの男も同様。クロセルを見ながらガクガクと震え、そのまま小走りでその場を離れていった。" },
  { chara: { slot: "center", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "クロセルさん？事態の収拾を付けたのは良いのですが、少しやり過ぎかと" },
  { name: "エル", who: "el", expr: "sad", text: "そうだね、関係ない人も怯えちゃってるよ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトより｜魔杖《まじょう》の方が格好良かったわね" },
  { chara: { slot: "right", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺の威厳が無いのは主に肩に乗ってるお前のせいだと思うんだが？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "それが分かってるなら降ろせばいいじゃないですか……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ああやって褒められると降ろしづらいだろ……くそっ" },
  { text: "完全に俺だけ空回りしていたようだが、なんとか人払いは出来たようだし結果オーライか。" },
  { bgm: "tension" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ついでにオークションを見るのに｜邪魔《じゃま》だった人混みも払えたな、これなら俺でも見える" },
  { chara: { slot: "center", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "私達も見えますが……あれは……ちょっと余り面白い見世物では無さそうですね……" },
  { text: "オークションの会場を見た途端、アカツキが目を細めて俯く。一体何の競りを行っているのだろう、遠目に見て分かるのは、人が並んでいるということ。人が並んでいる？どういうことだ？それも並んでいる人は皆、手足を鎖のような物で拘束されており……それはまるで……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "奴隷売買……か……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "みたいですね……王国では禁止されている行為ですが、ここ教国では容認されているのでしょうか……" },
  { text: "文字通り、人間が売られている。売られるということは親や身内に売られたか、或いは賊に捕まったのか、その経緯こそ不明な物の、少なくとも自ら望んで奴隷になった訳ではないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "日本の裏社会に精通した俺だが、人身売買は始めて見たな、少し興味がある" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "本気ですか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "本気だよ、奴隷にされた奴らに関して哀れだとは思うが、所詮は他人だからな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "まぁクロセルさんを奴隷のような扱いで侍らせているような人ですもんね……そりゃ奴隷にも抵抗は無いですよね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おい、俺はクロセルの事を大事に扱ってるつもりだが？" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……時々結構酷い扱いをされることもあるがな" },
  { name: "エル", who: "el", expr: "cold_smile", text: "と本人は言ってるけど……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "時々だろ、いつもじゃない" },
  { hide: "all" },
  { text: "少し遠くて良く見えない。俺はもう不要だろと断ってティアを降ろすと、一人その会場へと近付いてみる。近くで見て確信する。これは人に良く似た異種族とかではない、間違いなく人間だ。" },
  { text: "鎖に繋がれた奴隷達は皆同じような服装をしている。と言っても薄布一枚という訳ではなく、教国に住む人々と同じきちんとした洋服だ。加えて極端に痩せ細ったりしている訳でもない。最低限の衣食住は確保されているのだろう。" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そこまで酷い扱いをされてる訳じゃなさそうだな、商売道具なんだし当然と言えば当然だが" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "？？？", who: "bolt", expr: "normal", text: "最も、買われた後に必ずしも幸せになれるとは限らないけどね……" },
  { chara: { slot: "left", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんだお前" },
  { text: "ふと、気が付けば横に一人の少年が立っていた。金髪に帽子を深く被っており、服装は教国の物では無い、見たことのない物だ。少年と言っても年は俺と同じくらいだろうか、背が低いだけでその風貌は何処か大人びて見える。" },
  { name: "？？？", who: "bolt", expr: "surprised", text: "お兄さん、さっき騒ぎを起こしてた魔術師の主人なんでしょ？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、そうだが……何か文句でもあるのか？" },
  { name: "？？？", who: "bolt", expr: "smile", text: "滅相もない、人払いをしてくれて助かったよ、そして長い話は嫌いそうだから手短に話すけど……" },
  { text: "そう告げると少年は俺の耳元に口元を近付け、小声で続けた。" },
  { name: "？？？", who: "bolt", expr: "smile", text: "王国王女ティア、王国国王秘書アカツキ、お兄さん、この二人を連れてるよね？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……なぜ分かる？" },
  { name: "？？？", who: "bolt", expr: "surprised", text: "分かる物は分かるんだ、続けるよ、王国では“ヤマト”という男が反逆罪、加えて略取・誘拐罪として指名手配になってる" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "？？？", who: "bolt", expr: "smile", text: "──君でしょ？ヤマトって" },
  { text: "ニヤリと少年の口元が歪む。こいつ……俺達の事を知っている人間だ。服装からしても教国の人間ではない。" },
  { chara: { slot: "left", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "王国の追手か？" },
  { name: "？？？", who: "bolt", expr: "normal", text: "違うよ、僕は貴方達の敵じゃない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なら大人しく黙っててくれるんだろうな？" },
  { name: "？？？", who: "bolt", expr: "sad", text: "そうしたいのは山々なんだけど……ごめんね、こっちも事情があって、一つ条件があるんだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "脅迫か、なるほどな……" },
  { text: "此方は弱みを握られている。それに対して此方は相手に付いて何も分からない状態。これほど不利な交渉はない。此処は大人しく条件を呑むしか無いか……？" },
  { name: "？？？", who: "bolt", expr: "sad", text: "いや、条件とか言ったら脅迫だよね、ごめん言い換えるよ。お兄さん……いや、ヤマトさん、お願いがあるんだ" },
  { text: "どうやらこの少年は強硬手段は取りたくないようだ。と言っても、状況は脅迫に変わりないのだが……まぁ確かに命令されるよりはお願いされた方が相手の心象は良くなる。交渉術に長けた少年、いや……単純に純粋なだけなのかもしれない。" },
  { text: "少年は俺に向き直ると、帽子を取り、此方に頭を下げながら言葉を続けた。" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { cg: "cg_v_plea" },
  { wait: 500 },
  { name: "？？？", who: "bolt", expr: "sad", text: "──僕の妹を助けて欲しいんだ" },
  { text: "深く下げられた頭。仕立ての良い身なりと、その必死さがどうにも噛み合わない。奴隷売買の喧騒の中で、この少年の真っ直ぐさだけが、酷く場違いに見えた。" },
  { cg: null },
  { hide: "all" },

  /* ===============================================
     Scene 5: v_request ― V (EP59〜60)
     =============================================== */
  { label: "v_request" },
  { chara: [
      { slot: "left", id: "yamato", expr: "serious" },
      { slot: "right", id: "bolt", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "これまた突飛な話だな、何故俺がお前の妹を助けなければならない" },
  { name: "少年", who: "bolt", expr: "normal", text: "話すと長くなるのと……僕の素性は明かせないので、必要最低限だけ伝えさせて貰うね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ……無いよりはマシだな、納得できる説明をしてくれよ" },
  { name: "少年", who: "bolt", expr: "normal", text: "僕、見ての通り教国の人間ではなくて、別の国から来たんだけど……その旅の途中、盗賊に遭遇したんだ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "読めてきたな……それでお前は盗賊に襲われた訳か" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "少年", who: "bolt", expr: "sad", text: "はい、その通り、僕は直ぐにやられてしまったんだけど……死んだと思われたみたいで気絶したまま放置されたんだ、そして目が覚めると……馬車と妹は盗まれてしまった後だったと" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "妹を助けたい動機と経緯は分かったが……どうして俺なんだ？もっと他に頼める奴が居るんじゃないか？" },
  { name: "少年", who: "bolt", expr: "surprised", text: "ヤマトさん、魔王の復活を阻止する王命を受けたんだよね、それに失敗して反逆罪になっていると" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだな" },
  { name: "少年", who: "bolt", expr: "normal", text: "魔王の復活を阻止する事って並大抵の冒険者じゃ出来ないことだよね、ヤマトさんには魔王復活を｜目論《もくろ》む皇帝を退けられるであろう実力があったから選ばれた、そうでしょう？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あー……まぁ……そうなのかもな" },
  { name: "少年", who: "bolt", expr: "normal", text: "そんなヤマトさんなら、僕の妹を救い出してくれると思って、お願いさせて貰ったんだ" },
  { text: "アカツキとティアが王国の人間だと見抜く目。その風貌。そして王国が魔王復活を阻止する王命を出した事を知っている。この少年、間違いなく一般人じゃない。かと言って王国の人間でもない。となると……一体何者なんだ？" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ……要するに盗賊退治の依頼ってことでいいのか？" },
  { name: "少年", who: "bolt", expr: "surprised", text: "えっと……当面の目標はそれであってる……のかな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どういうことだ？お前の妹は盗賊に捕まったんだろ？" },
  { name: "少年", who: "bolt", expr: "surprised", text: "そうなんだけど……調べてみた所、盗賊に捕まった人間は人身売買されて奴隷として売られるみたいなんだよね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり……盗賊を退治しただけじゃ終わらない、というか意味がない可能性があるのか……奴隷売買をしている組織を叩かねばならないと" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "少年", who: "bolt", expr: "normal", text: "そうなるね、それでこのオークションの主催、何処か知ってる？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "知らないな、俺は通りすがっただけだ" },
  { text: "なるほど、つまりこの少年は妹を救い出す為にこのオークション会場に来たのだろう。仮にこの場で売られていなくても、このオークションの運営側を追えば妹の居場所も突き止められるという訳だ。" },
  { text: "オークションの運営陣を見てみると、そこには貴族らしい高そうな衣を｜纏《まと》った男と、武装した屈強そうな男が数名立っていた。最低限襲撃の対策はしているようだ。" },
  { name: "少年", who: "bolt", expr: "sad", text: "……聖教会だよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "は？" },
  { name: "少年", who: "bolt", expr: "sad", text: "聖教会が主催してるんだよ、このオークション" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "聖教会ってこの国のトップだろ？なんでそんな組織が奴隷売買なんかしてるんだ" },
  { name: "少年", who: "bolt", expr: "sad", text: "神に背いた罪人、要するに犯罪者を売り払っている……という名目で、盗賊から買い取った人間を混ぜて売っているんだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "その話……本当なのか？" },
  { name: "少年", who: "bolt", expr: "normal", text: "僕が調べた情報が確かなら" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "マジかよ……信じられねぇ……" },
  { text: "もしこの話が本当だとすると、少年の妹を救うには聖教会を敵に回す必要がある。それは折角手に入れたこの｜安寧《あんねい》の地を捨てることに他ならず……更に言えばそうなると完全に逃げる場所を失う訳で……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "悪いな、その話は受けられない" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "少年", who: "bolt", expr: "sad", text: "そう……だよね……ヤマトさん達は教国に逃げてきたんだもんね……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "分かってくれるようで助かる、だから他の人を当たってくれないか" },
  { name: "少年", who: "bolt", expr: "sad", text: "分かった……無理を言って申し訳ない……" },
  { text: "少年は深く頭を下げると、帽子を深く被り、｜俯《うつむ》いたまま背を向ける。" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ちょっと待ってください、今の話、本当ですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "盗み聞きとは趣味が悪いな、アカツキ" },
  { text: "いつの間にか俺の横にアカツキが立っており、アカツキが少年を呼び止める。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさんがいつまで経っても戻ってこないから厄介事に巻き込まれたのかと思って見に来たんです" },
  { name: "少年", who: "bolt", expr: "surprised", text: "アカツキさん……？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、私がアカツキです、貴方は……" },
  { name: "少年", who: "bolt", expr: "sad", text: "すいません、名は名乗れないので……今はVとだけ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "V君ですね、分かりました、それでさっきの話、本当なんですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おいアカツキ……話を聞いたなら分かってるだろ……相手は聖教会だぞ、敵に回したら折角手に入れた平和な暮らしを捨てることになるんだぞ" },
  { name: "V", who: "bolt", expr: "normal", text: "本当です……このオークションの主催は聖教会ですし、恐らく僕を襲った盗賊は聖教会に奴隷を提供してます" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かりました、引き受けましょう" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……本気か？" },
  { bgm: "heartwarm" },
  { chara: { slot: "left", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "本気ですよ、ただし、ヤマトさんの考えているようなやり方では無いですが" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "何か策があるってことか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、無いわけでもありません、それにV君、他に頼る場所も人も居ないんですよね" },
  { chara: { slot: "right", id: "bolt", expr: "surprised" } },
  { name: "V", who: "bolt", expr: "surprised", text: "はい……本当に引き受けてくださるんですか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "えぇ、任せて下さい" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "ありがとうございます！本当にありがとうございます！" },
  { text: "アカツキがそう言って胸を叩くと、少年は満面の笑顔を浮かべてぺこぺこと頭を下げる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "おいおい……俺は知らないぞ？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ヤマトさんには分からないでしょうが、人と人は助け合いですよ。それにこの国の癌を放っておけませんしね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "取り敢えず……どうすんだよ、この場にお前の妹は居ないんだろ？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、この会場には居ないみたいです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なら此処に居ても無駄だな、買い物済ませて一旦帰ろうぜ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "買い物は私達で済ませておくので、ヤマトさんにはちょっとお使いを頼んでいいですか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんだよ……言ってみろ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まずは妹さんの身柄が何処にあるか調べる必要があります、だからヤマトさんはこのオークションの運営陣にV君の妹の特徴を告げて、こういう奴隷が居たら買い取りたい、と言ってきて下さい、それで聖教会の抱えてる奴隷の中にV君の妹が居るか分かるはずです" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なるほどな、で……なんで俺なんだよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "見た目も経歴も、明らかに悪人ですし奴隷商人と話す際に怪しまれにくいと思いまして" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "おい殴るぞ？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そういう所です、凄い悪そう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "うぐっ……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "じゃあヤマトさん、任せましたよ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あいあい、分かったよ" },
  { hide: "all" },
  { text: "結果からすれば、アカツキがあのVと名乗る少年の依頼を引き受けてしまった。凄い面倒事に巻き込まれた気しかしないのだが……本当に大丈夫だろうか。あの様子だと断っても大丈夫そうだったし……この奉仕活動は本当に無駄にしか感じない。" },
  { chara: [
      { slot: "left", id: "yamato", expr: "serious" },
      { slot: "right", id: "bolt", expr: "sad" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "大した見返りもないしな……全く何で受けちまったんだか" },
  { name: "V", who: "bolt", expr: "surprised", text: "ごめんね……善意に付け入るような形になっちゃって" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "もういい、さっさと奴隷商人と話付けるぞ" },
  { name: "V", who: "bolt", expr: "surprised", text: "今はまだオークション中みたいだし、終わってからの方が良いんじゃないかな" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "俺に命令するな" },
  { name: "V", who: "bolt", expr: "sad", text: "分かった、ごめんよ……" },
  { text: "と言っても、Vの言う通りだ。今話し掛けに行っては｜邪魔《じゃま》な客としか思われないだろう。タイミングを見計らって、出来る限り怪しく、裏の世界に精通している様子で話し掛けねばならない。そうして待機している内に、数時間が経った。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "終わったか？" },
  { name: "V", who: "bolt", expr: "smile", text: "みたいだね、僕は話を合わせるから、ヤマトさん、任せたよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "言われなくても分かってる、行くぞ" },
  { text: "オークションが終わるのを待って、俺はVを置いて運営陣らしき男へと話し掛けに行く。" },
  { text: "足音が聞こえるからちゃんと着いて来てるだろう。" },
  { bgm: "suspense" },
  { chara: [
      { slot: "left", id: "yamato", expr: "smirk" },
      { slot: "right", id: "bolt", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よう、ちょっと良いか？" },
  { name: "奴隷商人", text: "はい、なんでしょうか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "奴隷が欲しいんだが、うちの坊っちゃんが言うには今日の品にはどうも惹かれなくてな、坊っちゃんが望むような奴隷は無い物かと聞きに来た訳だ、もし用意してくれたらどんなに高くても買って良いと思ってる" },
  { name: "奴隷商人", text: "左様ですか、それでどんな奴隷がご入用で？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おい、言ってみろ" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "未成人の赤髪の少女が良いな〜？出来ればしっかり礼儀作法を身に着けてる従順な子だと実に良い！そんな子は居ないかな？" },
  { name: "奴隷商人", text: "左様ですか！それなら丁度良い奴隷が先日入ったので、次の開催時にご用意できたらご用意させて頂きます、きっとお気に召すと思いますよ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか、流石だな、助かる" },
  { name: "V", who: "bolt", expr: "smile", text: "ふふふ……楽しみだね、期待してるよ" },
  { text: "このVという少年、俺より演技が板についている。というかこいつだけで良かったんじゃないか？そんな事を思いながら、軽く手を振って奴隷商人から離れる。そのまま暫く歩き、完全に見えなくなった所で、俺は口を開いた。" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前……妹の事そんな風に思ってたのか？" },
  { chara: { slot: "right", id: "bolt", expr: "surprised" } },
  { name: "V", who: "bolt", expr: "surprised", text: "失礼な！そんな訳無いだろ！妹の特徴を事細かに告げるにはああするしか無かったんだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "シスコンめ……" },
  { name: "V", who: "bolt", expr: "normal", text: "うぐっ……というかそれより、あの様子だと間違いなく妹は聖教会の元に居ると思って良いね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁそうだな、最近手に入れたと言っていたしほぼ間違いないだろう" },
  { name: "V", who: "bolt", expr: "normal", text: "となると取り戻すには、大人しく奴隷として彼女を買うか……会場で彼女を連れ去るか、或いは聖教会に乗り込んで助けるか、と言った所かな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだな、俺もそう言った手段しか無いと思う" },
  { name: "V", who: "bolt", expr: "normal", text: "でもアカツキさんは別の方法を考えてるみたいだったよね……信じて良いのかな……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あーそうだな……あいつは有能だから、信じて大丈夫だと思うぞ、あいつがミスすることは｜稀《まれ》だからな" },
  { name: "V", who: "bolt", expr: "normal", text: "ヤマトさん、アカツキさんのこと信用してるんですね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "まぁ……結構付き合いも長くなるしな……もう仲間っちゃ仲間だし……沢山お世話になったし……" },
  { text: "素直に信用している、とは恥ずかしくて言えないが、心の内で感謝はしている。彼女が居なければ俺は今生きていないだろうし、教国での暮らしも危うい物だっただろう。だから今回の……彼女の“｜我儘《わがまま》”は受け入れてやるべきなのかもしれない。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "俺の抑止を止めてまで何かをするなんて、あいつにしては珍しいもんな……" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "ふふっ……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "何笑ってんだよ馬鹿" },
  { name: "V", who: "bolt", expr: "surprised", text: "いや、アカツキさんとヤマトさん、ああやって言い合ってはいるけどやっぱり仲間なんだなって、そういう関係ってなんか羨ましい、良いなって思っただけです" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うるせぇなぁ……俺はあいつのことをそんな大層に思ってないからな" },
  { name: "V", who: "bolt", expr: "surprised", text: "はいはい、そうだね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "お前……うぜぇな……" },
  { name: "V", who: "bolt", expr: "surprised", text: "そんなこと言わないでよ、僕ももう仲間だろ？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "な訳あるか！お前は俺の敵だ！仲間な訳無いだろ！" },
  { name: "V", who: "bolt", expr: "surprised", text: "はいはい、冗談だから、もう日も暮れるし早く拠点に案内してよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "嫌だなぁ……はぁ……アカツキに免じて今回は許したが面倒事は面倒事に変わりはないな……" },
  { text: "事件が解決するまでと言えど、この生意気なガキと行動すると考えると……気が滅入る……" },
  { text: "アカツキに約束してしまった以上放って帰る訳にもいかず、仕方なくこの生意気な少年を連れて新たな我が家へと帰るのであった。間違いない。妹は聖教会の手元に居る。" },
  { hide: "all" },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "daily" },
  { text: "帰宅後、皆に紹介と説明を済ませ、数時間に渡る話し合いの結果、俺以外の全員一致でVの依頼を引き受けることが確約された。ついでに行く宛のないVは俺達の拠点に住むことになった。" },
  { chara: [
      { slot: "farleft", id: "el", expr: "smile" },
      { slot: "left", id: "akatsuki", expr: "normal" },
      { slot: "center", id: "yamato", expr: "normal" },
      { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "では満場一致で引き受けるということで、良いですね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺は賛成してないけどな" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……ヤマト様もそろそろ諦めなよ……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ、ご主人は男なのだからもう少し広い心を持つべきだな、それとVとやらの部屋は我のを使うと良い、我はご主人の部屋を使うからな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おい" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "分かりました、結果としてクロセルさんの部屋も用意しておいて助かりましたね" },
  { name: "V", who: "bolt", expr: "smile", text: "すいません、助かります" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それでどうするんだアカツキ、策があるんだろ？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうですね、当面の方針ですが……まず聖教会が奴隷としてV君の妹を捕らえているのは確定しているとみて良いでしょう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだな、だから盗賊退治をする必要はない" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、そして聖教会から妹さんを奪取する方法についてですが……" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "次の奴隷商の開催を狙って救出するのじゃ駄目なのかな？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、俺もそれが一番手っ取り早いと思う、安全に解決したいのなら奴隷として買ってしまうのが一番だが" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "その方法だと、真っ向から聖教会と敵対することになりますよね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あぁくそっ、分かってる、じゃあどうすれば良いんだよ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "私の策はこうです、聖教会を利用して聖教会を叩きます" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "アカツキ……お前何言ってるんだ？" },
  { text: "俺とV、そしてエルは頭の上にクエスチョンマークを浮かべる。一方クロセルだけは何故か合点がいった様子で一人頷いている。やはりこのメンバーのブレインはアカツキとクロセルの二人のようだ。" },
  { text: "因みにティアは結構前からソファで寝ている。難しい話にはついていけないよな。俺もついていけないもん。" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { chara: { slot: "right", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふむ、なるほどな……教国の統治形態を考えると……確かに良い方法かもしれん" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセルは分かるのか？" },
  { name: "V", who: "bolt", expr: "sad", text: "えっと……僕も良く分からないです……もう少し説明を頂けますか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "V君、聖教会が盗賊から奴隷を買い取っている……という話は何処で手に入れた物ですか？" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "聖都では無く、教国にある村ですね……僕達を襲った盗賊団を追って辿り着いた場所なので、村をその盗賊団が支配していて治安はかなり悪かったと記憶しています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その話の信憑性は……まぁその盗賊団の被害にあってる場所だし無くは無いのか" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "仮にその話が本当だとして、それを知っている人間は聖都に居ましたか？" },
  { name: "V", who: "bolt", expr: "normal", text: "居ない……と思います、先のオークション会場でも何人かに話を聞きましたが皆揃って間違った……『罪を犯し人の身から落ちた犯罪者を売り払っている』という認識を持っていましたね" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "これは仮説ですが、恐らく聖教会も同じ認識を持っているのでしょう、いや……正確に言えば“聖教会の上層部”がその認識を持っている、と" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我が思うに、聖教会は各層の格差が大きい組織であると推定する、聖都が下層、中層、上層に分かれているのが根拠だな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、クロセルさんの言う通りです、ですから聖教会の下層が受け持っている奴隷売買の全容について、聖教会の上層部は把握していないと思っています" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "要するに、聖教会のお偉いさん達は部下の汚職に気付いていない訳か" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "所詮は推測に過ぎないので……もしかしたら聖教会の上層部は下層の汚職を把握した上で容認している可能性もあります、その場合は別の方法を考える必要がありますね" },
  { name: "V", who: "bolt", expr: "normal", text: "つまり……聖教会の上層部に掛け合って下層の奴隷売買における不正を暴き、不正に手に入れた奴隷の解放を求める……ということですか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、V君の言う通りです、これが私の考えた策となります" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "確かに下手に強硬手段を取るよりは穏便に事を運べそうだな……" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "凄い……流石はアカツキさんです！ありがとうございます！" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "喜ぶのはまだ早いぞ、これもそう簡単ではない、聖教会において影響力のある幹部格に｜直談判《じかだんぱん》する必要がある。そして先も述べたようにこの国の身分格差は大きい、我々のような一般人が上層の人間に話をする機会など簡単には手に入らないだろう" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "正直な話、私達のような余所者だと中層に行く事すら厳しいでしょうね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "駄目じゃねぇか" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "sad", text: "じゃあ……どうすれば……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それはこれから考えるしか無いですね……今すぐに解決する方法は思い付きません" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "残念だが我も思い付かん、だが当面の方針は決まったな、聖教会の上層に住む、聖教会の下層に直接影響を与えられる権力のある人間に｜直談判《じかだんぱん》する" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "最悪、V君の妹さんが売られてしまった後でも、聖教会と繋がっていれば購入ルートを辿って助け出すことも可能ですから、まずは聖教会と繋がるのが目標になりますね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "聖教会なぁ……クロセルにちょっかいを出した男も聖教会の奴だったし、良い印象無いんだよな……" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "十分です、最終的に妹を救い出せれば、僕は何も文句はありません、それに妹と同じように盗賊に捕まってしまった不幸な子達を助ける事にもなりますし、その方針で問題ありません、僕も出来る範囲で協力します" },
  { chara: { slot: "center", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんとも壮大な事になってきたな……人一人救うだけだってのにやり過ぎじゃないか……？" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様、救うのは一人だけじゃないよ、これが成功すれば多くの不幸な人達を救うことが出来る、見返りはそれだけで十分じゃないかな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "全く、お人好しばっかだな……" },
  { text: "因みに事件が解決するまでの間、行く宛のないVは俺達の拠点で住むことになった。クロセルの分の部屋が空いていた為、そこを使う事になったのだが……" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "てかこいつも一緒に住むのかよ……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさん彼の事がそんなに嫌なんですか……？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "子供と面倒事が苦手ってだけだ、あいつ自体を嫌ってる訳じゃない……筈だ" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "sad", text: "失礼だな……僕はちゃんと成人した大人だよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そうなのか、まぁ……その背じゃ子供にしか見えないな" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "sad", text: "うっ……気にしてるんだぞ……余り触れないでくれ……" },
  { name: "アカツキ", who: "akatsuki", expr: "blush", text: "可愛らしくて良いじゃないですか、私は小さい子の方が好きですよ" },
  { name: "V", who: "bolt", expr: "smile", text: "複雑ですが嬉しいです、ありがとうございます" },
  { text: "Vの振る舞いだが、アカツキに対して、いや正確に言えば俺以外に対しては敬語を用いて礼儀正しい。俺だけ敬われてないってことだろうか……いや、違うな。アカツキはあれでも身分のある人間だ。" },
  { text: "Vはアカツキが国王秘書であることを知っているから敬った対応をするのであろう。そうだと信じたい。" },
  { text: "俺は重い溜息を吐く。それに反してアカツキ、エル、そしてVは希望に満ちた目をしていた。彼らの顔を一瞥すると、俺は再び溜息を吐く。そして小さく口元が歪んだ。" },
  { text: "この行いは善行だ、実現すればまさに英雄だ。本当に、らしくない。この世界に来てから、俺はらしくない事ばかりしている。でもまぁ、それも悪くないと思えてきた。そんな自分に笑えてくる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ま、何をするにも一歩ずつだ、今幾ら頭を捻ったって何も出て来ないだろ" },
  { chara: { slot: "left", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、明日からに備えて今日は休みましょうか" },
  { name: "V", who: "bolt", expr: "smile", text: "明日からは公衆浴場の営業も始めるんだよね、忙しくなるなぁ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうなると自由に動けるのはヤマトさんとVさんの二人になりますね、暫くは二人で調査活動をお願いします" },
  { name: "V", who: "bolt", expr: "normal", text: "分かりました、なんとかして聖教会に掛け合う手段を見つけてきます" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こいつと二人っきりかよ……クロセルぐらい連れていけないのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "水の供給をティア様一人に任せる訳にもいきませんし……暫くはお二人でお願いします、営業に余裕が出来てきたらそちらに人員を割きますので" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あーしょうがねぇなぁ……分かったよ" },
  { chara: { slot: "right", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "よろしくね、ヤマトさん" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "正直気は乗らないが、まぁよろしく" },
  { text: "Vは帽子を外して俺に向き直ると、人懐っこい笑みを浮かべて笑いかけてくる。こういう所がどうも子供っぽくて好きになれない。｜無垢《むく》な笑顔は俺には毒だ。そういう意味ではティアの相手も中々に苦手なんだが……本人に言うと泣くので黙っている。そんな訳で、今宵は解散となった。" },
  { hide: "all" },

  /* ===============================================
     Scene 6: church_adan ― 教会 (EP61)
     =============================================== */
  { label: "ep60_investigation" },
  { fade: "out" },
  { bg: "arcadia_lower" },
  { fade: "in" },
  { bgm: "town" },
  { text: "そして翌日より、俺とVの二人での調査が始まった。俺達は聖都の酒場で聞き込みをしていた。本当は冒険者ギルドとかの方が情報収集には向いているのだろうが、この国ではギルドがほぼ機能していない為にそれは悪手、他に人が集まる場所と言えばやはり定番の酒場だ。" },
  { chara: [
      { slot: "left", id: "bolt", expr: "normal" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "酔客", text: "上層に行く方法？そりゃ聖教会の教会員になって地道に昇格するしか無いだろ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "聖教会の構成員でない人間が上層に行く方法は無いのか？" },
  { name: "酔客", text: "うーん、あるのかもしれないが俺は知らないなぁ……" },
  { name: "V", who: "bolt", expr: "smile", text: "そうですか、ありがとうございます" },
  { text: "所詮は下層で手に入る情報。期待はしていなかったが、事実、多少の成果は出ていた。" },
  { name: "V", who: "bolt", expr: "normal", text: "やっぱり聖教会の構成員で無いと上層はおろか中層にも行けないみたいだね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "だが収穫はあったな" },
  { name: "V", who: "bolt", expr: "normal", text: "さっきの人が言ってた“各層の移動は聖教会の教会を通じて行う”って奴？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁそうだ、層を渡る移動手段は分かった、最悪の場合、変装して上層に行くって手もあるしな" },
  { chara: { slot: "left", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "sad", text: "その場合は僕達は不法侵入者になるから話を聞いてもらえるかは怪しいと思うけど" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あー確かにそうか……つまり荒手は使えないと" },
  { text: "良く考えれば、単純に行くだけであればクロセルやティアの魔術で飛べば良い話だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ならどうすれば良いんだ、聖教会のお偉いさんと仲良くなる……とかか？" },
  { name: "V", who: "bolt", expr: "sad", text: "そのお偉いさんに会えないから困ってるんだけど……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なら……くそっ、どうすれば良いんだ……俺の頭じゃ思い付かんぞ……" },
  { text: "アカツキやクロセルが居れば良い案も思い付くのかもしれないが、残念ながら俺は彼女達ほど頭は回らない。ここはVを頼るしか無いか。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "お前は何か案でも無いのか？" },
  { chara: { slot: "left", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "あるよ、ここ聖都には聖教会の施設が幾つかある筈だ、次はそこを調べてみよう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "聖教会の下層って今の俺達の敵だろ？そこで調査をするのは危険じゃないか？" },
  { name: "V", who: "bolt", expr: "normal", text: "ただ聖都の上層に行きたいだけの人間と思われるだろうから、僕達の本来の狙いまでは流石に分からないはずだよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁそうか……誰もが誰も頭が回る奴ばっかじゃないしな" },
  { name: "V", who: "bolt", expr: "smile", text: "そうと決まれば早速行こうか、場所はさっき教えてもらったしね" },
  { text: "そう言うと、Vは何処からともなくメモを取り出し、俺の目の前で軽く振る。簡易的な地図のようだ。聞き込みをしながらいつの間に用意していたのだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "準備が良いな" },
  { name: "V", who: "bolt", expr: "smile", text: "僕としては元からこっちが本命だからね、下層の一般市民から手に入る情報なんてたかが知れている" },
  { text: "得意げにそう言い放つと、一人酒場の出口へと歩き出す。何故か無性に腹が立つ。俺はその苛立ちを近くの柱に吐き出す。店員と客に睨まれたが些末なことだ。俺は飛んでくる視線をぐるりと見渡しながら睨み返すと、そのままVの背に付き従うようにして店を出た。" },
  { chara: { slot: "left", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "全く、野蛮だね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "何か文句でもあるのか？" },
  { name: "V", who: "bolt", expr: "normal", text: "別に……無いよ" },
  { text: "Vは振り向きながら俺に冷たい目を向ける。それは例えるならば、“期待外れ”とでも言いたげな視線。要するに軽蔑されているようだ。別に気にはならないが。" },
  { name: "V", who: "bolt", expr: "sad", text: "強いて言えばもう少し協調性を持って欲しいかな、僕達は仲間だろ？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今だけはな、事件が解決すればもう他人だ" },
  { name: "V", who: "bolt", expr: "sad", text: "はぁ……はいはい、そうだね" },
  { text: "俺の棘のある返しにVは呆れたように溜息を吐きながら返す。そして、なんとも険悪な雰囲気のまま、俺達は聖教会の施設へと向かったのであった。" },
  { hide: "all" },

  { label: "church_adan" },
  { fade: "out" },
  { bg: "church_interior" },
  { fade: "in" },
  { bgm: "holy" },
  { chara: [
      { slot: "left", id: "bolt", expr: "normal" },
      { slot: "center", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "勝手に入って良いのか？" },
  { name: "V", who: "bolt", expr: "smile", text: "立入禁止とは書いてなかったし大丈夫だと思うよ" },
  { text: "俺とVの二人は調査と情報収集の為に聖教会の教会施設に来ていた。堂々と入り口を通り、俺達は中へと足を踏み入れる。建物の中は礼拝堂のようになっていて、綺麗かつ広々としている。下層の施設と言えど此処は聖都。聖教会の施設であるのだからこれぐらい立派な建物でもおかしくはないか。" },
  { name: "V", who: "bolt", expr: "smile", text: "一般人も多いね、これなら僕達も目立たずに済みそうだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、お前の格好はそれでも目立つと思うんだが……" },
  { text: "Vの纏っているそれは未だこの世界で見たこと無い服飾をしている。強いて分かる事と言えば、それがテレビで見るような上流階級の人間が着るような物であるという事ぐらいだ。" },
  { text: "何処かの国の貴族なのだろうか。だとしたら何故妹と二人で教国に来たんだ？何か教国に来る目的でもあったのだろうか。" },
  { name: "V", who: "bolt", expr: "sad", text: "残念ながら余裕｜綽々《しゃくしゃく》とした家族旅行では無くてね、服はこれしか持ってないんだ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なら時間のある時に買いに行かないとな、お前自覚してないだろうがその服かなり目立つぞ" },
  { name: "V", who: "bolt", expr: "smile", text: "そうだったのか……気が付かなかった、御指摘感謝するよ" },
  { text: "Vはその場でくるりと回りながら自分の姿を確認する。そして驚いたように一つ頷くと、俺に向き直り笑顔で感謝の言葉を述べた。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……変な奴だな、俺のことが嫌いなんじゃないのか？" },
  { chara: { slot: "left", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "仲間の事を嫌うわけ無いだろ？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あー……そういやお前そういう奴だったな……面倒くせぇ" },
  { text: "何とも形容し難い複雑な気持ちだ。これだから｜無垢《むく》な子供は苦手なんだ。俺の言葉に返答はなく、ただ沈黙が訪れる。しかし、そのままでは事が運ばない為、Vはやれやれと言った様子で沈黙を破った。" },
  { chara: { slot: "left", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "そんな事より……うーん、どうしようか、まずは教会に来ている一般の方達に聞き込み……" },
  { text: "そんな風にVが言葉を紡いだかと思えば、後ろに誰かの気配を感じる。殺気ではないが……" },
  { chara: { slot: "right", id: "adan", expr: "normal" } },
  { name: "？？？", who: "adan", expr: "normal", text: "此処は初めてかい？君" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……" },
  { name: "V", who: "bolt", expr: "normal", text: "教会の人……ですか？" },
  { text: "当たり前だが敵ではないようだ。振り向いてみれば、そこには教会員の白い制服を着た茶髪の男性が立っていた。俺達を外部の人間と見抜いたのか……？いや、単純にこれはVの服装のせいだろう。" },
  { text: "面と向かってみて気付いたが、とても細い目をしている。あれで前が見えてるのだろうか……柔和な笑みの男だが……何かが妙に引っ掛かる。その違和感の正体は、まだ上手く言語化出来なかった。" },
  { name: "？？？", who: "adan", expr: "normal", text: "おっと、突然声を掛けてしまってごめんね、君の言う通り、僕はこの教会の人間だ。よく来てくれたね、歓迎するよ" },
  { name: "V", who: "bolt", expr: "smile", text: "いえ、大丈夫ですよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "お前……どうして俺達が此処に来るのが初めてだと分かった？" },
  { name: "？？？", who: "adan", expr: "normal", text: "見ない顔だったから……かな、僕はこの教会の施設長をしててね、此処に来る人が誰かは大体記憶しているんだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか……勤勉な奴だな" },
  { name: "？？？", who: "adan", expr: "cold", text: "君達はこの世界の神様が誰であるかは知っているかな？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……知らないな、何か名前があるのか？" },
  { name: "V", who: "bolt", expr: "normal", text: "いや、僕の知る限り……神に名は無い、ですよね？" },
  { name: "？？？", who: "adan", expr: "normal", text: "先に謝っておくよ、すまない。この問いは神について知っているかを問う有名な問いなんだ。本当は彼の言う通り、神に名前はない。それが何故か分かるかい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺は分からん、神が教えないとかそもそも聞いてないとかそんな所じゃないのか？" },
  { name: "V", who: "bolt", expr: "normal", text: "そうですね……名前が必要ないから、でしょうか" },
  { name: "？？？", who: "adan", expr: "cold", text: "ご名答、その通りだ。唯一の存在である我らが神に名前は要らない。だって“神”の呼称が指すのは神様ただ一人だからね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほど、納得だな" },
  { name: "？？？", who: "adan", expr: "cold", text: "この教会……いや聖教会は、そんな神を崇め、祀り、そしてその意志を代行する組織なんだ" },
  { name: "V", who: "bolt", expr: "smile", text: "各地に置かれている此処のような聖教会の施設では、神の意志、教えとも言えますね、それらを布教する目的もあるんですよね" },
  { name: "？？？", who: "adan", expr: "cold", text: "まさにその通りだよ、君は詳しいんだね" },
  { name: "V", who: "bolt", expr: "smile", text: "ありがとうございます、これぐらいは当然の知識ですからね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "お前俺のこと馬鹿にしてないか？" },
  { text: "何も知らない、と言いつつ基本的な知識はしっかり抑えている辺り、なんとも騙された気分だ。そんな俺の気持ちなどいざ知らず、Vは食い気味な姿勢で言葉を続ける。" },
  { name: "V", who: "bolt", expr: "normal", text: "聖教会に入るにはどうすれば良いんですか？" },
  { name: "？？？", who: "adan", expr: "cold", text: "興味があるのかい？" },
  { name: "V", who: "bolt", expr: "normal", text: "はい" },
  { name: "？？？", who: "adan", expr: "cold", text: "聖教会の構成員を僕らは神の使徒である事から「福音使徒」と称している、そしてこの福音使徒となるには試験がある" },
  { name: "V", who: "bolt", expr: "normal", text: "その試験に受かれば福音使徒となれるんですか？" },
  { name: "？？？", who: "adan", expr: "cold", text: "そうなるね、と言っても……最初は教会に来る人に対する応対や雑務が殆ど、神の意志の代行者としての本質的な役割に就くには｜十全《じゅうぜん》な下積みが必要だ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほど、具体的に何をしたら昇格できるんだ？" },
  { name: "？？？", who: "adan", expr: "cold", text: "自分より位階の高い使徒の推薦が主になるかな、特別大きな功を奏したならば教皇直々の位階の昇格もある" },
  { name: "V", who: "bolt", expr: "normal", text: "因みにお兄さんはどのくらいの地位に就いてるんですか？" },
  { name: "？？？", who: "adan", expr: "normal", text: "僕は｜聖四位《せいよんい》という位階だよ、これでもこの教会の施設長をしているんだ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "この教会の主か、なるほどな、で……お前は中層に住んでるのか？" },
  { name: "？？？", who: "adan", expr: "normal", text: "そうだね、｜聖五位《せいごい》からは中層に住む権利を得られる、だから僕も中層に住んでいるよ" },
  { name: "V", who: "bolt", expr: "surprised", text: "上層に住むにはどのくらいの位階が必要なんですか？" },
  { name: "？？？", who: "adan", expr: "cold", text: "｜聖一位《せいいちい》以上、福音使徒の幹部格だけが上層に住む権利を得られる、上層は神が住む場所だからね、そう容易には立ち入れないよ" },
  { name: "V", who: "bolt", expr: "normal", text: "もし、上層の方に会いたい場合ってどうすれば良いんですか？" },
  { name: "？？？", who: "adan", expr: "normal", text: "それは難しいね、上層の方が降りてきて下さるのを待つか、自分が上層に立ち入れる位階になるしか無いんじゃないかな" },
  { name: "V", who: "bolt", expr: "sad", text: "そうですか……" },
  { text: "やはり此処でも結論は同じようだ。ただ“上層の人間が降りてくるのを待つ”というのは盲点だった。自分から上に行かずとも、向こうが降りてきてくれればそれで良いのだ。実際、聖都に来た当日、教皇が下層に降りてきて演説をしていた記憶がある。つまり上層の人間が下層に降りてくることもあるにはあるのだ。俺達はその機会を待てばいい。" },
  { name: "？？？", who: "adan", expr: "cold", text: "もし福音使徒となる試験を受けたいのなら、この教会で勉強をすると良い、我らが神について基本的な事さえ知っていれば、試験に受かる事自体はそう難しくないはずだよ" },
  { name: "V", who: "bolt", expr: "smile", text: "なるほど、丁寧に説明をありがとうございます、考えておきます" },
  { text: "考えておく、という文句は、要するにやんわりと断った事に違いない。Vも正攻法で上層に行くつもりは無いようだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そう言えば、その聖教会という組織の内で、自分より下の位階の奴には自由に命令出来るのか？" },
  { name: "？？？", who: "adan", expr: "cold", text: "あぁ、正確に言えば二つ以上下の位階の人に対して、ではあるけど、命令する権利とそれに付属する責任が発生する、命令に背いた場合、或いはその命令が神の意志に反した物であった場合、それは神に背いた事に他ならないから重い罪に罰せられる" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なるほどな、勉強になった" },
  { name: "V", who: "bolt", expr: "smile", text: "色々とありがとうございます、最後に貴方のお名前を聞いても良いですか？" },
  { name: "アダン", who: "adan", expr: "normal", text: "僕はアダンだ、またいつでも来てくれて構わないよ" },
  { name: "V", who: "bolt", expr: "smile", text: "分かりました、それでは改めてアダンさん、ありがとうございました、今日はこの施設の説明を聞きに来ただけなので、これで失礼します" },
  { name: "アダン", who: "adan", expr: "normal", text: "そうか、それではまたね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おい、いいのか？" },
  { hide: "right" },
  { text: "Vはアダンと名乗る男に一礼すると、そのまま俺の腕を掴んで出口へと歩いて行く。まだ調べる事がある気もするが……こいつはどうやら帰る気らしい。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ調べたいことは大方聞けたし一旦帰ってもいいか" },
  { name: "V", who: "bolt", expr: "normal", text: "ヤマトさん、アダンさんの話を聞いてどう思った？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "上層の奴が下層に降りてくるのを待つのが一番簡単な方法だと思った" },
  { name: "V", who: "bolt", expr: "sad", text: "そう……だよね……それしか無いよね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "逸る気持ちも分かるが、ミスは許されない仕事だ、気を長くして待つしか無いだろ" },
  { name: "V", who: "bolt", expr: "smile", text: "｜聖四位《せいよんい》であるアダンさんに話すのは……流石に悪手だよね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだな、それだともし｜聖五位《せいごい》以上の奴が黒幕だった場合、打つ手がなくなる" },
  { name: "V", who: "bolt", expr: "smile", text: "あの違法奴隷売買にはそれを指示している黒幕が確実に居る……そいつはそれなりの位階の人間だろうから……万全を期すには上層の人間に｜直談判《じかだんぱん》するしか無いよね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "もし｜聖二位《せいにい》以上の奴が黒幕なら詰むけどな" },
  { name: "V", who: "bolt", expr: "sad", text: "その場合は教皇、或いは更に上、神本人を頼るしかなくなるね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……無理だな、まず" },
  { name: "V", who: "bolt", expr: "sad", text: "そうだね……だからそうならない事を祈るしか無いよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ帰るか、取り敢えず聞いたことをアカツキやらクロセルに話せば何か良い案でも出るだろ" },
  { chara: { slot: "left", id: "bolt", expr: "smile" } },
  { name: "V", who: "bolt", expr: "smile", text: "アダンさん良い人だったね、僕の中だと聖教会の人って悪いイメージを持ってたから、ああいう親切な人が居るとなると少し安心するよ" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そればっかりは同意するな、俺もあいつらは嫌いだ、アダンって奴もな" },
  { name: "V", who: "bolt", expr: "normal", text: "ヤマトさんは彼のこと嫌いなの？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、嫌いだ、あいつは信用できない" },
  { name: "V", who: "bolt", expr: "sad", text: "そうか……気が合わないね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだな" },
  { text: "どうやらこいつはあの男の｜胡散臭《うさんくさ》い点に気付いていないようだ。なんとも幸せな奴である。" },
  { text: "そうして俺達は教会での調査を終え、帰路についた。" },
  { hide: "all" },

  /* ===============================================
     Scene 7: bathhouse_opening ― 公衆浴場 (EP62)
     =============================================== */
  { label: "bathhouse_opening" },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "daily" },
  { cg: "cg_bathhouse" },
  { text: "数日前より始めた公衆浴場だが、その盛況っぷりは予想を遥かに上回る物であった。教国は比較的気温が高く砂塵が多く、中でも神の住まう神聖な都市である聖都に住む人間は綺麗好きが多い。“安価で身体を清めることの出来る”施設というのは需要とマッチしていた。" },
  { chara: [
      { slot: "left", id: "akatsuki", expr: "smile" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "盛況だな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "教国には無い文化ですから受け入れられるか心配だったんですが、｜杞憂《きゆう》でしたね" },
  { text: "水が貴重なのもあり、聖都にこういった施設は他に一件も無い。良心的な価格設定に加え、珍しいと言う事から話題性もあるのだろう。" },
  { text: "結果として、開店から一週間と経たず、公衆浴場の人気はピークを迎えていた。これはアカツキも想定外だったようで、現状スペースも人手も圧倒的に足りていない。" },
  { text: "外部の人間を雇うにしろ準備期間が足りなかった。だから今だけは代わりとして、俺とVも手伝いに駆り出されているのであった。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "これだけの人気が続けば時間はかかるだろうが元は取れそうだな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そうですね、ってそんな事よりヤマトさんは用が済んだなら早く戻って下さい、ほらもう、列が乱れてますよ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "分かった分かった……" },
  { text: "三時間待ちの行列が出来る公衆浴場とか聞いたことがあるだろうか。因みに俺は無い。今俺は、そんな意味不明な行列の列整理をさせられている。Vは男湯の雑用担当らしい。この人の出入りだと、俺より忙しそうだ。" },
  { cg: null },
  { hide: "left" },
  { chara: { slot: "left", id: "el", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あー……最後尾はこっちだ、そっちじゃない、ほら、早く来いよ" },
  { name: "エル", who: "el", expr: "troubled", text: "ヤマト様……相手はお客様だからね……？" },
  { text: "最後尾の看板を片手に、適当に列整理をしていると、横から声を掛けられる。エルの声だ。声の方向に振り向いてみると、衣服やタオルの山のような物を抱えて俺の横を通り過ぎる所であった。全く仕事中だというのに俺の行動を見れるだけの余裕があるのか……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "エルか、お前も忙しそうだな" },
  { chara: { slot: "left", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "うん、だからヤマト様に付きっきりにはなれない、ごめんね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや必要ないから……早く行けよ" },
  { name: "エル", who: "el", expr: "smile", text: "分かった、じゃあ頑張ってね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "というか……Vとかアカツキなんかより過労死してそうなのはあの二人だな……" },
  { text: "因みにクロセルとティアは交代で水の供給をしている。貯水タンクは居住スペースの方から入れる地下にあり、一般の人間は立ち入れない。地下には他にも部屋があるらしいが……俺は入ったことがない。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "魔術を使うエネルギー……魔力……的なあれにも限度はあるっぽいしな、前に魔力が枯渇してクロセル半透明になってたし" },
  { text: "最も、普通の人間が魔力枯渇状態になるとどうなるのかは見たことがない。ティアにはそこまで重労働させられないしな。そんな軽い会話を挟みながら、俺達は公衆浴場の運営に尽力するのであった。" },
  { hide: "all" },
  { text: "そして……あっという間に時は流れ……ある朝、Vが俺の部屋に飛び込んできた。" },
  { chara: [
      { slot: "right", id: "bolt", expr: "sad" },
      { slot: "center", id: "yamato", expr: "surprised" },
  ] },
  { name: "V", who: "bolt", expr: "surprised", text: "ヤマトさん！" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "Vかよ、チッ……なんだよこんな早くに……" },
  { name: "V", who: "bolt", expr: "surprised", text: "なんだよじゃ無いよ！僕の妹を助けてくれるって約束はどうなったんだ！？" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人……さては忘れてたな？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "いやいや引き受けるって言ったの俺じゃないから！？アカツキだろ？クロセルもエルも賛成してたし、俺は反対した立場だからな！？" },
  { name: "V", who: "bolt", expr: "sad", text: "妹が攫われてからもう一ヶ月近く経つんですよ……？まだ妹が無事な保証なんて……" },
  { text: "突然のVの襲来に、寝起きの頭が一気に醒める。朝から迷惑な事だ。目を醒ましたのはクロセルも同じようで、隣で呆れたような声を漏らしている。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "Vとやら、気持ちは分かるが落ち着け、別に我々も何もしていなかった訳ではない" },
  { chara: { slot: "right", id: "bolt", expr: "surprised" } },
  { name: "V", who: "bolt", expr: "surprised", text: "えっ……？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ヤマト、もしかしてVに伝えていなかったのか？" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あー……ごめん、そっちは完全に忘れてた" },
  { name: "V", who: "bolt", expr: "normal", text: "どういうことですか……？" },
  { text: "商売が忙しい期間が続いたが、それでも話し合うだけの時間はあった。俺はクロセルとアカツキと相談し、一つの策を練っていたのだ。そして今日この日まで、俺達三人はその策を踏まえて動いてきたのだが……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エルに話したんだけどな、肝心のVに伝えるのを忘れてたわ……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "全くご主人は……我が説明しても良いか？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "良いぞ、任せる" },
  { name: "V", who: "bolt", expr: "normal", text: "何か良い方法が思い付いたんですか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、今の我々が持っている手札を利用して、この件を解決する最も無難な方法が一つ、ある" },
  { name: "V", who: "bolt", expr: "normal", text: "どうすれば良いんですか？" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "まず、我々の公衆浴場に来る客層がどんな物か、お前は知っているか？" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "一般人と……あ、それと聖教会の福音使徒も身を清める為に来てましたね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、その割合は決して少なくはない、恐らくだが中層、上層には水を大量に使えるような施設は無いのであろう、故に大量に水を消費する必要がある際には下層に降りてくる必要がある" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "少し前に調べてきた事だが、福音使徒の奴らは神聖な儀式の際に身を清める、その為に今までは聖都の郊外にあるオアシスを利用していた" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そう今まではそうであった、だが今は下層に公衆浴場がある、綺麗な水を山のように使える施設がな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "地から湧いてきたオアシスの水と、魔術で無から生み出した水、どちらが儀式に用いる際に有用だと思う？" },
  { name: "V", who: "bolt", expr: "normal", text: "魔術で生み出した物質には一切の｜穢れ《けがれ》や不純物が無い……つまり魔術で生み出した水の方が綺麗で有用だと言えますね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、つまり聖教会の人間としてはこの公衆浴場で使われている水を使いたい訳だな" },
  { name: "V", who: "bolt", expr: "normal", text: "綺麗な水を無償で提供する代わりに、その水が入り用の際は下層の公衆浴場まで直接来ることを条件にすれば……" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "理解が早いな、まぁそういう事だ、既に俺が聖教会に水を提供する事を交渉してきた、結果は言うまでもないな、二つ返事で了承されたよ" },
  { chara: { slot: "right", id: "bolt", expr: "surprised" } },
  { name: "V", who: "bolt", expr: "surprised", text: "つまり……後は聖教会の上層が儀式を行うのを待てば良いって訳ですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうなる、それでこの公衆浴場の評判を落とさない為にも、今は仕事に集中するべきだと思った訳だな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "全く一人で空回りしやがって、人騒がせな奴だ……" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "sad", text: "ヤマトさんが教えてくれなかったのが悪いんじゃないですか！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あいあい、反省してます" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "だが確かに時間は有限だ、いつまでもVの妹が無事な保証はない、我々が取った方法は酷く遠回りで、時間の掛かる策であることに違いはない、それは事実だ、すまないと思っている" },
  { name: "V", who: "bolt", expr: "smile", text: "いえ……大丈夫です、僕の妹もそう簡単に折れるほど弱くはないですから……きっと大丈夫なはずです……" },
  { text: "どうやらVも分かってくれたようだ。これでひとまず一件落着だろう。全く意味もなく早起きしてしまった、まだ空は暗いし……暗い？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "待て、クロセル……俺の体内時計が正しければ、もう日が昇っててもおかしくはない時間だよな？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……確かにおかしいな、待っていろ、今窓を開ける" },
  { chara: { slot: "lcenter", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "クロセルさん！開けないで下さい！" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "アカツキか、どうしたこんな朝早くに" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そこまで早くないです、それと今は静かにして下さい、窓は閉めたままでお願いします" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "どうしたのだ、アカツキ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "少しまずいことになりました……幸運にも狙いは下層じゃないみたいですが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まさかとは思うが……ついに来たのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "多分……ヤマトさんの予想であってると思います" },
  { text: "全力で走ってきたのだろう、息を切らしたアカツキは胸に手を当てて深呼吸すると、俺達を見渡し、重々しく言葉を紡いだ。" },
  { bgm: null },
  { chara: { slot: "lcenter", id: "akatsuki", expr: "serious" } },
  { se: "heartbeat" },
  { fx: "shake" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "──魔王軍の……襲撃です" },
  { hide: "all" },

  /* ===============================================
     Scene 8: airship_raid ― 聖都襲撃 (EP63)
     =============================================== */
  { label: "airship_raid" },
  { fade: "out" },
  { bg: "arcadia_lower" },
  { fade: "in" },
  { bgm: "tension" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "center", id: "yamato", expr: "serious" },
      { slot: "right", id: "akatsuki", expr: "serious" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "魔王軍が攻めてきたって……どういうことだ、教国には神の加護とやらがあるから安全なんじゃないのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "確かに神の加護では魔の者、要するに魔物や｜穢れ《けがれ》を持った魔族、魔王や悪魔などの存在の力を奪う事が出来ます" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なら！" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……こっちに来て外を見てみるが良い" },
  { text: "一体何がどうなっていると言うのだろう。俺は困惑しつつも、クロセルの元へ歩み寄り窓の外へと視線を向ける。窓の外から見えた物は、俺のよく知る飛行船その物であった。上部に気球があり、それに吊られる形で船体が付いている。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あれは……船？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "飛行する船だな、我の時代には無かった物だ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "飛行船、｜飛空艇《ひくうてい》……まぁそんな物です、前皇帝エルクの任期中に帝国が発明した最新兵器ですね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "でかいな……暗いのは此処があの船の影になってたからか……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "飛行船は帝国の兵器なんだろ？なんで魔王軍が使ってるんだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "これは推測ですが……恐らく帝国は既に魔王の支配下にあるんだと思います……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり……帝国は滅びたのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "いえ、正確に言えば……帝国は魔王の｜傀儡《かいらい》国となったんだと思います" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……待て、つまりあの飛行船に乗ってるのは……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "十中八九、帝国兵だな、王なき帝国にもはや魔王に対抗する力は無い、故に従わざるを得なかったのだろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "公国は滅びたのに帝国は生かすのか……意味不明だな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "一応……魔王にとって帝国は元々自分の国ですからね、壊すより利用する事を選んだんでしょう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "だからと言って教国を攻め込むのか……随分と強気だな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "と言っても……狙いは下層では無いみたいですね、あの飛行船の本来の使い方は爆撃機です、それを行っていないということは、ただ移動手段として飛行船を用いたのでしょう" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なら中層……いやまさか……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "もしこれが政治的戦争であれば行政の中核を担う中層を落として国の機能不全を狙う、という手もありますが……単に破壊を目的とした戦争であれば中層を狙う理由は無いですね、下層を爆撃するのが無難でしょう" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "下層、中層が狙われていないとすれば……言うまでもなく狙いは一つ、上層に住まう“神”だと言って良い" },
  { text: "クロセルが重々しくそう呟いた。俺は外に再び視線を移す。あの巨大な飛行船は確かにここ下層を無視して、空高くにある巨大な施設。上層を目指しているように見える。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "魔王は神を殺すつもりなのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "全能の魔王にとって脅威に足り得るのは神と勇者だけですから、そこを潰しに来る事自体は理に適ってると思います" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "確かにおかしな話ではないが……無謀じゃないのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "神と言っても｜仮初《かりそめ》ながら人の身体を持つ生物だ。“死”は確実に存在する" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "この世界を作った神だろ？人間の身体じゃ寿命が持たないんじゃないのか、今までどうしてたんだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "神は十歳の少年少女の肉体を借りる形で｜現界《げんかい》する、そして二十歳になるとまた新しい肉体に移るのだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "待て……その肉体の元の持ち主はどうなるんだ？" },
  { chara: { slot: "lcenter", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "sad", text: "使い捨てだよ……" },
  { text: "ここで黙っていたVが初めて口を開いた。そう言えばこいつも神について詳しかったな。そんな事よりも。Vの口から発せられた言葉が意味することの方が重要だ。それがそのままの意味なら……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "｜依代《よりしろ》になった肉体は死ぬのか？" },
  { name: "V", who: "bolt", expr: "surprised", text: "神をその身に宿しておくというのは、僕達が思っている以上に肉体に負荷をかける行為なんだ。だから十年の間、神を宿した後、使い終わった肉体は滅びる" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "これまた酷い話だな……でもそれなら、神の肉体を破壊しても次の｜依代《よりしろ》に移れば良いだけの話なんじゃないのか？" },
  { name: "V", who: "bolt", expr: "normal", text: "神の継承は魔王の継承とは違うんだ、複雑な儀式が必要、それが神の作った“ルール”だ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "神って奴は馬鹿なのか？簡単に乗り移れるような“ルール”にしておけば安全だってのに、わざわざ付け込める弱点を用意するなんて" },
  { name: "V", who: "bolt", expr: "normal", text: "僕もそう思うよ、どうしてそんなルールを作ったのか、それは神様しか知らない謎だ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……もし神が死んだらどうなる？" },
  { name: "V", who: "bolt", expr: "normal", text: "分からない、もしかしたら世界が終わる可能性もある" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ならなんとかしないとまずいだろ……本当は面倒事に関わりたくないんだがな……" },
  { chara: { slot: "right", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "駄目ですヤマトさん、魔王にとってヤマトさんは憎き宿敵、幸いにもそんなヤマトさんの所在は魔王に知られていません、ですがもし今ヤマトさんが魔王に立ち向かったら……もう私達に逃げる場所は無くなるんですよ？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "チッ……ここで指くわえて見てろってのか" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "今回ばかりはそうするしか無いだろうな、我慢しろご主人" },
  { hide: "center" },
  { text: "俺は窓の外を一瞥して小さく舌打ちをすると、ベッドに背中から倒れ込む。下層と言えど空から魔王に見つからないとは限らない。魔王軍が撤退するまで、外に出るのは危険だろう。それまでの間……特にすることもない。俺はゆっくりと目を閉じた。そして、その直後……" },
  { se: "magic" },
  { text: "エルが慌てた様子で部屋に駆け込んできた。魔王の襲撃の件なら既に聞いているが、別の案件だろうか。" },
  { chara: { slot: "center", id: "el", expr: "sad" } },
  { name: "エル", who: "el", expr: "surprised", text: "ヤマト様！大変だ！" },
  { name: "ヤマト", who: "yamato", text: "あぁもう！どうしたんだ……全く、今日は誰もが俺の部屋に慌てて駆け込んでくるな……" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……ごめんよ……" },
  { name: "V", who: "bolt", expr: "sad", text: "申し訳ないです……" },
  { name: "ヤマト", who: "yamato", text: "そんな事よりエル、何がどうしたんだ" },
  { name: "エル", who: "el", expr: "sad", text: "ティア様が……上層に向かった" },
  { name: "ヤマト", who: "yamato", text: "……本当か？" },
  { name: "エル", who: "el", expr: "sad", text: "本当、部屋にも居なかったし彼女が“勇者”であることを考えればそうとしか思えない" },
  { name: "ヤマト", who: "yamato", text: "そうか……" },
  { text: "魔王の襲撃が来た時点で、薄々こうなることは予想出来ていた。神に……そうでなくとも教国に危機が迫るとして、真っ先に呼び出されるのは勇者達だろう。" },
  { text: "過去に起きた教国を交えた戦争でも、教国の主戦力は勇者だったと言う。これは間違いなく“神の御告げ”で招集が掛かったと見て間違いないだろう。" },
  { name: "ヤマト", who: "yamato", text: "ったく……あいつを一人にする訳には行かないだろ……どうする？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "招集が掛かったのはティアだけじゃない、別の勇者も居る筈だ、ティアの事は……彼らに託すしか無いかもしれないな" },
  { name: "ヤマト", who: "yamato", text: "勇者ってニコラスみたいな奴らの事だろ！？あんな奴らにティアを任せておけるかよ！" },
  { chara: { slot: "center", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "なんだかんだ言いつつティア様の事大事なんだね、ヤマト様" },
  { name: "ヤマト", who: "yamato", text: "あ？なんか言ったか？" },
  { name: "エル", who: "el", expr: "smile", text: "何も言ってないよ、ヤマト様" },
  { text: "何故かエルが笑顔である。こんな緊急事態だと言うのに緊張感の無い奴だ。" },
  { name: "ヤマト", who: "yamato", text: "行くぞ、クロセル" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、策はあるのか？" },
  { name: "ヤマト", who: "yamato", text: "魔王に見付からないようにしつつ、ティアを連れ戻す、以上だ" },
  { chara: { slot: "right", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "待って下さい！流石に無謀です！" },
  { name: "ヤマト", who: "yamato", text: "クロセル、いけるか？" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "それがご主人の望みならば" },
  { name: "エル", who: "el", expr: "smile", text: "気を付けてね、ヤマト様" },
  { name: "V", who: "bolt", expr: "sad", text: "本当は僕も行きたい所ですが……生憎、戦闘能力は無いので……我慢します" },
  { name: "ヤマト", who: "yamato", text: "エルとアカツキも今回は留守番だ、人数は少ない方が目立たないからな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……魔王と戦いに行く訳ではない、あくまでもティアを連れ戻すだけだからな？" },
  { name: "ヤマト", who: "yamato", text: "しつこいな……それぐらい分かってる" },
  { name: "ヤマト", who: "yamato", text: "じゃあ行ってくる、すぐ戻るから待ってろ" },
  { name: "エル", who: "el", expr: "smile", text: "行ってらっしゃい" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "気を付けて下さいね" },
  { name: "V", who: "bolt", expr: "smile", text: "ご武運を" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、では行ってくる" },
  { hide: "all" },
  { text: "軽い別れを告げると、俺とクロセルの二人は拠点から出る。あの飛行船が良くない物だというのは一般人も分かっているようで、外には全く人通りがない。皆鍵を締めて家に閉じ籠もっているのだろう。" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "right", id: "yamato", expr: "serious" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "既に飛行船は上層に到着したようだな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "勇者を呼び寄せたって言っても転移魔術で呼び出すとかじゃないんだろ？間に合わずに神がやられる可能性もあるんじゃないか……？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "教国に居て空を飛べるティアが一番乗りの可能性もあるな、そうなると彼女は帝国軍の｜矢面《やおもて》に立つ事になる、彼女の魔術の腕は確かだが、実戦経験は浅い。非常に危険だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "急がないと手遅れになるな……" },
  { text: "俺は空を見上げながらそう呟いた。その時、何かを｜番《つが》えるような音が響く。そして続いて何かを引く音。方向は俺の後方。俺の様子を見てクロセルも音に気付いたようだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "下層は狙ってないって言ってたが……クロセル、やれ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ、任せろ。｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》──属性魔術……｜水弾《ウォーターボール》・｜雨《マシンガン》！" },
  { se: "magic" },
  { fx: "flash" },
  { text: "クロセルが短い詠唱を唱え終わると同時に、水滴で出来た弾丸が建物の影へと放たれる。同時に、何かを貫く鈍い音と共に、何かが倒れるドサッ……という音が響く。殺気を感じたから誰かと思えば、どうやら帝国軍の伏兵が居たらしい。この様子だと、家に閉じ籠もっているというのは正解のようだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "殺したか？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "否、首元に軽いのを撃ち込んだだけだ、殺傷性は無い" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか……帝国兵は俺達の明確な敵だ、生かすのは気が引けるが……まぁ良いだろう" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人も無駄な殺生はしたくないと思ってな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そんなことはない、俺達の｜邪魔《じゃま》をする奴は容赦なく殺せ、慈悲は要らない" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ、それがご主人の望みならばそうしよう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "伏兵は勇者がどうにかするとして、あまり下層に長居するのも面倒だな、ティアは……空を歩いて上層まで行ったのか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "空中歩行魔術は彼女の得意な風魔術だからな、間違いなく魔術で上層に行っただろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら俺達もそれに倣うか、それ以外に上に行く方法は無いしな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、転移魔法は使えない故に空を飛ばねば上層には向かえない、だが空中歩行魔術だと飛行船に見つかる可能性があるな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どうするんだよ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "透明化……とまではいかないが姿を隠す魔術ならある。｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》──属性魔術……｜風迅空歩《スカイウォーカー》──属性魔術……｜光錯迷彩《オプティカル・カムフラージュ》" },
  { se: "magic" },
  { fx: "flash" },
  { hide: "left" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "連続詠唱とか出来るのか……っておい、クロセル？何処行った？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "眼の前に居るぞ、ご主人、目をよく凝らして見るが良い" },
  { text: "クロセルが詠唱を終えたと同時に、その身が緑と白の二色の光に包まれ、そして姿が消えた。言われた通り、良く目を凝らしてみると……確かに人の形らしき輪郭が見える。これは……周囲の風景に溶け込むタイプの迷彩のようだ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "凄いな……相当近付かないと居ることに気付かないぞ" },
  { name: "クロセル", who: "crocell", text: "我に触れていればどちらの魔術も効果を得られる。手を掴むと良い、ご主人" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや……手が何処にあるのか分からない、そっちから掴んでくれよ……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うむ……そうか……残念だ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "何がだよ" },
  { text: "そんなやり取りをしていたかと思えば、俺の手がクロセルの手に触れる。すかさず俺は離さないようにその手を優しく握った。" },
  { name: "クロセル", who: "crocell", text: "よし、行くか！しっかり手を掴んでいるのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これ、味方同士でも見えなくなるのが不便だな、クロセルから俺の事も見えてないんだろ？" },
  { name: "クロセル", who: "crocell", text: "うむ！不便だから今まで使わなかった！だがこれだけ近くにいれば大丈夫だろう、では行くぞ" },
  { text: "ゆっくりと足を踏み出し、その姿を隠しながら宙を｜闊歩《かっぽ》していく。そうして俺とクロセルの二人は、上層に向かったティアを連れ戻しに上層へと向かったのであった。" },

  /* ===============================================
     Scene 9: pope_battle ― Side Story『教皇イヴ・エンド』(EP64)
     =============================================== */
  { label: "pope_battle" },
  { fade: "out" },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { bgm: "battle" },
  { comment: "視点転換: 教皇イヴ・エンド" },
  { pov: "eve_end" },
  { text: "――その頃、聖都の上層。" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "福音使徒", text: "エンド様！大変です！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "……なんだね？" },
  { name: "福音使徒", text: "帝国です、帝国軍が攻めてきました！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "……国境警備隊は何をしていたのだ" },
  { name: "福音使徒", text: "それが……帝国軍は空を飛ぶ兵器に乗って来たようで……迎撃する術が無く……" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "そうか……それなら仕方がないな" },
  { name: "福音使徒", text: "エンド様……ど……どうするんですか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "全く、慌て過ぎだよ……神に仕える者であるならば、もっと冷静に物事を考えなさい" },
  { text: "『エンド』と呼ばれる老齢の男。白い福音使徒の制服に高い帽子を被った彼こそ、聖教会のトップ。教皇イヴ・エンドである。教皇は白一色の床と壁に覆われた一室で、椅子に座りながら優雅に茶を飲んでいた。" },
  { name: "福音使徒", text: "そう……ですね……取り敢えず、敵の狙いは上層のようです、中層に救援を要請しましたが……敵の到着の方が早いかと" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "敵の狙いは……私か……或いは神様か、どちらにせよ……食い止めねばならないね" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "取り敢えず神様には“聖域”から出ないように指示を出してくれ……勇者と援軍の到着までは……まぁ私がなんとかするよ" },
  { text: "教皇は焦り一つ見せず、呑気な様子でそう告げると、カップを机の上に置き、ゆっくりと立ち上がる。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "君達は神様の護衛を頼んだよ" },
  { name: "福音使徒", text: "……分かりました" },
  { text: "教皇と話をしていた福音使徒は、その言葉を聞くと教皇に深く一礼し、早足でその部屋を後にした。" },
  { text: "後に残された教皇は、両手を上に伸ばし、伸びをすると、近くに立て掛けてあった杖を手にする。そしてそれをコツン……コツン……と地に突きながら、教皇も部屋を後にした。" },
  { se: "rumble" },
  { fx: "shake" },
  { text: "一方、上層にある聖教会の本部へと飛行船の｜錨《いかり》が乱暴に刺される。それと同時に橋が掛けられ、本部の入り口に帝国兵が雪崩込んでいく。" },
  { name: "帝国兵", text: "着いたぞ、｜錨《いかり》を刺せ！" },
  { name: "帝国兵", text: "全く人の気配がないな……本当に此処に居るのか？" },
  { name: "帝国兵", text: "魔王様が居ると言ったんだから居るんだろう……それに居なかったとしてもどうすることも出来ないしな" },
  { name: "帝国兵", text: "神を殺した奴は……本当に魔王様の｜寵愛《ちょうあい》を受けられるんだよな？" },
  { name: "帝国兵", text: "殺さないと……家族を守らないと……" },
  { text: "そのまま帝国兵が通路を進んでいくと、やがて広い広間のような場所に出た。広間の中央にある高台、男とも女とも取れない大きな子供の彫像があり、その足元に福音使徒の制服を纏った一人の人間が立っていた。" },
  { name: "帝国兵", text: "神はどっちだ！？" },
  { name: "帝国兵", text: "本当に誰も居ねぇなぁ……案外楽な仕事かもしれねぇぞ" },
  { name: "帝国兵", text: "おい待て、あそこに誰か居るぞ！" },
  { name: "帝国兵", text: "誰だ！" },
  { name: "帝国兵", text: "武器を置いてそこに｜跪《ひざまず》け！大人しくすれば命は助けてやる！" },
  { name: "帝国兵", text: "神の居場所を教えるんだ！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "はぁ……全く……神聖なこの場所で騒ぎを起こしてはいけませんよ" },
  { text: "一人の人間が、ゆっくりと振り向いた。そしてその手に持った杖を、地面に強く打ち付ける。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "私を誰と心得ているのですか、神の代行者にして忠実な側近、教皇イヴ・エンドとは私のことですよ" },
  { name: "帝国兵", text: "教皇？この国のトップじゃねぇか！神には劣るが、殺せば魔王様に褒められるぞ！殺せ！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "静粛に……と言っても聞いて貰えないんでしょうね、全く困りました……" },
  { text: "帝国兵が教皇に向かって一斉に駆け寄る。ある者は剣を向け、ある者は槍で突き、ある者は弓を構えた。四方八方からの同時攻撃。盾になってくれる者も、支援をしてくれる者も居ない。これに為す術を持つ者は、居ないだろう。──そう、彼を除いては。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……｜魔術回路構築《クリエイト》" },
  { text: "教皇は、静かに構えると、立ち向かってきた者の剣を杖で弾き、心臓を貫かんと迫る槍の一撃を後方に宙返りして｜躱《かわ》す。その動きはとても老人の物とは思えない。否、もはや人間離れしていた。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……詠唱" },
  { text: "弓から放たれた矢が四方から迫るが、教皇がくるりとその場で優雅に一回転したかと思うと、カラン……という乾いた音が幾つも辺りに響き渡る。ふと気が付けば、全ての矢は教皇の身体に届くこと無く、地に叩き落とされていた。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……レ・ラルム・アルヴァリアス・ティロワール" },
  { text: "その後も、立て続けに帝国兵が教皇の元へと迫るが、教皇は軽やかな足取りでそれら全ての攻撃をいなしていく。それは、まるで踊るかのような舞であった。" },
  { name: "帝国兵", text: "何をこんな男一人相手に手間取ってる！早く殺せ！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "──光魔術……｜神罰代行《ゴッドパニショメント》・｜神魔鎖錠《ホールロック》" },
  { se: "flash" },
  { fx: "flash" },
  { text: "その口から歌うような詠唱が奏でられたかと思えば、その場に居る教皇以外の全ての人間の天井と足元から、光の鎖が飛び出し、帝国兵の身体を拘束すると、彼らを地に伏せさせた。" },
  { name: "帝国兵", text: "これは……くっ……外れない…" },
  { chara: { slot: "center", id: "eve_end", expr: "cold" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "貴方達は神に背いた大罪人です……この魔術は貴方達の罪の重さだけその身を強く締める鎖。その罪……その罰を……その身で受け切れるでしょうか？" },
  { text: "教皇は、地に伏せた帝国兵達を見下ろしながら、笑顔でそう言い放つ。" },
  { text: "バキッ……ゴリッ……と嫌な音があちこちで聞こえ始める。同時に絶叫、悲鳴、｜嗚咽《おえつ》で間も無く辺りは｜阿鼻叫喚《あびきょうかん》の地獄絵図となる。" },
  { name: "帝国兵", text: "嫌だ！死にたく無い！うっ……い……息が……" },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "全く……此処は神聖な場所だと言っているでしょう、くれぐれも静粛に、静かに罰を受けなさい" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "？？？", who: "laplace", expr: "laugh", text: "そうでしょうか？ボクはこの悲鳴と泣き声のオーケストラ、と〜っても甘美な音色に聞こえるんですが" },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "なっ！？" },
  { bgm: null },
  { se: "slash" },
  { fx: "red" },
  { fx: "shake" },
  { text: "教皇が背後に気配を感じ、振り向こうとしたその｜刹那《せつな》、教皇の腹部から一本の剣が突き出る。" },
  { chara: { slot: "center", id: "eve_end", expr: "surprised" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "ごほっ……この私が……不覚を取りますか……" },
  { name: "？？？", who: "laplace", expr: "normal", text: "慢心しすぎですよ、ご老人、そこで眠ってて下さい" },
  { name: "イヴ・エンド", who: "eve_end", expr: "pain", text: "貴方は……あく……" },
  { name: "？？？", who: "laplace", expr: "surprised", text: "おぉ！良く分かりましたね！そうですボクは悪魔です！えっ？なんで悪魔のボクが此処に居るかって？それはですねー神のなんでしたっけ、あのー加護でしたっけ？あれの効果を、何故かこれを持ってると受けないみたいなんですよね" },
  { name: "イヴ・エンド", who: "eve_end", expr: "pain", text: "せい……け……" },
  { name: "？？？", who: "laplace", expr: "surprised", text: "喋りすぎると死にますよ？そうです聖剣です、なんでボクが使えるのか良く分からないんですけど、まぁこれを持ってる限りボクは加護のある土地でも自由に動ける訳ですよ！とんだ仕様の抜け穴ですね！この加護とかいうルール作った神様って、ガバガバなんじゃないですか〜？なんてね、あははははははは！" },
  { hide: "center" },
  { fx: "clear-red" },
  { bgm: "dark" },
  { text: "何処からともなく突如現れた黒髪の少女は、教皇の腹から聖剣を引き抜き、そのまま蹴飛ばすと、辺りをくるりと見渡す。" },
  { chara: { slot: "right", id: "laplace", expr: "normal" } },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "いやー……帝国兵だいぶ消費しちゃいましたね、囮として良くやってくれた物ですよ、それに良い声で鳴いてくれますしね☆いやーボクは嬉しいなぁ" },
  { name: "帝国兵", text: "ラプラス様……聖域の場所が分かりました、直ぐに第二部隊がやってくるので第一部隊を救出、合流したら向かいましょう" },
  { chara: { slot: "right", id: "laplace", expr: "mad" } },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "あ？あの爺さんが折角こんなに素敵な場を用意してくれたのに台無しにするつもり？あんな奴ら放っとけよ、お前とは関係ないだろ" },
  { name: "帝国兵", text: "……失礼しました、申し訳ありません" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "ま、いいや……さっさと神殺して帰ろうか、魔王様も待ってることだし" },
  { text: "ラプラスと呼ばれた黒髪の少女は、聖剣フルティンを軽く振るうと、帝国兵に促されるまま、聖教会本部の奥へと進んでいった。そして、イヴの魔術を受けた帝国兵達が助けられる事は無かった。最後の一人に至るまで。" },
  { hide: "all" },

  /* ===============================================
     Scene 10: upper_rescue ― 奪回作戦 (EP65) ◆B05
     =============================================== */
  { label: "upper_rescue" },
  { pov: null },
  { fade: "out" },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { bgm: "suspense" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "right", id: "yamato", expr: "serious" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "だいぶ近付いたな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、あの様子だと帝国兵は既に聖教会の奥に進んだようだな" },
  { text: "俺とクロセルの二人は、長い空中散歩の末に、上層へと辿り着いた。飛行船は施設の壁へと｜錨《いかり》を刺しており、施設の入り口へと桟橋が掛けられている。門らしき場所は見事にバラバラに破壊されており、帝国兵が強引に内部に押し入った事が分かる。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "飛行船の周りに数人見張りが居るな……まぁ飛行船が無いと帰れないんだしそれを守る奴が居るのは当然か" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、どうする？見張りを始末するか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、必要無い。このまま中に入ろう" },
  { text: "見張り達の意識は船の方に集中しており、門の方は警戒が手薄なようだ。これなら姿を隠したまま中に入れば見付からないと判断し、俺はクロセルにそう指示する。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "分かった、しっかり掴まっているのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かってるって" },
  { text: "俺達はそう軽く言葉を交わすと、直ぐに口を噤む。声でバレたら今までの努力が水の泡だ。そして、俺はクロセルに手を引かれるまま聖教会の本部の奥へと進んだ。この施設、外装も内装も白一色だ。" },
  { text: "恐ろしい程に掃除が行き届いており、汚れ一つ見当たらない。強いて言えば少し目に痛いのが玉に瑕か。長い廊下を進んでいくと、やがて広い場所に出る。" },
  { fx: "red" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "此処は広間か……っておい……なんだこれ……" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、声を抑えろ、まだ生きている" },
  { text: "俺達が辿り着いた広間には、地獄絵図が広がっていた。無数の帝国兵達が謎の光の鎖で全身を締め上げられ……悲痛な叫び声をあげながら……死んでいる。思わず声を出してしまったが、辺りは悲鳴に包まれており、俺達の会話はまともに聞こえていないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……酷いな" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "一思いに殺さず、拷問のような責めを受けさせながら殺すとは……なんとも悪趣味だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "これも魔術か？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、恐らく光属性の上級魔術だ、帝国兵がやられていると言うことは、教会側の魔術師の仕業だろう" },
  { text: "此処は教国の頂点に位置する組織の本部だ。高度な光属性魔術を使える魔術師が福音使徒の中に居てもおかしくはない。それにしてもこれは酷いと思う。元は｜咎人《とがびと》である俺ですら吐き気を覚えるレベルだ。" },
  { text: "この惨状にばかり目が行ってしまったが、この広間には他にも何かがある。そんな直感に従って俺は辺りを見渡す。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おいクロセル、あそこに誰か居ないか？" },
  { text: "広間の中央。謎の巨大な彫像の足元にある二つの人影を、俺は指差す。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どこだご主人" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……指差しても見えないよな、正面だよ正面、あの彫像の下" },
  { text: "それから僅かな沈黙。俺の視力では捉えられないが、クロセルであれば見えるだろう。そして、クロセルは口を開いた。" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ティアと……老人だ、何処かで見覚えがあるが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その老人は帝国兵じゃないんだな？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "服装は福音使徒の物だ、聖教会側の人間だろう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "爺さんはどうでもいい、それよりティアだ、連れ戻すぞ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ……ではまだ生きている帝国兵の意識を奪うか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "頼んだ" },
  { text: "クロセルの掌から生まれた水の球体が全方位に弾丸を飛ばし、的確に帝国兵達の急所を撃ち抜いていった。先程までの喧騒を思えば、この静寂はなんとも不気味だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "殺したのか" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "……あのまま放置しても死ぬ運命だ、一思いに殺してやった方が楽に逝けると判断した" },
  { fx: "clear-red" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか、良くやった、じゃあ行くぞ" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { text: "こいつらは敵だ。殺しても何とも思わない。良心の呵責など俺には存在しない。そう自分に言い聞かせると、俺はティアと老人の元に駆け寄った。" },
  { chara: { slot: "center", id: "tia", expr: "surprised" } },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おいティア、何してる" },
  { name: "ティア", who: "tia", expr: "surprised", text: "ヤマト！？と｜魔杖《まじょう》ね、こんな所まで来てどうしたの？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それはこっちの台詞だ。神の御告げだか何だか知らないが、俺に断らず勝手に外に出るな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我とご主人はお前を連れ戻しに来たのだ" },
  { chara: { slot: "center", id: "tia", expr: "sad" } },
  { name: "ティア", who: "tia", expr: "sad", text: "でも……私は神様に逆らえないから……" },
  { text: "ティアが申し訳無さそうな声色で俺達にそう告げると、小さく俯く。それを見て、俺は少し考えるように腕を組むと、一つ頷く。ティアに近付いていくと、その手を掴んだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なら命令だ、俺はお前を強引にでも連れ帰る" },
  { name: "ティア", who: "tia", expr: "sad", text: "うん、私の意志じゃ帰れないから……頼んだわ、ヤマト" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、俺に任せろ" },
  { name: "ティア", who: "tia", expr: "surprised", text: "あっ！でもその前に……ヤマト、この人を助けないと……" },
  { text: "ティアの足元には、白い服を血で真っ赤に染めた瀕死の老人が倒れていた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？なんだこの爺さん、白い服が血で真っ赤だな" },
  { name: "ティア", who: "tia", expr: "sad", text: "怪我をして死にそうなの……治癒魔術だけ掛けてから帰らせて頂戴？" },
  { text: "正直、見ず知らずの爺一人だ。助ける義理は無い。だが──" },
  { choice: [
      { label: "老人に手を貸す", jump: "b05_save" },
      { label: "ティアだけ連れて引き返す", jump: "b05_abandon", kind: "if" },
  ] },

  /* ---- 正史: 老人を助ける ---- */
  { label: "b05_save" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "しょうがねぇなぁ……クロセル、手伝ってやれ", tid: "ch04__b05_save__01" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", text: "うむ、我に任せておけ", tid: "ch04__b05_save__02" },
  { text: "クロセルとティアの二人で、福音使徒らしき爺さんの治療を始める。船から来た帝国兵に出会すのが怖いが、幸運にも後続は来ないようだ。それから十数分程度の時間が経った。", tid: "ch04__b05_save__03" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "老人", who: "eve_end", expr: "pain", text: "うっ……私……は……", tid: "ch04__b05_save__04" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "お、目を醒ましたか？", tid: "ch04__b05_save__05" },
  { name: "ティア", who: "tia", expr: "surprised", text: "流石は｜魔杖《まじょう》ね……あれだけ深い傷をあっという間に治しちゃうなんて", tid: "ch04__b05_save__06" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふっふ～凄いだろう、もっと褒めても良いのだぞ" },
  { name: "老人", who: "eve_end", expr: "serious", text: "君達が……私を助けてくれたのかい？", tid: "ch04__b05_save__07" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ、そうなるな、礼ならティアに言ってくれ", tid: "ch04__b05_save__08" },
  { name: "ティア", who: "tia", expr: "surprised", text: "大丈夫？お爺さん" },
  { name: "老人", who: "eve_end", text: "そうか……君達、ありがとう", tid: "ch04__b05_save__09" },
  { text: "爺さんは自分の胸元を軽く見て、そのまま立ち上がろうとするが、直ぐに姿勢を崩して膝をつく。", tid: "ch04__b05_save__10" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "無理すんな、治癒魔術は体力まで回復する物じゃない", tid: "ch04__b05_save__11" },
  { name: "老人", who: "eve_end", expr: "serious", text: "私、殆ど仕事が出来なかったし……今は無茶しないとね……神様が危ない……聖域に行かないと……", tid: "ch04__b05_save__12" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前、福音使徒だろ？他の奴らはどうしたんだ？" },
  { text: "俺は再び辺りを見渡す。だがそこに転がっているのは帝国兵の｜亡骸《なきがら》のみ。福音使徒の遺体らしき物は一つも見当たらない。まさかとは思うが……この数の帝国兵相手に一人で相討ちまで持ち込んだのか？いや、それは流石に無いか。" },
  { name: "老人", who: "eve_end", expr: "serious", text: "他の皆は聖域に避難している、無事だと良いんだけどね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前、此処で敵にやられたんだろ？その中に魔王は居たか？", tid: "ch04__b05_save__13" },
  { name: "老人", who: "eve_end", expr: "serious", text: "いや、魔王は居なかったよ、帝国兵と……悪魔が一人、それだけだ", tid: "ch04__b05_save__14" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "悪魔か……となると、俺達は此処までだな", tid: "ch04__b05_save__15" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、恐らく魔剣の悪魔だろう、奴に我々の存在を勘付かれてはいけない", tid: "ch04__b05_save__16" },
  { name: "老人", who: "eve_end", expr: "serious", text: "これは私達の問題だからね……部外者である君達を巻き込むつもりはないよ、助けてくれてありがとう、それだけで十分だ", tid: "ch04__b05_save__17" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "本当に爺さん一人で大丈夫なのかよ……", tid: "ch04__b05_save__18" },
  { text: "この弱そうな爺さん、折角命を助けてやったのに、この様子だとまた死ぬんじゃないだろうか。心配だ。それでも、俺達は着いて行けない。これは俺だけの問題じゃないんだ、アカツキやエル、ティアの為でもある。我慢するしか無い。そんな時であった。", tid: "ch04__b05_save__19" },
  { chara: { slot: "lcenter", id: "nicholas", expr: "laugh" } },
  { name: "？？？", who: "nicholas", expr: "laugh", text: "──話は聞かせてもらったよ", tid: "ch04__b05_save__20" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふむ、この声は……", tid: "ch04__b05_save__21" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "うげ……", tid: "ch04__b05_save__22" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "祝福の勇者ニコラス、又の名を｜抜刀斎《ばっとうさい》ニコンとは僕の事だ！", tid: "ch04__b05_save__23" },
  { text: "祝福の勇者ニコラス。不死身の身体を持つ、人類の希望だ。黄金の鎧に長い刀を携え、その男は立っていた。", tid: "ch04__b05_save__24" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "ヤマト君とクロセルちゃん、それにティア様も居るじゃないか、久しぶりだね", tid: "ch04__b05_save__25" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あーそうだな……久しいな", tid: "ch04__b05_save__26" },
  { text: "俺はこいつの事が苦手だ。扱いやすい男ではあるのだが、どうも好きになれない。魔王封印が失敗した際に置いていった後、何をしていたのかは知らないが、どうやらまた聖剣（笑）を新調したらしい。毎回何処から拾ってきてるんだよ。" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "僕の｜鎌矛尾羽針《かまぼこおはばり》が気になるのかい？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "別に興味ねぇよ" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "そうかい、残念だな……" },
  { name: "老人", who: "eve_end", expr: "serious", text: "祝福の勇者ニコラス様ですか……私達の神様を守る為に駆け付けて下さったのですね？", tid: "ch04__b05_save__27" },
  { chara: { slot: "right", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", text: "そう！その通りだ！僕が今度こそ……この国を！世界を！救ってみせる！", tid: "ch04__b05_save__28" },
  { text: "今度こそ、と意気込むのは失敗続きだからだな。だが、こいつが居るのならこの爺さんの身は多少安全になるだろう。こう見えてもニコラス、あいつの実力は確かだ。", tid: "ch04__b05_save__29" },
  { chara: { slot: "right", id: "nicholas", expr: "laugh" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "んじゃ勇者、爺さんと神は任せたぞ", tid: "ch04__b05_save__30" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "君達は来ないのかい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、俺達は戻る、こっちはお前と違って不死身じゃないんだ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "そうか、では任せてくれ", tid: "ch04__b05_save__31" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう、任せた", tid: "ch04__b05_save__32" },
  { hide: "center" },
  { hide: "lcenter" },
  { text: "勇者は老人に肩を貸しながら、施設の奥へと進んで行った。残された三人。目的は達成された、後は戻るだけだ。", tid: "ch04__b05_save__33" },
  { chara: [
      { slot: "center", id: "tia", expr: "sad" },
      { slot: "right", id: "yamato", expr: "serious" },
  ] },
  { name: "ティア", who: "tia", expr: "sad", text: "行かないと……ヤマト、私を止めて", tid: "ch04__b05_save__34" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かってる、あまり動くなよ", tid: "ch04__b05_save__35" },
  { text: "ティアが苦しそうな声色で震えながらそう告げる。どうやら神のお告げに逆らっているからだ。俺は手錠でティアの両腕を拘束し、手拭いを｜猿轡《さるぐつわ》にして口を塞いだ。", tid: "ch04__b05_save__36" },
  { text: "詠唱が出来なければ魔術も発動できない。これで無事に拠点まで連れ帰れれば、神の御告げには逆らえたと言って良いだろう。", tid: "ch04__b05_save__37" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "これで良し……と、暫くは我慢してくれ", tid: "ch04__b05_save__38" },
  { text: "ティアはコクコクと頷く。", tid: "ch04__b05_save__39" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ帰るか、クロセル、例の魔術を", tid: "ch04__b05_save__40" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "その手錠とやら、我の知識には無かった物だが、中々に便利だな", tid: "ch04__b05_save__41" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "本当は拘束するのも魔術で一発なんだろ？", tid: "ch04__b05_save__42" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "まぁそうだな、魔術を使った方が手っ取り早いだろう", tid: "ch04__b05_save__43" },
  { chara: { slot: "right", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", text: "いや……ほんと俺って要らないんじゃないかな……", tid: "ch04__b05_save__44" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そんな事は無いぞ、ご主人が居なければ我は現界出来ていなかったのだから、我の功績はご主人の物だ", tid: "ch04__b05_save__45" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "慰めてくれてありがとな", tid: "ch04__b05_save__46" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "全く、本当だと言うのに……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あーティア悪いな、さっさと戻ろう" },
  { text: "ティアに少し睨まれた。怒られる前にさっさと帰ろう。" },
  { text: "クロセルが魔術を発動し、空中を歩く能力を得ると同時に、その姿が消える。現在俺はティアを両手で抱き抱えている。この状態でクロセルに接触したまま動くにはどうすれば良いのだろう。", tid: "ch04__b05_save__47" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "えっと……手が空いてないんだが……どうすれば良い？……って、うぐっ……", tid: "ch04__b05_save__48" },
  { text: "背中に鈍い衝撃。クロセルが何をしたのか直ぐに察した。首元に腕の感触がある。ついでに背中にも柔らかい感触が……無かった。まぁそれもそうかと一人納得する。", tid: "ch04__b05_save__49" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセルもティアも軽くて助かったな……これなら俺でも動けそうだ", tid: "ch04__b05_save__50" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "空中歩行のやり方は分かるな？", tid: "ch04__b05_save__51" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "何度か経験してるから分かるよ、ただ段差は一定に作ってくれよ", tid: "ch04__b05_save__52" },
  { text: "ティアを抱え、見えないクロセルを背に、俺は上層の床から宙へ足を踏み出した。途中、入り口の方向から帝国兵達が走ってくるが、壁に密着するようにしてやり過ごす。どうやら見付からずに済んだらしい。", tid: "ch04__b05_save__53" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あんな数の増援……勇者や爺さんは大丈夫なのか？", tid: "ch04__b05_save__54" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "信じるしか無いだろうな、我々に出来ることはない", tid: "ch04__b05_save__55" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そうだな……", tid: "ch04__b05_save__56" },
  { text: "気が付けば、あの勇者や爺さんの事を心配してしまっている。何故だ？俺はあいつらがどうなっても何とも思わない筈なのに。", tid: "ch04__b05_save__57" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ほら、早く進むぞ", tid: "ch04__b05_save__58" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、分かった", tid: "ch04__b05_save__59" },
  { text: "いつの間に立ち尽くしていたらしい。俺は慌ててクロセルに返事を返すと、再び出口へと歩き出す。行きと同じ長い廊下を抜けると、外に出た。", tid: "ch04__b05_save__60" },
  { text: "外の空気を吸うと、少しだけ落ち着く。さっきの広間は噎せ返るような血の香りで包まれていた為、新鮮な外の空気が随分と心地良く感じる。", tid: "ch04__b05_save__61" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "いい風だな。よし、降りるぞ", tid: "ch04__b05_save__62" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ミッションコンプリートだな、完璧だ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "拠点に帰るまでが仕事だぞ、気を抜くな" },
  { text: "そんな風にクロセルに叱責されながらも、俺は地上へと降りていく。" },
  { hide: "all" },

  /* ===============================================
     Scene 11: retreat_smoke ― 作戦終了 (EP66)
     =============================================== */
  { label: "retreat_smoke" },
  { fade: "out" },
  { bg: "arcadia_lower" },
  { fade: "in" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よっこいしょ……っと" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そんな恨めしそうな目で俺を見ないでくれ……お前の為なんだから" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人、地上にも帝国の伏兵が潜んでいることを忘れるでないぞ、気を抜くな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かってる、索敵は任せるぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "なに、撃退も任せておけ" },
  { text: "ティアを抱え、クロセルを背に、長い空中散歩の末、俺達は地上に降り立った。と言っても……自由自在に空を渡れた訳ではなく、何度も躓き、転げ落ちそうになりながらの到着だ。" },
  { text: "真っ直ぐ降りてきた訳では無い為、拠点からは少し離れている。拠点に戻る途中で敵に遭遇するリスクを冒す事になるが、こればっかりは仕方ない。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そう言えば、魔王は何が目的で地上に帝国兵を配置したんだ？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "恐らく……上層に向かう冒険者の遊撃、各聖教会の施設の制圧が目的だろう、上層を孤立させる意図だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "下層から上層に向かうには聖教会の施設を経由する必要がある、そこを抑えれば上層に救援は来ない……って寸法か、それにしては兵力が心許ない気がするが" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "貴重な兵力は出来る限り上層に割きたいだろう。そもそも下層を完全に制圧する必要はない。時間を稼ぐ程度で十分だからな" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "捨て駒……って訳か……あの皇帝がやりそうな事だ" },
  { text: "今回の狙いが上層で本当に助かった。俺は心の内でそっと胸を撫で下ろす。もし魔王としての本分である、破壊を目的とした侵略を行われていたら、戦力に乏しい教国に為す術はなかっただろう。勇者の加勢を加味しても、あの飛行船による空爆が行われれば甚大な被害が出ることは容易に想像できる。" },
  { text: "教国は“魔物、魔族、陸路を除くあらゆる攻撃手段”に弱い。良く今の時代まで生き延びてこれた物だ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ、今回の魔王がイレギュラーってだけか、神も想定してなかったんだろうな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、魔王が人間を魔族とせずに従えたのは前例のない事だ。それに加えてあの空飛ぶ船。あれには立派な長城による国境防衛も意味を為さない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "正直……魔王が生まれる以前の帝国でも教国なら攻め滅ぼせたんじゃないか？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "かもしれん……帝国の軍事力は間違いなくこの世界で最高の物だと言えるからな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王に対抗出来るであろう唯一の戦力である帝国が魔王側に付いたのが痛過ぎるな。王国教国公国の三国が手を組んでも対抗出来るか怪しいだろ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "同感だな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あと、そんな事よりそろそろ降りろ、歩きにくい" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "おっと、そうだな、忘れていた" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "お前……俺が指摘してなかったらずっと背に張り付いてる気だっただろ……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "そんな事は無いぞ！" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "どうだか……" },
  { text: "何処か名残惜しそうに目を細めながら、クロセルは腕を解き、俺の背から降りる。その後も他愛のない事を話しながら歩いていた。その｜刹那《せつな》。" },
  { se: "rumble" },
  { fx: "shake" },
  { text: "ドォォン……と遠くで鈍く重たい音が響く。それは……例えるなら何かが爆発するような。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？何だ？" },
  { chara: { slot: "left", id: "crocell", expr: "surprised" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人！あれを見ろ！" },
  { text: "俺はクロセルの言う通り、音のした方向へと振り返る。音の出処は、丁度上層の辺り。上層で何かがあったのかと目を凝らすと……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "上層から煙が上がってるな……何かあったのか？" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "音から推測するにかなり大きな爆発の筈だが……遠目だとあまり施設が破壊されたようには見えない、別の何かに爆発の衝撃を吸われたか……或いは上層が相当強固な作りになっているのか……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "神が無事だと良いんだがな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人が神の心配をするとは意外だな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そりゃ誰だって世界が終わったら困るだろ、つか魔王は世界が終わるリスクを冒してでも何で神を殺そうとしてるんだ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "世界が終わらないからじゃないのか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そんな確証無いだろ……いや、魔王には確証があるってことか？あいつは神を殺したらどうなるのか知ってるのか？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "さぁな、我には分からん" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうか……まぁ仮に神が死んだとしても世界が終わらないなら別に良いか" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "本当に利己的だな……ご主人は" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "悪いか？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "否。そういう所も我は嫌いじゃないぞ" },
  { text: "遥か遠くに立ち昇る黒煙を見ていてもつまらない。興味が失せた俺は、上層の方角から目を逸らし、再び歩みを進める。" },
  { hide: "all" },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "daily2" },
  { text: "その後、道中で帝国兵に出会す事も無く、無事に俺達は拠点に戻ってくる事が出来た。" },
  { chara: [
      { slot: "farleft", id: "crocell", expr: "normal" },
      { slot: "left", id: "el", expr: "smile" },
      { slot: "center", id: "yamato", expr: "normal" },
      { slot: "rcenter", id: "akatsuki", expr: "smile" },
      { slot: "right", id: "bolt", expr: "smile" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ただいま" },
  { name: "クロセル", who: "crocell", text: "今戻ったぞ" },
  { text: "居住スペースの方に設けた入り口から中に入る。予想はしていた事だが、仲間達は俺達の帰りを玄関で待っており、帰還と同時に盛大に出迎えられる事になった。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "おかえりなさい、ヤマトさん" },
  { name: "V", who: "bolt", expr: "smile", text: "ヤマトさん、おかえり" },
  { name: "エル", who: "el", expr: "smile", text: "無事で良かった、ヤマト様" },
  { text: "アカツキ、V、そしてエル。三人共大人しく拠点で待ってくれていたようだ。懸念していた襲撃の跡も特に見られない。本当に平穏無事だったようだ。" },
  { text: "そんな風に安堵の感情に浸っていると、何故かクロセルが不機嫌そうに俺の背を突く。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "皆揃ってヤマトヤマトと……我の事は出迎えてくれないのか" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ごめんなさい、クロセルさん。改めて、おかえりなさい" },
  { name: "クロセル", who: "crocell", text: "うむ！ただいま戻った！" },
  { text: "アカツキが気を利かせて直ぐ様フォローに走る。それで満足そうに頷いているクロセルもクロセルだが。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ティアお嬢様も無事で良かったです……無事連れ戻せたんですね" },
  { name: "エル", who: "el", expr: "smile", text: "手錠に｜猿轡《さるぐつわ》……ヤマト様、なんというか……その……誘拐犯みたいだね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あ？何か文句でもあるのか？" },
  { name: "エル", who: "el", expr: "normal", text: "まぁ本人の意志に反して連れ戻したのは事実だし……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いやそれは違うぞ、こうしてるのも戻って来たのも確かにティアの意志だ、上層に行きたがってるのは神の意志だからな" },
  { name: "エル", who: "el", expr: "smile", text: "そうなんだ、それなら別に良いか" },
  { text: "俺はティアをソファに降ろし、手錠と｜猿轡《さるぐつわ》を外してやると、ぐるりと辺りを見渡す。これで俺の仲間全員が揃った。後は事が済むまで隠れていればいい。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、これで万事解決だ" },
  { name: "クロセル", who: "crocell", text: "後は神が無事なことを祈るばかりだな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "まぁ勇者も居るし大丈夫だろ……帝国兵と言えど所詮は人、勇者を再起不能なまでに叩きのめせる実力者はまず居ないんじゃないか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "勇者……ってもしかしてニコラスさんですか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……そうだ、神の御告げを聞いて我先にと駆け付けたみたいだぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そうですか……ニコラスさんらしいですね……" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "懸念するべきは悪魔か……あいつの実力は未知数だからな……" },
  { chara: { slot: "rcenter", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "私の分析だと、そこまで強くは無かった筈ですが……何らかの特殊能力を持っているみたいなので、危険な相手ではありますね" },
  { name: "クロセル", who: "crocell", text: "皇帝の未来視が魔剣の力による物だとしたら、あの悪魔も同じ力を使える可能性はあるな" },
  { text: "俺はあの悪魔に良いイメージを持っていない。寧ろ最低で最悪な宿敵の一人だ。機会さえあれば是が非でも殺してやりたいとすら思う。だが残念な事に、俺には傷害のディザビリティがある故、直接手を下すというのは絶対に出来ない事だが。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今回の襲撃、魔王は来てないんだよな" },
  { name: "クロセル", who: "crocell", text: "うむ、魔剣の悪魔と帝国兵だけだな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "まぁそれなら勇者の頑張り次第で何とかなりそうだな……よし" },
  { text: "俺は手を叩き、決心した様子で大きく頷くと、自分の部屋へと歩いて行く。" },
  { name: "クロセル", who: "crocell", text: "ご主人、どうしたのだ？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "疲れたから俺は寝る！何かあったら起こせ！" },
  { chara: { slot: "rcenter", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "現在進行系で聖都が襲撃を受けてると言うのに危機感無さ過ぎないですか……？まぁ良いですけど……" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様、おやすみ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "おう、おやすみ" },
  { text: "アカツキには呆れられ、エルは苦い笑みを浮かべて俺に手を振る。そしてクロセルが、慌てた様子で俺の背中に着いていくる。そんな仲間達を俺は軽く一瞥すると、小さく笑って俺はベッドに向かった。" },
  { hide: "all" },

  /* ===============================================
     Scene 12: sanctuary_defense ― Side Story『聖域』(EP67)
     =============================================== */
  { label: "sanctuary_defense" },
  { fade: "out" },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { bgm: "tension2" },
  { comment: "視点転換: 聖域" },
  { pov: "eve_end" },
  { name: "福音使徒", text: "此処より先は神聖なる聖域である！不敬なる侵略者よ！近付くな！" },
  { name: "帝国兵", text: "これは結界か？" },
  { name: "帝国兵", text: "みたいだな……斬っても突いてもびくともしねぇ" },
  { text: "聖教会の本部は全ての外装、内装、｜調度品《ちょうどひん》が白色で統一されている。それは神に仕える福音使徒達が潔白である証明。だが、そんな本部に、唯一白色以外が使われているエリアがある。その名も、聖域。" },
  { text: "神の使徒が清廉なる白色であるならば、神は何色なのであろうか。答えは無色である。神は黒ではなく、白でもない。何色にも染まらぬ唯一にして無二の存在。故に神の過ごす聖域では、全ての物が無色透明で統一されているのだ。" },
  { text: "十数人の福音使徒が一つの椅子を取り囲んでいた。その中央に座す少女こそ、神である。この世界を生み出した唯一神。創造神。神はこの緊迫した状況下でも、酷く冷静に冷たい瞳で｜虚空《こくう》を見つめていた。" },
  { name: "福音使徒", text: "神様、御安心下さい、貴方様の事は私達が全力で守ります、命を懸けて" },
  { name: "福音使徒", text: "結界を張り続けろ！絶対に破られるな！" },
  { name: "福音使徒", text: "無茶を言わないで下さい！維持するのが限界です！" },
  { name: "帝国兵", text: "結界を張ってるのは一人だけだ！魔力が尽きるまで叩きまくれ！" },
  { name: "帝国兵", text: "応援が来る前に結界を突破すれば俺達の勝ちだ！" },
  { text: "使徒の内の一人が、聖域を取り囲むようにして巨大な結界を張っていた。だが所詮は一人の力。あらゆる武器、手段で傷付けられ続ける結界の修復、維持が限界であった。そしてそれも……有限。彼の魔力が尽きれば、後は帝国兵達が福音使徒、そして神を｜蹂躙《じゅうりん》するだけである。" },
  { chara: { slot: "right", id: "laplace", expr: "sulk" } },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "全く……まーだ壊せないんですか？" },
  { name: "帝国兵", text: "ラプラス様、それがこの結界を張っている福音使徒、中々にしぶといようで……" },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "もー焦れったいですねぇ……早くどうにかしてくださいよー" },
  { name: "帝国兵", text: "後少しで破れると思いますので、どうか暫しお待ちを……" },
  { text: "聖域の入り口に突撃する帝国兵達を遠目に見守る黒髪の少女。片手には光り輝く剣を携え、それを｜気怠《けだる》げに振り回しながら、話し掛けてきた帝国兵にジト目を向ける。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "聖剣で突いたら一発だったりしないですかねぇ……" },
  { text: "少女がそう呟いたかと思うと、その瞳が一瞬、青く光る。そして何かを悟ったかのように溜息を吐いた。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "ダメみたいですねー……無駄なことはしたくないし此処は帝国兵の皆さんに任せますよ、ちゃっちゃとやっちゃって下さい" },
  { text: "それから暫しの時が流れた。今まで奇跡的に維持されていた結界が、ついに限界を迎える。" },
  { name: "福音使徒", text: "すい……ません……神様……" },
  { se: "rumble" },
  { fx: "shake" },
  { bgm: "battle" },
  { text: "結界魔術を張っていた男が意識を失い、倒れ込むと同時に、聖域を取り囲んでいた結界がガラスの割れるような音と共に弾ける。こうして、兵達と神を隔てる壁はなくなった。" },
  { name: "帝国兵", text: "今だ！突撃！福音使徒を殺せ！" },
  { name: "帝国兵", text: "俺が一番乗りだ！" },
  { name: "帝国兵", text: "うおおおおおお！神！殺す！" },
  { text: "勝利を確信した、嬉々とした声が飛び交う。帝国兵達は我先にと神の座する場所へ突っ込んでいく。──その時の事であった。" },
  { name: "帝国兵", text: "いてっ……なんだ……" },
  { name: "帝国兵", text: "突然目の前に壁が現れたぞ！？" },
  { name: "帝国兵", text: "これは……結界！？くそっ、結界魔術を使う奴は倒れた筈じゃ！？" },
  { text: "帝国兵達の眼の前に、再び結界が展開される。しかし、その術師は福音使徒達の中には居ないようで、使徒達は何事かと目を丸くして辺りを見渡す。" },
  { name: "？？？", text: "どうやら……何とか間に合ったみたいですね" },
  { name: "帝国兵", text: "誰だ！？" },
  { se: "slash" },
  { text: "鞘から刀を引き抜き、再び鞘に納刀する音が静かに奏でられる。全工程、一秒にも満たず。凡俗な人間には、それがただ刀を抜き、収めただけの動作に見えただろう。振り向いた帝国兵達の急所から突如血が吹き出たかと思えば、そのまま一斉に倒れた。" },
  { chara: { slot: "left", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "ふふっ……またつまらない物を斬ってしまったね" },
  { name: "帝国兵", text: "な……一瞬でこの数の兵を……" },
  { text: "倒れた帝国兵達の前に立っていたのは、容姿端麗な黄金の剣士。剣士はふっと小さく笑うと、再び刀を鞘から抜き放ち、帝国兵に突き付けながら言葉を続ける。" },
  { chara: { slot: "left", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "僕が！僕こそが！人斬り｜抜刀斎《ばっとうさい》ニコンだ！ばばーん！" },
  { text: "その姿はまさしく英雄。勇者と呼ぶに相応しい出で立ちであった。しかしその本性は、黙っていれば格好良い残念な男である。そしてその男の後ろから、コツン……コツン……と何かを突く音。" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "皆さん遅れてすいません、でも間に合ってよかった" },
  { text: "剣士の横に現れたのは、慈愛に満ちた優しい笑顔を浮かべる高齢の男性。しかし、その白い制服は鮮血で紅く染まっており、本来なら安心感を齎す筈である笑顔さえ、恐怖を掻き立てる。" },
  { text: "事実、その感想は間違っていないとも言える。本質的に、この老人は恐ろしい男だ。この男の笑顔の裏には、その純白の装束で隠された闇がある。" },
  { text: "この男の本性、それは罪は罰を以て断罪されねばならないと狂信する異常なまでの｜嗜虐性《しぎゃくせい》。神が全てであり、その教えが法律よりも重い教国。そんな国を統べるトップとしては、必要以上なまでに素質はあると言えるだろう。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "さて、どうしたものでしょう……神に背き、その御身に｜刃《やいば》を向けた罰、死よりも重い罰でしか裁けませんね" },
  { chara: { slot: "right", id: "laplace", expr: "mad" } },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "あぁ……ボクも詰めが甘いですね、苦痛に苦しむ姿を眺めたりせず、さっさとトドメを刺しておけば良かった、これはボクの失敗だなぁ……ごめんなさい魔王様" },
  { text: "ラプラスの瞳が青く光り輝く。未来視。そのまま少女は駆けるようにして教皇の｜懐《ふところ》へと一気に距離を詰めた。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "──もう一度殺してあげます☆" },
  { fx: "flash" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "させないよ" },
  { text: "それとほぼ同時に。勇者が教皇の前に躍り出たかと思えば、刀を振り上げ少女の剣を弾き上げる。だが──" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "まぁ君ならそうするよね！ボクは分かってる！君の未来と死が見える！だからこの勝負、ボクの勝ちだ！" },
  { text: "少女は剣に体重を乗せたまま宙へと飛び上がり、宙返りをする形で勇者の胸元を蹴り上げた。" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "うぐっ……軽いね、そんな攻撃じゃ僕は……" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "あはははは！喋ってる余裕なんて無いですよ！？" },
  { text: "少女はそのまま着地したと同時に怯んだ勇者に向けて回し蹴りを放つ。" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "っ……" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "まだまだ！" },
  { text: "少女の｜体躯《たいく》もあり、大して威力は乗っていないが、姿勢を崩すには十分過ぎる攻撃が二発通った。既に勇者は構えを崩され、勝負は勇者の防戦に傾いていた。" },
  { text: "続いて少女は剣を回しながら握り直すと、そのまま体重を乗せて勇者に斬り掛かっていく。一瞬もの間に行われる幾度もの｜剣戟《けんげき》に金属音が幾重にも重なって響く。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "さて、そろそろ終幕ですよ" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "くっ……僕の動きが完全に読まれている！？" },
  { text: "勇者も攻勢に転じようと必死にチャンスを伺うが、少女はその隙を一切勇者に与えることはなかった。そして、この勝負は早くも最終幕へと移る。" },
  { fx: "shake" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "ジ・エンドです、勇者さん" },
  { chara: { slot: "left", id: "nicholas", expr: "depressed" } },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "がはっ……僕が……負ける……？僕は……祝福の勇者……ニコラス……だぞ……｜抜刀斎《ばっとうさい》……なんだぞ……" },
  { se: "slash" },
  { fx: "red" },
  { text: "少女の剣が勇者の身体を｜鎧《よろい》の上から大きく斬り裂く。勝負を決する、深い一撃が入った。勝敗は付いたと言って良いだろう。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "死ね" },
  { text: "力尽き、膝をついた勇者の胸に、少女は剣を深々と突き刺し、乱雑に引き抜く。そして、勇者は力なく地面に転がった。" },
  { hide: "left" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "あは？教皇の護衛のつもりだったんでしょうが、随分と弱いですねぇ……こんなのボクと魔王様に掛かれば雑魚ですよ雑魚" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "君の罪は重すぎる、とても私では裁ききれない程に……" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "無理しないでくださいよ〜ボク知ってるんですよ？貴方が何故ボクと勇者の戦いに加勢しなかったのか。貴方、結界を維持するのに全力で戦う余裕なんて無いんですよね？あはははは！なんて無駄な事を！" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "貴方を守る人が死んで、貴方が死ねば、結界を張って必死に稼いだ時間も水の泡。だって全員死ぬんですから！もし貴方がお仲間の福音使徒と神様を捨てて、勇者と結託してボクに挑めば、勝機もあったろうに！あはははは！馬鹿ですねぇ！" },
  { fx: "clear-red" },
  { chara: { slot: "center", id: "eve_end", expr: "cold" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "cold", text: "君は……何か勘違いをしているようだね" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "は？ボクが勘違い？何が違うって言うんです？ボクはただ真実を述べたまで、この先の未来はボク達の勝ちで確定してい……" },
  { text: "顔を大きく歪めながら嘲笑を浮かべる少女の瞳が、再び青く光る。" },
  { chara: { slot: "right", id: "laplace", expr: "surprised" } },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "は？嘘だろ？こんな未来……こんな未来があるなんて！？嘘だ！ボクは認めない！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "やっと分かったようですね、私は結界を維持するのに全力を尽くしていた訳ではありません、悪魔さん" },
  { name: "ラプラス", who: "laplace", expr: "surprised", text: "やめろ……嘘だ！？勇者と戦う前は……ボクの勝利の未来があったはずだ！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "えぇ、そうでしょう。貴方が勇者と戦わずに、何らかの手段で私を先に仕留めていれば、貴方達の勝利は確定していた" },
  { chara: { slot: "right", id: "laplace", expr: "mad" } },
  { name: "ラプラス", who: "laplace", expr: "mad", text: "あぁァァァァァ！？くそっ！ボクは！今からでも、未来を変えてやる！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "無駄です、全行程終了……──光魔術 ｜神罰代行《ゴッドパニショメント》・｜神魔封印《ホールロック》・｜時空牢獄《タイムプリズン》" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "｜魔術回路改竄《カスタマイズ》！｜略式詠唱展開《ファストキャスト》！──闇魔術 ｜虚空吸引《ブラックホール》！" },
  { fx: "flash" },
  { se: "explosion" },
  { fx: "shake" },
  { hide: "right" },
  { text: "教皇の詠唱が終わると同時に、少女の頭上と足元から光の鎖が現れ、足元の異空間へと引きずり込もうとする。だが対抗して詠唱した少女の魔術も同時に発動した。周囲の物質を吸引し、飲み込む魔術。それを自分の目の前に展開し、教皇の魔術に対抗しようとしたのだ。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "出来もしない略式詠唱魔術……無茶をしましたね……これだけ不安定な物質を生み出したりなんかしたら……" },
  { text: "教皇は呆れたように溜息を吐く。そして今にも異空間へと飲み込まれようとしている少女に背を向け、自らの作った結界の内側。聖域へと歩いて行く。それを阻止しようと帝国兵が教皇を襲うが、彼はその手に持った杖一本で、兵士達の攻撃を軽くいなし、そのまま悠々と突き進んでいく。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "まぁ、こうなるでしょうね……" },
  { text: "不安定な魔術により生み出された物体は、周囲の物質を無作為に吸収しながら膨張し、最終的に大爆発を起こした。後に残ったのは無残な帝国兵達の｜亡骸《なきがら》と、ぽっかりと空いた異空間への穴。穴はゆっくりと閉じ、やがて辺りは静寂に包まれる。" },
  { bgm: "holy" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "さて……皆さん無事ですか？" },
  { name: "福音使徒", text: "エンド様！助かりました！貴方が居なければ今頃どうなっていたか……" },
  { name: "福音使徒", text: "流石は教皇、やはり神を守れるのは貴方様だけです" },
  { name: "福音使徒", text: "神様も、お怪我はないですか？" },
  { text: "“神”と呼ばれた少女が、椅子に座ったまま小さく頷く。それを見て教皇は安心したように笑顔を浮かべると、杖をトン、と地面に打ち付ける。すると、辺りを覆っていた白い結界が解かれ、宙に光となって消えていく。" },
  { name: "福音使徒", text: "エンド様……結界を外すんですか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "えぇ、もう脅威は去りましたからね。ほら、あそこを見てみなさい" },
  { text: "そう言いながら教皇は透明な床の一点を指差す。福音使徒が促されるままにその場所を見てみると、そこには中層から転移してきた聖教会の兵士と勇者達の姿があった。" },
  { name: "福音使徒", text: "やっと応援が来てくれた……助かった……私達は助かったんだ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "えぇ、ですから安心なさい、後は教国兵と勇者の仕事です、貴方達は早速ですが今回の襲撃の後処理に取り掛かって下さい、また忙しくなりますね" },
  { name: "福音使徒", text: "承知しました、エンド様、すぐに取り掛かります" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "神様、勇者を遣わせてくれてありがとう御座います、彼が居なければ今頃危ない所でしたからね" },
  { text: "教皇はそう言いながら神様に笑い掛ける。神と呼ばれる少女は、それに応えることこそ無かったが、教皇を見て、小さく笑った……ような気がした。" },
  { name: "福音使徒", text: "あの…エンド様、彼って生きてるんですか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "あぁ……祝福の勇者だね、半分以上が骨しか無い死体に見えるけれど……数日経てば元に戻るよ、医務室に運んであげなさい" },
  { text: "祝福の勇者。ああ見えても今回の一件に関しては彼も功労者だ。彼が時間を稼いでくれなければ教皇は大規模魔術を発動できなかった。それはつまりあの悪魔を仕留める事が出来なかったという訳でもあり、その場合、教皇を含め彼らは無事では居られなかっただろう。" },
  { name: "福音使徒", text: "エンド様！｜飛空艇《ひくうてい》！撤退していきます！" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "そうか、援軍が下の階も制圧してくれたようだね、これで本当の意味で一息つけるよ" },
  { text: "今回の功労者は祝福の勇者の他にまだ居る。それは死にかけていた教皇を助けてくれたあの少女達だ。彼女達が居なければ、教皇は今頃死んでいたのだから。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "なんというか……全ての歯車が上手いこと回って何とか難を逃れた。そんな気がしますね" },
  { name: "福音使徒", text: "何を言ってるんですか、エンド様の尽力が全てですよ、貴方が居なければ私達、そして神様が生き延びることは出来なかった、本当に感謝しています" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "そう言って貰えると私も嬉しいよ、ありがとう" },
  { text: "辺りが騒がしくなり、再び上層にも活気が戻ってきたという所。教皇はあることを考えていた。それは、今回の襲撃は魔王の本気ではなかったと言うこと。帝国の持つ飛行船は二桁、兵士は七桁。" },
  { text: "今回の襲撃は飛行船一隻、兵士数千人だけ……規模が小さすぎる。此方の戦力を図る為の襲撃と考えるのが妥当だ。本当の襲撃が来るのは、時間の問題だと。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "間に合いますかねぇ……まぁ、やるしか無いんですが" },
  { text: "魔王軍に対抗できる戦力を用意する。それは今の教国には無茶な話だ。だが、それでもやるしかないのだ。教皇イヴ・エンドは教国を導く者。守る者であるのだから。" },
  { hide: "all" },

  /* ===============================================
     Scene 13: pope_meeting ― ｜直談判《じかだんぱん》 (EP68)
     =============================================== */
  { label: "pope_meeting" },
  { pov: null },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "daily" },
  { text: "帝国兵により制圧された下層の教会施設の速やかな鎮圧によって、勇者と教国兵の援軍が上層に到達。上層での援軍と帝国兵隊の数時間に渡る交戦。その軍隊の壊滅を以て、飛行船は上層を発ち、帝国軍は撤退に追い込まれたのであった。そして、教国には再び、平和が訪れたのであった。" },
  { text: "一方その頃。襲撃が終わり、一段落ついた所で、俺とクロセルとアカツキの三人は、今後について話し合っていた。" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "center", id: "yamato", expr: "serious" },
      { slot: "right", id: "akatsuki", expr: "serious" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "以上が今回の襲撃の概要ですね、聖教会の発表ですがヤマトさんの言ってた話とも特に食い違う点はありませんし、間違いないと思います" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "教国は追撃しなかったのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "帝国……いや魔王軍の飛行船の速力には教国の持つ移動手段じゃ追い付け無い上に、国境を超えられたら追跡は困難ですからね、追撃が出来なかったのは妥当でしょう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なんとも奇妙だよな……結局、魔王軍は何がしたかったんだよ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "神の抹殺……で間違いないだろうが、明らかに今回は戦力を抑えての襲撃だったな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、クロセルさんの言う通り、あれはどう考えても魔王軍の全力では無いですね、教国の戦力を図る為の襲撃……であったと考えるべきかもしれません" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "教国が何らかの“奥の手”を持ってることを想定して、石橋を叩いて渡る手段に出た訳か、魔王の奴も中々に慎重だな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まぁ、仮にそういう意図だとすれば今回の襲撃は成功だと言っていいでしょうね。兵に多少の損害が出たとしても、教国の戦力情報を無事に持ち帰れた訳ですから" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "今回のが本気じゃなかったなら、襲撃には“次”があるってことだよな。そしてその次こそは相手も全力を出してくる、となると神が殺されるのは時間の問題か……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "教国の取れる対抗策としては……他国の協力を仰ぐか、此方から打って出て魔王を討つ事ぐらいですかね" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "教国は今まで頑なに外交を断ってきた国だから前者は望み薄、後者は無謀としか言いようがないな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "同感です、後はそうですね……神様が動いて“奇跡”を起こしてくれることを祈る事ぐらいでしょうか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "今回もそうだが神って奴は何考えてるんだ……今回神がやった事と言えば、自分の身を守る為に勇者を呼び寄せたぐらいだろ？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "神も自由にその権能を使える訳じゃないのかもしれないですね……私達人間のように自由には動けないのかもしれません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "或いは……神は“意志がない人形”だったりしてな。最低限の自衛本能と条件付けされた行動しか取れないロボットみたいな奴なのかもしれない" },
  { chara: { slot: "right", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ロボット……？待って下さい、神に意志がなければ“神の意志を代行”する聖教会の存在が矛盾します" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "聖教会が本当に“神の意志を聞き届けている”とは言い切れないだろ？もしかしたら自分勝手に神の意志とやらをでっちあげて、好き勝手やってるのかもしれない" },
  { chara: { slot: "right", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "確かに……一理ありますけど……流石にそんな筈は……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "無いとは言い切れないだろ？" },
  { text: "アカツキが何かを言いたそうに口を開くが、その口から言葉が紡がれる事は無く、束の間の沈黙が訪れる。クロセルはロボットの意味が分からないようで、頭の上にクエスチョンマークを浮かべながら、小さく首を傾げている。少し可愛いから放っておこう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ、取り敢えず今回の襲撃について考える事はこんなもんだろ、それよりだな……クロセル" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "……ん？何だご主人" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "上層に行った時、クロセルとティアの二人で死にかけてた爺さん助けたよな？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "あぁ、助けたな、覚えているぞ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あいつが誰だか思い出した。何処かで見たことあると思ったんだよ、クロセル、お前も見てる筈だぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "思い出せないな、あの老人は誰なのだ？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "教皇だよ。あの……なんだ……イヴェンとか言う奴" },
  { chara: { slot: "right", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "イヴ・エンドですよ……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そうそう、そいつだ、そいつだったんだよ" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "あぁ！思い出したぞ、聖都に来た初日に下層で演説をしていた老人！" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうだよ、思い出したな、んで……俺達は教皇様を助けてやった訳だよな" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人……まさか……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ、俺達には教皇と話をする大義名分が出来た、何しろ命の恩人だからな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん……教皇を助けたんですか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや俺じゃなくてクロセルとティアが……だけどな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うむ、助けて正解だったな！" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、あの時は時間の無駄だと思ったが、やっぱり善行には善果がある物だな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "というかヤマトさん、重傷の老人を見捨てようと思ってたんですか…" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "結果的に助けたんだから別に良いだろ" },
  { text: "アカツキが俺に冷たい視線を送る。俺はそっとアカツキから目を逸らして、言葉を続けた。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうと決まれば早速教皇に会いに行くか" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "Vも連れて行くべきだな、下層で起きている聖教会の汚職については彼が一番詳しい" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私も着いていきます、クロセルさんが居るので大事にはならないと思いますが……念の為です" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ってことはエルとティアは留守番か……あの二人を残すのは嫌な思い出があるんだよな……" },
  { text: "前に帝国で二人に留守を任せた際、エルは深手を負いティアは誘拐された。もうあの黒ずくめが追ってきてはいない事は分かっているが、やはり怖い物はある。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "まぁ大丈夫だろ……行くぞ" },
  { hide: "all" },
  { fade: "out" },
  { bg: "church_interior" },
  { fade: "in" },
  { bgm: "holy" },
  { text: "慎重になり過ぎては駄目だと、覚悟を決める。そして俺達は、クロセル、V、アカツキの三人を連れて、以前訪ねた事のある聖教会の施設に向かった。" },
  { chara: [
      { slot: "farleft", id: "crocell", expr: "normal" },
      { slot: "left", id: "akatsuki", expr: "normal" },
      { slot: "center", id: "yamato", expr: "normal" },
      { slot: "rcenter", id: "bolt", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "此処が教会ですか……やっぱり神聖な感じがしますね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか？俺は何も感じないな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "さて、取り敢えずこの施設で一番偉い奴……を……" },
  { name: "V", who: "bolt", expr: "surprised", text: "居たよ！あそこ、アダンさんだ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、そう言えば此処の一番偉い奴ってアダンって奴だったか……気が滅入るな" },
  { name: "V", who: "bolt", expr: "normal", text: "ヤマトさん、アダンさんって人の事が苦手なんですか？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁな" },
  { chara: { slot: "right", id: "adan", expr: "normal" } },
  { text: "Vが駆け寄り、近くを歩いていたアダンに声を掛ける。" },
  { name: "V", who: "bolt", expr: "smile", text: "お久しぶりです、アダンさん" },
  { name: "アダン", who: "adan", expr: "normal", text: "おっと、また来てくれたんだね、歓迎するよ" },
  { name: "V", who: "bolt", expr: "normal", text: "今日はアダンさんにちょっとお願いがあるんです" },
  { name: "アダン", who: "adan", expr: "normal", text: "なんだい？僕で良ければ聞かせて貰うよ" },
  { text: "糸のような細い目でニコニコと笑顔を浮かべるアダンは、Vに向き直ると、腰を落とし、視線を合わせる。そして、俺達が近付いていくと、アダンは俺達の方に視線を移す。" },
  { name: "アダン", who: "adan", expr: "normal", text: "……こないだ一緒に来ていた彼かい？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだよ、俺だ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私はアカツキです" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我はクロセルだ" },
  { name: "アダン", who: "adan", expr: "normal", text: "お友達と一緒に来てくれたんだね、それで……お願いってのは何だい？" },
  { name: "V", who: "bolt", expr: "normal", text: "実は此処に居るヤマトさんとクロセルさん、先日の襲撃で教皇の命を救った、恩人なんです" },
  { name: "アダン", who: "adan", expr: "normal", text: "それは……本当なのかい？つまりヤマトさんとクロセルさんは勇者なのかな？" },
  { text: "その質問に対し、俺は言葉に詰まる。例え緊急事態であったと言えど、上層に無断で立ち入った事は罪だ。そんな根本的な事を俺は失念していた。だが、勇者が上層に立ち入ったともなれば話は違う。上層に勇者を呼び寄せたのは間違いなく神の意志だ。つまり勇者であれば上層に立ち入っても問題無かったという訳だ。となれば……答えは一つ。" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あーまぁ……そんな所だ、な？クロセル" },
  { chara: { slot: "farleft", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ、我は勇者だからな、怪我をして死にかけていた教皇を治癒魔術で助けてやったのだ" },
  { chara: { slot: "right", id: "adan", expr: "normal" } },
  { name: "アダン", who: "adan", expr: "normal", text: "そうなのか、それは凄いね……エンド様、教皇はそれを知っているのかい？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "知っている筈だ。だから話をしたくてな、俺達が教皇と話せるように上に掛け合ってくれないか？" },
  { name: "アダン", who: "adan", expr: "normal", text: "うーん……分かったよ、エンド様の命の恩人の頼みとなれば、断れないね。分かった、僕に任せてくれ" },
  { name: "V", who: "bolt", expr: "smile", text: "ありがとうございます！" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "助かります" },
  { name: "アダン", who: "adan", expr: "normal", text: "君達の住んでいる場所は？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "聖都にある唯一の公衆浴場って言えば分かるか？" },
  { name: "アダン", who: "adan", expr: "cold", text: "あぁ、聖教会に水の提供をしてくれているあの施設だね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かるなら話が早いな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "教皇が下層に降りてきて下さるんですか？" },
  { name: "アダン", who: "adan", expr: "cold", text: "そうなるかな、一般人を上層に立ち入らせる訳にはいかないからね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあそういう訳で、頼んだぞ" },
  { name: "アダン", who: "adan", expr: "cold", text: "エンド様を助けてくれたのはヤマトさんとクロセルさんの二人であってるね？" },
  { name: "V", who: "bolt", expr: "normal", text: "大丈夫です、あってます" },
  { name: "アダン", who: "adan", expr: "cold", text: "分かった。それじゃあ任せてくれ、エンド様が降りてくるまで少し時間が掛かると思うから、それまでこの教会でゆっくりしていてくれるかな" },
  { name: "V", who: "bolt", expr: "smile", text: "分かりました、お願いします" },
  { name: "アダン", who: "adan", expr: "cold", text: "うん、じゃあ行ってくるよ" },
  { hide: "right" },
  { text: "アダンは施設の奥へと歩いて行く。後は待つばかり。俺達は近くの椅子に腰掛け、雑談に興じることにした。" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それにしても嘘ついて大丈夫だったんですか……？" },
  { chara: { slot: "center", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "バレなきゃ問題無い、相手の才能が分かるのは分析の才能持ちだけだろ？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "仮にバレたとしても我々が命の恩人な事に変わりはない。心の広い教皇なら許してくれると信じよう" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そうだと良いんですけどね……" },
  { text: "アカツキが何処か憂いを帯びた目でそう呟いた。" },
  { hide: "all" },
  { text: "そして、そんな風に話をしている内に、数時間が経った。突如、辺りが騒がしくなる。何事だろうかと、俺は周囲を見渡し、そして納得する。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、なるほどな……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ようやくお出ましという訳だな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "あれが……教皇……" },
  { text: "施設の奥から、見覚えのある老人と、複数人の福音使徒が歩いてくる。周囲の福音使徒、そして教会に来ていた一般人達は、その姿を確認すると、皆揃って頭を下げる。アカツキとVも倣って頭を下げるが、俺とクロセルだけはそのままの姿で構えていた。" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "福音使徒", text: "エンド様、彼らが本当に……？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "あぁ、間違いないよ。確かに私を助けてくれた“勇者”達だ" },
  { name: "福音使徒", text: "そうでしたか、疑ってしまってすいません。教皇の命を狙う者が嘘を吐いた可能性もあったので……" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "まぁ、その可能性を踏まえて警戒する事自体は正しい判断だよ、私を守ろうとしてくれてありがとう" },
  { name: "福音使徒", text: "そんな……有難きお言葉です、感謝します" },
  { text: "教皇の横で付き従っていた福音使徒が、教皇に向かって頭を下げる。そんな姿を優しい笑顔で見守る教皇は、次に俺達の方に視線を向けて言葉を続けた。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "あの時は世話になったね、君達には感謝してもしきれないよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ、死にかけてる老人を放って置く訳にもいかないしな、成り行きだよ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうだぞ、ご主人が優しかったからお前は生きているのだ" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", text: "ちょっとヤマトさん！クロセルさん！？教皇様相手ですよ！？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "構わないよ。君も気を遣ってくれてありがとう" },
  { text: "アカツキが慌てた様子で俺達を叱責するが、教皇はそれを片手で制しながら、アカツキに向かって感謝を述べる。" },
  { text: "まぁ、確かによく出来た人間だ。神に仕える人間のトップ。教皇ともなると、やはり根っからの善人なのだろう、俺とは正反対の人間だ。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "それで、話とは何だい？何か褒賞が欲しいのなら用意するつもりだけど" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "褒美とかそういうのは要らん、こうして話せる機会を貰えただけで十分だ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "そうか、では話を聞こうじゃないか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その前に……人払いを頼めるか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……彼の言う通りにしよう、別室に移ろうか。施設長、応接室は空いてるかな？" },
  { name: "アダン", who: "adan", text: "えぇ、空いてますよ、此方です" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "着いてきなさい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "あの……私達も良いんですか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "構わないよ、彼の仲間なんだろう？" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ありがとうございます" },
  { text: "二人は同時に頭を下げると、俺達の後ろから小走りで付いて来る。" },
  { text: "そして、四人は施設内の一角。応接室に案内された。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "では、皆は外で待っていてくれ" },
  { name: "福音使徒", text: "エンド様、本当にお一人で大丈夫なんですか……？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "もう少し彼らを信じなさい、彼らは私に害をなすような人間ではないよ" },
  { name: "福音使徒", text: "そう……ですよね、失礼しました" },
  { name: "アダン", who: "adan", text: "では僕も失礼するよ、くれぐれも失礼の無いようにね" },
  { text: "教皇の付き人の福音使徒と、アダンは部屋を出ていく。そして、部屋には俺達四人と教皇の五人だけが残された。" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "さぁ、座ると良い。話をしようか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "色々とありがとな、じゃあVとアカツキ、頼んだぞ" },
  { text: "俺はソファに深々と腰掛けると、アカツキとVに目配せをして話をするように促す。それを見て、アカツキは呆れたように溜息を吐きながら、ソファに座る。因みにVは俺を見ながら苦笑いを浮かべている。なんか嫌だな。" },
  { chara: { slot: "right", id: "bolt", expr: "normal" } },
  { name: "V", who: "bolt", expr: "normal", text: "じゃあここは僕から説明するよ、教皇さん、まず聖教会が奴隷売買をしている事を知ってるかな" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "うん、知っている。でもそれは罪人に与えられる然るべき罰であると同時に、更生のチャンスを与える目的がある。神の意志に準じた正当な物だ" },
  { name: "V", who: "bolt", expr: "normal", text: "はい、その通りです、罪を犯した｜咎人《とがびと》を奴隷として売る事自体には問題はないと思います、ですが仮に……罪無き弱者が、不当に奴隷として｜拐《かどわ》かされ、売られている、としたら……どう思いますか？" },
  { chara: { slot: "center", id: "eve_end", expr: "serious" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "……仮にそんな事実があるとすれば、それは良くない事だね" },
  { name: "V", who: "bolt", expr: "normal", text: "そうです、それは許されざる事なんです、そして……此処からが本題なんですが" },
  { text: "Vが重々しい口ぶりで教皇と言葉を交わし合う。そして、ついにその口から真実が述べられた。" },
  { name: "V", who: "bolt", expr: "normal", text: "──聖教会は盗賊から人身を買い取り、奴隷として売却しています" },
  { chara: { slot: "center", id: "eve_end", expr: "surprised" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "それは本当なのかい？" },
  { name: "V", who: "bolt", expr: "normal", text: "本当です。僕達は、そんな違法な奴隷売買が行われている事実を教皇様に伝え、なんとかして頂きたいと考えました" },
  { text: "少し考え込むように目を伏せた教皇に対し、アカツキが言葉を挟む。" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "奴隷売買を管理しているのは聖教会下層組織です、教皇様が知らないのも無理は無いと思います" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "うん、確かに私は聖教会の全てを監視できている訳ではない、中層の現状すら完全には把握できていない状況だ、だから君達が持ってきてくれた話にはとても驚いた、まさに青天の｜霹靂《へきれき》だよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前が聖教会のトップだろ、お前には部下の汚職を何とかする義務があるんじゃないのか？" },
  { chara: { slot: "center", id: "eve_end", expr: "normal" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "その通りだよ、これは私が解決しないといけない問題だ" },
  { name: "V", who: "bolt", expr: "surprised", text: "引き受けて下さるんですか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "うん、任せてくれ。君達の言っている事が事実か調査し、そして必ず解決に導いてみせるよ" },
  { name: "V", who: "bolt", expr: "smile", text: "そうですか！ありがとうございます！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あーそれと、ついでなんだが……俺達が何故こんな手間暇かけてまで聖教会の汚職を摘発しようとしたのか、理由を聞いてくれるか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "聞かせて貰うよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "実はこいつの妹が盗賊に攫われて、奴隷として売られている。俺達はこいつの妹を助け出す為にこうしてお前に会いに来たんだ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "そうだったのか……それは災難だったね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "という訳で、聖教会の下層をどうにかするついでに……こいつの妹を助け出してやってくれないか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "それぐらいなら、私に任せてくれ、やれる限りやってみるよ。それで……君の妹の名前はなんて言うんだい？" },
  { chara: { slot: "right", id: "bolt", expr: "sad" } },
  { name: "V", who: "bolt", expr: "sad", text: "あっ……えっと……それは……" },
  { text: "困ったような顔をしながら、Vは口ごもる。妹の名前を言えない理由でもあるのだろうか？" },
  { name: "V", who: "bolt", expr: "sad", text: "皆さんと教皇様になら……大丈夫かな……あの……僕の妹の名前、口外しないで貰えますか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "何か事情があるんだね、分かったよ" },
  { name: "V", who: "bolt", expr: "sad", text: "……僕の妹の名前は『ファイ・ドラゴファースト』です" },
  { text: "その名に、何故かアカツキだけが息を呑んだ。俺にもクロセルにも、教皇にすらピンと来ていない。だがアカツキだけは――まるで幽霊でも見たような顔で、じっとVを見つめていた。" },
  { chara: { slot: "left", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "えっ……ってことはVさん……貴方は……" },
  { name: "V", who: "bolt", expr: "smile", text: "あはは……やっぱアカツキさんにはバレちゃいますよね……出来れば今後もVと呼んで頂けると助かります" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あ？アカツキ、何が分かったんだ？" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふむ……我も良く分からんな" },
  { chara: { slot: "left", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "秘密です、V君はV君ですから" },
  { name: "V", who: "bolt", expr: "smile", text: "すいません……ありがとうございます、アカツキさん" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "そうか……大変だったんだね……事情は察した。承ったよ。君の妹は私が必ず助け出そう" },
  { name: "V", who: "bolt", expr: "smile", text: "ありがとうございます" },
  { text: "Vは教皇に深く頭を下げる。これで伝える事は伝えきっただろうか。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ、話は以上だ。時間を取らせて悪かったな" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "気にしないでくれ、有意義な時間だった" },
  { text: "そう声を掛けると、教皇はにこやかな笑顔で応えた。それを見届けると、そそくさと俺は立ち上がり、出口へと歩いて行く。" },
  { name: "ヤマト", who: "yamato", text: "じゃあ失礼する" },
  { name: "クロセル", who: "crocell", text: "全く……ご主人は気が早いな" },
  { name: "ヤマト", who: "yamato", text: "教皇も忙しいんだろ、俺達がさっさと立ち去ってくれた方が有り難いはずだ" },
  { name: "V", who: "bolt", expr: "normal", text: "では教皇様、本当にありがとうございました" },
  { hide: "all" },
  { fade: "out" },
  { bg: "arcadia_lower" },
  { fade: "in" },
  { bgm: "town" },
  { text: "部屋を出るとそこには教皇の付き人の福音使徒、そしてアダンがおり、俺達が部屋から出るとほぼ同時に部屋の中へと駆け込んでいく。やっぱり俺達は教皇以外には信用されていなかったようだ。" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "center", id: "yamato", expr: "normal" },
      { slot: "right", id: "akatsuki", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これで解決だな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まだ何も解決してないですけど……後は教皇様が上手くやってくれる事を祈るばかりですね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あーそうか……イヴェンの性格だと心配だな……部下の嘘を信じ込んで騙されるかもしれん" },
  { name: "V", who: "bolt", expr: "normal", text: "その略し方は何なんですかね……？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ああ見えても賢い人ですから大丈夫だと思いますよ、ヤマトさんとクロセルさんが勇者じゃないと分かってて目を瞑ってくれていたみたいですし" },
  { chara: { slot: "center", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "えっ……バレてたのか？" },
  { chara: { slot: "right", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "当たり前でしょう……上層まで来といて神を守らず帰るような人間が勇者な訳無いじゃないですか……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それもそうか……分かってて知らないフリをしてたのかよ……なんか腹立つな" },
  { name: "V", who: "bolt", expr: "smile", text: "いやそこは感謝する所だよね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "うるせー……取り敢えず帰るぞ、俺達に出来ることはもうない" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうだな、帰るとしよう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ところで……Vの妹の名前がどうしたんだよアカツキ、気になるだろ" },
  { chara: { slot: "right", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "Vさんとの約束ですから何も言えません" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんだよ……俺よりVの方が大事なのか！？" },
  { name: "アカツキ", who: "akatsuki", expr: "angry", text: "そういう訳じゃないですよ！というかどっちが大事とかそういう話じゃないですし！" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、ご主人の理解者は我だけで良いのだ" },
  { name: "アカツキ", who: "akatsuki", expr: "blush", text: "私だってヤマトさんの事を大事に思ってますから！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、なら教えてくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "えっ、嫌です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんでだよ！" },
  { text: "教皇に｜直談判《じかだんぱん》する事に成功し、Vの依頼を事実上解決。眼前の目標を達成し、身も心も浮かれきった俺達は、仲良く歓談しながら拠点に帰るのであった。" },

  /* ===============================================
     Scene 14: hideout_raid ― 隠れ家 (EP69)
     =============================================== */
  { label: "hideout_raid" },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "daily" },
  { text: "数日後。公衆浴場の営業時間中、人気も落ち着き俺が暇を持て余していた所、エルに声を掛けられる。" },
  { chara: [
      { slot: "left", id: "el", expr: "normal" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あ？俺に客だと？" },
  { name: "エル", who: "el", expr: "smile", text: "みたいだよ、公衆浴場の区画にある個室で待ってるらしいから行ってらっしゃい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキからの伝言か？" },
  { name: "エル", who: "el", expr: "normal", text: "うん、そうだけど" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか、まぁありがとう、気は乗らないが行ってくる" },
  { text: "なんでも俺を訪ねてきた客人が居るらしい。珍しい物だ。正直、面倒なのだが放置する訳にもいかない。俺は重い足取りで指定された部屋へと向かった。" },
  { hide: "all" },
  { chara: [
      { slot: "left", id: "eve_end", expr: "normal" },
      { slot: "center", id: "yamato", expr: "normal" },
      { slot: "right", id: "nicholas", expr: "laugh" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "此処か、待たせたな" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "お｜邪魔《じゃま》しているよ" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "久しぶりだね！ヤマト君！" },
  { name: "ヤマト", who: "yamato", text: "うげ……" },
  { text: "俺が扉を開け、その目に飛び込んできたのはアカツキ。そして彼女に向かい合うようにして教皇イヴ・エンドと祝福の勇者ニコラスの二人が座っていた。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "アカツキ……客ってこいつらの事か？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですよ？ほら、早く座って下さい" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか……分かった……" },
  { text: "教皇は兎も角、勇者が絡んだ案件となると、俺としては嫌な予感しかしない。絶対に面倒事を持ち込まれる流れだ、これは。俺は椅子に座ると、軽く辺りを見渡し、疑問に思った点について質問を投げる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今日は福音使徒のボディーガードとか居ないのか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "勇者様を連れてきたのは私の護身の目的もあるからね、それに出来れば外部に漏らしたくはない話なんだ、と言えば要件は察して貰えるかな？" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あー……先日の案件か、｜進捗《しんちょく》はどうなんだ？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "違法な奴隷売買に直接関わっていた実行犯は摘発、同時に下層と繋がっていた各種盗賊団は逮捕。違法奴隷の解放。とまぁ、この案件は八割程度達成出来たと言って良いんだが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "残りの二割は何なんだよ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "違法奴隷を匿っている隠れ家がまだあるみたいなんだ、そして実行犯を裏で操っていた黒幕が誰かを暴く必要がある" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その隠れ家が何処か分からないのか？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "大方の｜目星《めぼし》は付いている。後は制圧するだけだ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ならさっさとやれば良いじゃねぇか、俺達に何の関係があるんだよ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "誰が黒幕か分からない以上、福音使徒を使って捜査をするのは悪手だ。万全を期す為には、聖教会の外部の人間に依頼する必要があった" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……それを俺達にやれと？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "surprised", text: "そういう事になるかな、戦力として祝福の勇者ニコラス君が君達の仲間として動いてくれる｜手筈《てはず》になっている、どうだろう、引き受けて貰えないか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ふむ……なるほどな" },
  { text: "要するに。俺達は敵の隠れ家に行ってそこを制圧、黒幕を捕まえてくれば良いらしい。クロセルに加えて勇者も付いて来るとなれば、戦力は十分だ。難しい依頼ではないが……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "報酬は？" },
  { name: "イヴ・エンド", who: "eve_end", expr: "normal", text: "金銭で良ければそれでも良いし、他に望みがあるなら聞いても良い" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……いや、やっぱ無しだ、違法奴隷の件でお前には十分働いて貰ったしな、引き受けてやるよ" },
  { hide: "left" },
  { chara: { slot: "left", id: "akatsuki", expr: "surprised" } },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "え！？あの……ヤマトさん……？熱でも出しましたか？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ？うるさいぞ……快く引き受けたのに何か文句でもあるのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "いえ……ごめんなさい、ちょっと驚いただけです……ヤマトさんが無償で他人に奉仕が出来る人間だったなんて……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "お前、俺の事馬鹿にしてるだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そんなつもりはないんです……ごめんなさい" },
  { text: "まぁ下心が無い訳ではない。後の事を考えて教皇とは良い関係を築いておきたいと思っただけだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ、この程度の仕事、俺とクロセルに掛かれば余裕で解決してやるよ" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "心強いですね、引き受けて頂いてありがとうございます" },
  { chara: { slot: "right", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "ヤマト君とクロセルちゃんが強い事は知ってるけど、僕の事は忘れてないよね？" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "いやお前……また無茶しただろ……上層で会った時は気付かなかったが鎧がボロボロだぞ" },
  { text: "勇者の黄金の鎧は、到るところに裂傷の跡があり、何らかの不思議パワーで継ぎ剥がれ、何とかその形を留めていると言ったような容態だ。勇者自身の身体は不死身でも、その装備品には確かに寿命がある。もう十分に買い替え時だと思うのだが……あの鎧には何か思い入れでもあるのだろうか。" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "気にしないでくれ、僕の性能に支障はない、今回は武器も健在だ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "まぁ別にお前を幾ら消耗しようと俺には関係ないから別に良いんだけどな、精々盾になってくれ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "うん！僕に任せてくれ！" },
  { text: "皮肉を言ったつもりなのだが、何故か嬉しそうだ。自信満々に拳で胸を叩く勇者を横目に、俺は教皇に話を振る。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "んで……その隠れ家の場所ってのは何処なんだ？" },
  { chara: { slot: "left", id: "eve_end", expr: "normal" } },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "実は正確には絞れていないんだ、だから幾つかの候補地がある、詳細は彼女に渡した書類に書いてある" },
  { hide: "right" },
  { chara: { slot: "right", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん、此方です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どれどれ……" },
  { text: "アカツキが地図らしき物を机の上に広げる。そして懐からペンを取り出すと、地図の複数箇所に丸を付けた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "結構多いな、一日だと回りきれなそうだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "あぁ、これ全部を回る訳では無いですよ。書類と照らし合わせて可能性の高い場所を特定しますから大丈夫です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なら出発は後日になるか" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうなりますね、その間……ニコラスさんも一緒に住みますか？" },
  { chara: { slot: "left", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "良いのかい？" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "おい、アカツキ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "構いません、明日には発てると思うので滞在して頂くのは一晩程度になると思いますが" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "それなら然程迷惑も掛からないかな、お言葉に甘えることにするよ" },
  { chara: { slot: "center", id: "yamato", expr: "angry" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "俺は許可してないぞ！？" },
  { chara: { slot: "right", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "この施設は半分以上私の物ですからね、ヤマトさんに決定権はありません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "うぐっ……確かにそうだが……" },
  { hide: "left" },
  { name: "イヴ・エンド", who: "eve_end", expr: "serious", text: "じゃあ、話も纏まったようだし、私はこの辺で失礼するよ。引き受けてくれてありがとう" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "お見送りします、じゃあヤマトさんはニコラスさんを部屋に案内しといて下さい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かった……客用の部屋で良いんだよな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それで大丈夫です、頼みましたよ" },
  { text: "そう言い残すと、アカツキは教皇に付いて部屋を出ていった。後に残された俺と勇者は、気まずい雰囲気の中、お互いに沈黙する。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あー……じゃあ部屋に案内するから着いて来い" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "うん！分かったよ！" },
  { text: "不本意だがアカツキの意向なら仕方ない。俺は勇者を部屋に案内し、そのまま一晩泊める事になったのだった。" },
  { hide: "all" },
  { fade: "out" },
  { bg: "underground_prison" },
  { fade: "in" },
  { bgm: "suspense" },
  { text: "そして翌日。俺とクロセル、アカツキと勇者の四人は、拠点の前で集合していた。エル、ティア、Vの三人は留守番だ。" },
  { chara: [
      { slot: "left", id: "akatsuki", expr: "normal" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "三人は留守番か" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "犯罪者の隠れ家に向かうんですから、黒幕に抵抗される可能性もあります、その際に戦えない人が居ると危険ですからね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺は戦える奴扱いなのか……？" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "武帝と称されるあの皇帝を二度も破ってるんですからもっと自信を持って下さい、ヤマトさんは強いですよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁな……傷害のディザビリティさえ無ければ異世界で無双ハーレムも夢じゃ無かったってのに……惜しい物だ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "……何も言わないでおきましょうか" },
  { chara: { slot: "center", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "早く出発しよう！悪は僕が裁くんだ！ジャスティス！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "うるせぇ……んでアカツキ、隠れ家の場所は絞れたのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "一箇所まで絞れました、要するに確定ですね、聖教会の資料に間違いがなければ間違いなく絞れてる筈です" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "流石だな、んじゃ案内は任せるぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "任されました、では行きましょうか" },
  { text: "アカツキが地図を片手に歩き出す。俺達三人はその背に付き従うようにして歩いた。そして、聖都を数時間程度歩いただろうか。俺達は一軒の民家らしき場所の前に立っていた。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "此処なのか？" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "クロセルさん、中に人は" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》──空間魔術 ｜空間精査《サーチ》" },
  { se: "magic" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "地下があるな、中の生命反応は数十体、この数だと敵の戦力に加えて奴隷も含まれていると推定出来る" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "通路は確保出来てます？" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "障害物、要するに扉はこの正面の一つだけだ。この扉さえ開けば真っ直ぐ最奥まで向かえる" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "では役割分担しましょうか、ヤマトさんと私で黒幕を捕獲、クロセルさんとニコラスさんの二人で敵戦力の無力化" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "戦力が偏り過ぎじゃないか？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "黒幕の戦闘能力次第だと俺とアカツキだけじゃ捕獲は厳しいかもしれないぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "捕獲、と言いましたが実際の所はクロセルさんとニコラスさんが敵を全滅させて合流するまで、時間を稼げれば良い訳ですから多少戦力不足でも問題ありません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうか、ならそれでいこう" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ではニコラスさん、一番槍は任せました" },
  { chara: { slot: "right", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "任された！行くぞ！ニコラス流……ニコン式奥義……ヒーローアターック！！！" },
  { fx: "shake" },
  { text: "勇者は刀に手を掛けて扉へと突き進んでいくと……その刀を抜き放つ……事はなく。そのまま体当たりで扉を｜蹴破《けやぶ》る。俺は唖然としながらそれを見ていた。その間にも、勇者はそのまま建物の奥へと走っていく。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん、行きますよ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……おう……" },
  { hide: "nicholas" },
  { hide: "crocell" },
  { text: "クロセルも勇者に続いて走っていき、後には俺とアカツキだけが残された。アカツキは俺の手を掴むと、そのまま手を引きながら走って行く。この建物の内部構造は至ってシンプルだった。" },
  { text: "一階部分はカムフラージュの為に何の変哲も無い民家となっており、その一部屋が地下に続く階段になっている。" },
  { text: "地下に進むと、そこは地下牢と呼ぶに相応しい空間が広がっていた。真っ直ぐ通路があり、その両脇に長屋のように牢獄が配置されていた。その道中には見張りらしき福音使徒が何人か見受けられ、その全員が武装、俺達に牙を｜剥《む》いてきた。" },
  { text: "だが、その｜凶刃《きょうじん》が俺達に届く事は無い。クロセルと勇者が無詠唱魔術と鮮やかな｜剣戟《けんげき》で速やかに敵勢力を無力化していく。そのお陰で、俺とアカツキの二人は一切敵と交戦する事無く、その最奥部まで辿り着く事に成功した。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "見事に牢屋と通路しか無かったな、部屋は此処一つだけか" },
  { text: "俺は立ち入った部屋の中を見渡す。そこにはロープや鎖、拷問器具や無数の鍵が壁に掛けられ、床にはまだそう時間が経っていないであろう血痕が広がっている。本棚には書類が詰め込まれており、残るは机と椅子。例えるならばそれは……悪趣味な書斎と形容するのが相応しい部屋であった。" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前が盗賊と通じて違法な奴隷を売買していた黒幕だな" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん、気を付けて下さい" },
  { name: "？？？", text: "おかしいな……僕の部下が来る筈だったんだけど……教皇も中々頭が回る、内通者の存在を加味して外部の人間に摘発を依頼するとはね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前は……" },
  { name: "？？？", text: "でも教皇は詰めが甘いな、これも僕の中では想定内だった、そう……君達が来る事を知っていたから、僕も少し準備をしたんだ" },
  { text: "黒幕は背を向けたまま、俺達に向けて言葉を紡ぐ。俺はポケットから一枚の紙とペンを取り出すと、何か文字を書く。そんな俺の行動に不思議そうに首を傾げるアカツキ。俺はそれを遥か後方へと放り投げた。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "人質を解放しろ" },
  { name: "？？？", who: "adan", expr: "cold", text: "うん、やっぱり君達だね、と言うことは……この子が大事なんだろう？" },
  { se: "heartbeat" },
  { chara: { slot: "center", id: "adan", expr: "cold" } },
  { text: "黒幕は立ち上がると、ゆっくり俺達の方へと振り向く。その右手にはナイフ。左手には、意識を失った赤髪の少女が乱雑に抱き抱えられていた。" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさん、彼女は？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "Vの妹だろう、俺達にとっては一番厄介な人質だな" },
  { name: "？？？", who: "adan", expr: "cold", text: "戦闘音……まだ仲間を連れてきてるんだね、困るなぁ……僕の大事な部下を傷付けるなんて" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "殺すつもりはない、無力化するだけだ" },
  { name: "？？？", who: "adan", expr: "cold", text: "そうか、君達は優しいんだね、僕と違って" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、俺達に比べればお前は最低だな、｜卑怯《ひきょう》な手を使いやがって" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "違法奴隷売買の黒幕は……貴方だったんですね……" },
  { name: "アダン", who: "adan", expr: "cold", text: "そうだよ、僕が黒幕だ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "どうしてこんな事をするんですか……──アダンさん……" },
  { text: "俺達の前に立ち塞がっていたのは、茶髪に糸目の男性。聖教会に属する福音使徒の一人、アダンであった。" },
  { name: "アダン", who: "adan", expr: "cold", text: "簡単な話だよ、この商売は金になる。僕は高い地位を利用して盗賊から買い取った奴隷を売り捌いた。罪人は大した値じゃ売れないからね、盗賊から買い取った従順な奴隷は良い値で売れるんだよ" },
  { name: "アダン", who: "adan", expr: "cold", text: "奴隷の売り上げが評価され昇格も出来た。僕の人生は順風満帆だった……んだけどね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それも此処までだな、俺達はお前を捕らえ聖教会に突き出す。証拠なら此処に幾らでもあるからな" },
  { name: "アダン", who: "adan", expr: "normal", text: "あはは……そうなんだよね……だから僕としても君達を無事に帰す訳にはいかないんだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "どうすれば人質を解放してくれる？" },
  { name: "アダン", who: "adan", expr: "cold", text: "そうだな……まずは大人しく拘束されてくれるかな、君の仲間も一緒にね" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "そんな条件……呑める訳……" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキ、“黙れ”" },
  { text: "俺は強い口調でそう告げると、アカツキの方に視線を向け、瞳で何かを訴えかける。通じたかは分からないが、ひとまず口を｜噤《つぐ》んでくれたようだ。それから間も無く、後ろから大きな足音を立ててクロセルがやってくる。" },
  { chara: { slot: "farleft", id: "crocell", expr: "angry" } },
  { name: "アダン", who: "adan", expr: "shock", text: "どうだい？僕の要求を呑む気にはなったかな？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺達全員を拘束したら、お前は彼女を解放するんだな？" },
  { name: "アダン", who: "adan", expr: "cold", text: "そうだね、君達全員を捕らえたら彼女の無事は保証しよう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かった。要求を呑む、俺達を拘束しろ" },
  { name: "アダン", who: "adan", expr: "normal", text: "助かるよ、ありがとう" },
  { text: "アダンはナイフを突き付けたまま俺達に近付き、近くにあった鎖で全身を拘束していく。片手で人質を取ったままもう片方の手で拘束するとは、何とも器用なものだ。そして、駆け付けたクロセルを含む俺達三人は、アダンの手によって完全に拘束されたのであった。" },
  { hide: "all" },

  /* ===============================================
     Scene 15: scream_gambit ― 違法奴隷売買 (EP70)
     =============================================== */
  { label: "scream_gambit" },
  { text: "違法奴隷売買の黒幕、アダンに手足の自由を奪われ、俺達は｜絶体絶命《ぜったいぜつめい》の危機に陥っていた。" },
  { text: "いや……俺の拘束はいつでも解けるしクロセルも口を塞がれている訳では無いから魔術でどうとでもなるのだが。人質が居る以上、強引な手段は取れない。" },
  { text: "相手の力量も未知数だ。という訳で……今は大人しく捕まっているのだが……" },
  { chara: { slot: "center", id: "adan", expr: "normal" } },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "約束通り、人質を解放しろ" },
  { name: "アダン", who: "adan", expr: "normal", text: "分かってるよ、僕は約束を守る男だ、ほら……これで良いかい？" },
  { text: "アダンは人質の少女を離す。少女は意識を失っているようで、そのまま力無く地面に倒れ込んだ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それで、俺達をどうするつもりだ？" },
  { chara: { slot: "center", id: "adan", expr: "cold" } },
  { name: "アダン", who: "adan", expr: "cold", text: "そうだな……君達は強いから商品にする事も出来ないし……かと言って生かして帰す訳にもいかない。となると……答えは一つだね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうか……" },
  { text: "どうやらアダンは俺達を殺すつもりらしい。ナイフを片手に、俺達の方へと歩み寄ってくる。それに対して、俺は息を大きく吸い込み……大声で叫んだ。" },
  { fx: "shake" },
  { chara: { slot: "right", id: "yamato", expr: "surprised" } },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嫌だあああああああああああああ！！！死にたくない！！！誰かあああああああああああああ！！！助けてくれ！！！" },
  { name: "アダン", who: "adan", expr: "normal", text: "命乞いとは意外だね……残念だけどこの建物は完全防音だ。君達に助けは来ないよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "うわあああああああああああああ！！！やめろおおおおおおおおおおおおお！！！" },
  { chara: { slot: "center", id: "adan", expr: "angry" } },
  { name: "アダン", who: "adan", expr: "angry", text: "煩いなぁ……僕は煩いのが嫌いなんだ、だから君から最初に殺してあげるよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "死にたくない！死にたくない！嫌！嫌！嫌！" },
  { name: "アダン", who: "adan", expr: "normal", text: "さようなら" },
  { text: "アダンが俺の目の前でナイフを振り上げる。それを見て、俺はニヤリと笑みを浮かべ、一言呟いた。" },
  { chara: { slot: "right", id: "yamato", expr: "smirk" } },
  { cg: "cg_scream_gambit" },
  { wait: 600 },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "──なーんてな……やっちまえ、勇者" },
  { chara: { slot: "right", id: "nicholas", expr: "serious" } },
  { se: "flash" },
  { fx: "flash" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "ヒーローアターック！！！" },
  { se: "slash" },
  { cg: null },
  { chara: { slot: "center", id: "adan", expr: "shock" } },
  { name: "アダン", who: "adan", expr: "shock", text: "な……何処から！？" },
  { text: "俺の目の前、アダンと俺の間を、勇者が抜刀した状態で駆け抜けていった。勇者の一刀によりアダンの両腕は見事に両断され、その足元に転がる。" },
  { text: "アダンは、何が起こっているのか理解出来ないとばかりに辺りを見渡し、驚きのあまり挙動不審になっている。そして、ふと自分の腕だった場所を見たかと思えば、一瞬の思考停止の後、絶叫を放つ。" },
  { name: "アダン", who: "adan", expr: "shock", text: "あぁぁぁぁぁ！？僕の腕が！？" },
  { chara: { slot: "right", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ文字を読む程度の脳はあったみたいだな、良くやったぞ勇者" },
  { name: "アダン", who: "adan", expr: "normal", text: "くっ……どうして……いつの間に……" },
  { text: "俺は呆れたように溜息を吐きながら、後ろ手で爪を噛み合わせディザビリティで鎖を解くと、そのまま立ち上がり、アダンの顔を指差し告げる。" },
  { chara: { slot: "right", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前、今になってもバレてないと思ってるのか？" },
  { name: "アダン", who: "adan", expr: "normal", text: "な……何がだ！" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前の“目が見えない”事だよ" },
  { name: "アダン", who: "adan", expr: "normal", text: "っ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その代わりに異常な程の聴覚がある、だから傍から見れば健常者に見えたって訳だ" },
  { name: "アダン", who: "adan", expr: "shock", text: "いつ気付いた！？" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "疑ったのは初対面。俺とVの二人が居たのにV一人に対して声を掛けただろ、最初は俺を無視してるだけだと思ったが……二度目に会った時もそうだった。お前、俺が仲間を連れてたのに俺達の方を見て“俺だけ”が来たと勘違いしたよな" },
  { name: "アダン", who: "adan", expr: "normal", text: "そんな事で分かる訳が無いだろう……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、そうだな。変な奴だとは思ったが、確証には至らなかった。本当に確信を持ったのは此処で会ったその時だ" },
  { name: "アダン", who: "adan", expr: "cold", text: "なるほどね……人質か……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ。あの応接室は壁が薄いという訳では無い。普通の人ならば扉の前に居るだけじゃ中の様子は聞こえないだろう。まぁ……それなのに聞こえてたって事はお前の聴力が普通じゃないからだと推測できる" },
  { name: "アダン", who: "adan", expr: "normal", text: "だから大声を出して仲間の行動する音を掻き消してたって訳か……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "人質を解放した上でお前を無力化するには、これが一番良い方法だと思ってな。お前の目と耳について仲間に伝えた。後は味方次第、まぁ上手いことやってくれたって訳だ" },
  { name: "アダン", who: "adan", expr: "normal", text: "僕は……ここまでなのか……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ、大人しく諦めろ" },
  { text: "両腕を失い、もはやアダンに出来ることはない。俺は悠々とクロセルとアカツキの鎖を解き、その鎖でアダンを縛る。" },
  { hide: "center" },
  { chara: [
      { slot: "left", id: "crocell", expr: "normal" },
      { slot: "lcenter", id: "yamato", expr: "smirk" },
      { slot: "rcenter", id: "akatsuki", expr: "normal" },
      { slot: "right", id: "nicholas", expr: "laugh" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "僕がみんなを救ったんだ！凄いだろ！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "はいはい、良くやったぞ勇者" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私に黙れって言ったのは勇者さんがアダンさんに近付いてるのに気付いても黙ってろって事だったんですね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "まぁな、察しが良くて助かったよ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "むぅ……あの程度の雑魚ならば我の魔術で瞬殺出来るのだがな……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "正直、どうしようも無くなったらクロセルに頼るつもりだった、今回は頼るまでも無かったってだけだ、能ある鷹なんだから爪は隠しとけ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "なんだそれは？" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "才能のある賢人はその才能をひけらかしたりしないって意味の言葉だ、お前は賢いだろ？" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "うむ！我は賢いからな！決してその才能をひけらかしたりはしないのだ！" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そうそう、勇者みたいにはなりたくないだろ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "確かにご主人の言う通りだな" },
  { text: "俺はアダンを縛り終えると、満足げに頷く。これで依頼は完遂できたと言っていい。後は事後処理になるが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキはこいつを聖教会に突き出してきてくれ、ついでに此処に捕らえられてる他の奴隷の保護の依頼も任せた" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "分かりました、ヤマトさんは？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺はこいつを連れて帰る、クロセルと勇者はアダンの配下の福音使徒達を縛って牢屋にでも入れといてくれ、その後はアカツキと合流して聖教会と一緒に事後処理を頼む" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "了解だ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "任せてくれ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ頼んだぞ" },
  { hide: "all" },
  { fade: "out" },
  { bg: "bathhouse_base" },
  { fade: "in" },
  { bgm: "heartwarm" },
  { text: "面倒な事後処理は仲間に任せ、俺は人質の少女を抱き抱える。近付いて気付いたが、奴隷には首と手足に鉄の輪が付けられている。鍵穴などは無い。強引に破壊するしか無いのだろうか。" },
  { name: "ヤマト", who: "yamato", text: "ま、後でクロセルにでも頼めば良いか、じゃあ先に帰ってるぞ" },
  { text: "俺は人質の少女、Vの妹と思われる人物を抱き抱えたまま、隠れ家を後にした。そして聖都を暫く歩き、真っ直ぐに拠点へと向かった。数時間後。俺は拠点へと辿り着いた。" },
  { chara: [
      { slot: "left", id: "el", expr: "smile" },
      { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ただいま" },
  { name: "エル", who: "el", expr: "smile", text: "おかえりなさい、ヤマト様" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エルか、Vは何処だ？" },
  { name: "エル", who: "el", expr: "normal", text: "部屋に居ると思うよ、それで……その子がもしかして？" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、多分だがVの妹だ。敵の隠れ家に居たから連れ帰ってきた" },
  { name: "エル", who: "el", expr: "smile", text: "そうなんだ、流石はヤマト様、お手柄だね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "じゃあVの所に行ってくる" },
  { name: "エル", who: "el", expr: "smile", text: "行ってらっしゃい" },
  { hide: "all" },
  { text: "俺はエルと短い会話を済ませると、Vの部屋へと向かった。ドアをノックし、中から短い応答が聞こえたと同時に、俺は扉を開き中に入る。" },
  { chara: [
      { slot: "left", id: "yamato", expr: "normal" },
      { slot: "right", id: "bolt", expr: "surprised" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よう、帰ってきたぞ、V" },
  { name: "V", who: "bolt", expr: "normal", text: "おかえり、ヤマトさん……ってその子は！" },
  { text: "Vが俺の方へと振り返る。その｜刹那《せつな》、驚いたように目を丸くしたかと思えば、全速力で俺の方に駆け寄り、少女の顔を覗き込む。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前の妹で間違い無いか？" },
  { chara: [
      { slot: "right", id: "bolt", expr: "smile" },
      { slot: "center", id: "fai", expr: "normal" },
  ] },
  { name: "V", who: "bolt", expr: "normal", text: "うん！うん！間違いない！ファイだ！僕の妹の！" },
  { text: "目を輝かせて何度も頷いたかと思えば、力を失ったかのように地面に座り込む。" },
  { name: "V", who: "bolt", expr: "smile", text: "良かった……無事で良かったよ……" },
  { chara: { slot: "left", id: "yamato", expr: "smile" } },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、良かったな。大した怪我も無いみたいだぞ" },
  { name: "V", who: "bolt", expr: "smile", text: "ベッドに寝かしてやってくれ、僕が面倒を見る" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうだな、後は兄のお前に任せる" },
  { text: "俺はVのベッドの上に少女を寝かせると、そのままVの部屋を後にしようとする。" },
  { name: "V", who: "bolt", expr: "surprised", text: "あの！ヤマトさん！" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あ？なんだ？" },
  { name: "V", who: "bolt", expr: "sad", text: "本当に、本当にありがとう！僕の妹を無事に取り戻せたのは貴方のお陰だ。面倒事に巻き込んでしまって本当に申し訳ないと思ってる、この礼はいつか必ずするから！" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、まぁ期待しとくわ" },
  { text: "Vは俺に向かって何度も頭を下げる。なんともくすぐったい感覚に俺は頭を掻きながら……適当に手を振り、その部屋を後にした。" },
  { hide: "all" },
  { name: "ヤマト", who: "yamato", text: "これで……終わりか……" },
  { text: "教皇の依頼、Vの依頼、その両方が解決し、これで俺達の抱える問題は無くなった。これで……これからは、平穏無事な日常を｜謳歌《おうか》出来るのだろうか。" },
  { name: "ヤマト", who: "yamato", text: "少しは罪滅ぼしになった……だろうか……" },
  { text: "らしくない呟きだ。俺の前世の罪を精算するには、この程度の慈善活動じゃ到底足りはしない。" },
  { name: "ヤマト", who: "yamato", text: "まぁ……この世界で安寧を得るには魔王をどうにかしないとだよな……" },
  { text: "先日の襲撃で確信した。もはや教国も無事とは言えない。王国で犯罪者として生きる、帝国で魔王の｜傀儡《かいらい》として生きる、なんて手もあるが、それなら死んだ方がましだ。" },
  { name: "ヤマト", who: "yamato", text: "魔王を倒す……か、今の俺達じゃ無理な話だが……或いは……" },
  { text: "あまり時間は残されていない。限られた時間をどう使うか……それが俺と魔王の勝敗を決めるだろう。" },
  { name: "ヤマト", who: "yamato", text: "公衆浴場の運営はアカツキ達に任せて、俺は俺で動くとするか……" },
  { bg: "bathhouse_base_night" },
  { bgm: "resolve" },
  { text: "気付けば、窓の外はとっぷりと日が暮れていた。喧騒の引いた拠点で、俺は一人、これから始まる戦いの事を考える。静かな夜だ。だが、この静けさが長く続かない事を、俺は知っている。" },
  { text: "策は無い訳でもない。魔王に対抗する術を用意することも不可能ではない筈だ。俺は拳を強く握り締め、未来への覚悟を決めるのであった。" },
  { fade: "out" },
  { jump: "ch05:morning_peace" },

  /* ===============================================
     ◆B05分岐: 瀕死の老人を見捨てる → BAD END『神殺しの夜』
     =============================================== */
  { label: "b05_abandon" },
  { bgm: "sad" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", text: "駄目だ。見ず知らずの爺に構ってる時間はない。ティア、お前だけ連れて帰る", tid: "ch04__b05_abandon__01" },
  { chara: { slot: "right", id: "tia", expr: "sad" } },
  { name: "ティア", who: "tia", text: "そんな……！お願いヤマト、この人死んじゃうわ！", tid: "ch04__b05_abandon__02" },
  { name: "ヤマト", who: "yamato", text: "助ける義理の無い人間は助けない。俺はそういう人間だ。言っただろ", tid: "ch04__b05_abandon__03" },
  { chara: { slot: "left", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", text: "ご主人……良いのか？", tid: "ch04__b05_abandon__04" },
  { name: "ヤマト", who: "yamato", text: "良いも悪いもない。後続の帝国兵が来たら俺達は全滅だ。優先順位を間違えるな", tid: "ch04__b05_abandon__05" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……それも、一理ある。だが、その老人は福音使徒だ。聖教会の中でも相応の地位の者だろう。見過ごすには、些か惜しい命やもしれんぞ", tid: "ch04__b05_abandon__06" },
  { name: "ヤマト", who: "yamato", text: "惜しいとか惜しくないとか、そういう話じゃない。俺は俺の仲間を一人も死なせたくない、それだけだ", tid: "ch04__b05_abandon__07" },
  { text: "それは正論だった。正論の筈だった。俺は暴れるティアに手錠を掛け、｜猿轡《さるぐつわ》を噛ませる。", tid: "ch04__b05_abandon__08" },
  { chara: { slot: "right", id: "tia", expr: "sad" } },
  { name: "ティア", who: "tia", text: "んーっ！んーっ！", tid: "ch04__b05_abandon__09" },
  { text: "｜猿轡《さるぐつわ》越しに、ティアが何かを必死に訴えてくる。だが詠唱の出来ないティアにはもう、俺を止める術はない。俺は血溜まりに沈む老人に背を向けた。", tid: "ch04__b05_abandon__10" },
  { name: "老人", text: "ま……って……神様……が……聖域に……", tid: "ch04__b05_abandon__11" },
  { chara: { slot: "center", id: "yamato", expr: "serious" } },
  { name: "ヤマト", who: "yamato", text: "……悪いな、爺さん。あんたの神様は、あんたらで守ってくれ", tid: "ch04__b05_abandon__12" },
  { name: "老人", text: "君は……後悔、する……ぞ……これは、君達の……世界の……話、でもある……", tid: "ch04__b05_abandon__13" },
  { name: "ヤマト", who: "yamato", text: "知ったことか。俺の世界はもう、俺の仲間だけで手一杯なんだよ", tid: "ch04__b05_abandon__14" },
  { text: "掠れた声が背中に届く。だが俺は振り返らなかった。白い広間に、コツン……と、力尽きた老人の手から杖が落ちる音だけが響いた。それが教皇イヴ・エンドの、最後の音であったとも知らずに。", tid: "ch04__b05_abandon__15" },
  { hide: "all" },
  { fade: "out" },

  { label: "b05_sanctuary_fall" },
  { bg: "arcadia_upper" },
  { fade: "in" },
  { bgm: "tension" },
  { comment: "視点転換: 聖域 ― 教皇の居ない防衛戦" },
  { pov: "nicholas" },
  { text: "～その頃、聖域～　結界を張り続けていた福音使徒の魔力が、ついに尽きた。ガラスの割れるような音と共に、兵達と神を隔てる壁はなくなった。", tid: "ch04__b05_sanctuary_fall__01" },
  { text: "本来であれば、此処に駆け付ける者が居た。深手を負いながらも治癒され、杖を突いて立ち上がる老人が。──だがこの世界線に、彼は間に合わない。誰にも治癒されなかった教皇イヴ・エンドは、白い広間の彫像の足元で、静かに息絶えていた。", tid: "ch04__b05_sanctuary_fall__02" },
  { text: "――それでも、神の御告げは勇者を呼んでいた。御告げに従い上層へ駆け付けた勇者ニコラスは、広間の屍の中に教皇が眠っている事も知らぬまま、ただ一人、神の前に立ち塞がっていた。", tid: "ch04__b05_sanctuary_fall__03" },
  { chara: { slot: "left", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", text: "僕が！僕こそが！祝福の勇者ニコラスだ！神様には指一本触れさせない！", tid: "ch04__b05_sanctuary_fall__04" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "ラプラス", who: "laplace", text: "あはははは！一人ですか？随分と寂しい防衛線ですねぇ！教皇はどうしたんですか？まさか、もう死んじゃったとか？あはっ、それはそれは……ボク、運がいいなぁ", tid: "ch04__b05_sanctuary_fall__05" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "教皇……？彼ならきっと来てくれる！祝福の勇者と教皇が揃えば、悪は必ず裁かれるんだ！", tid: "ch04__b05_sanctuary_fall__06" },
  { chara: { slot: "right", id: "laplace", expr: "normal" } },
  { name: "ラプラス", who: "laplace", text: "へぇ……来てくれる、ねぇ。ボクは分かってる！君の未来と死が見える！だから教えてあげますよ……誰も、来ませんよ", tid: "ch04__b05_sanctuary_fall__07" },
  { fx: "shake" },
  { name: "ラプラス", who: "laplace", text: "ジ・エンドです、勇者さん", tid: "ch04__b05_sanctuary_fall__08" },
  { se: "slash" },
  { fx: "red" },
  { chara: { slot: "left", id: "nicholas", expr: "depressed" } },
  { name: "ニコラス", who: "nicholas", text: "がはっ……教皇……どうして……来てくれないんだ……", tid: "ch04__b05_sanctuary_fall__09" },
  { text: "本来であれば、ここで遅延詠唱が編まれる筈だった。勇者が稼いだ僅かな時間に、教皇イヴ・エンドが致命の魔術を完成させる筈だった。──だが、その魔術師はもう、広間の屍の中で冷たくなっている。", tid: "ch04__b05_sanctuary_fall__10" },
  { name: "ニコラス", who: "nicholas", text: "そんな……僕は……今度こそ……世界を救う筈、だったのに……", tid: "ch04__b05_sanctuary_fall__11" },
  { text: "未来視の前に、勇者は為す術なく崩れ落ちた。時間を稼いだところで、遅延詠唱を編む者はもう居ない。ラプラスの歩みを止める物は、何も無かった。", tid: "ch04__b05_sanctuary_fall__12" },
  { hide: "left" },
  { name: "ラプラス", who: "laplace", text: "さーて神様ぁ……魔王様がよろしくとのことです☆", tid: "ch04__b05_sanctuary_fall__13" },
  { text: "聖剣フルティンが、振り上げられる。無色透明の聖域の中央で、神は──十歳の少女の姿をした｜依代《よりしろ》は、最後まで酷く冷静な瞳で、その切っ先を見つめていた。", tid: "ch04__b05_sanctuary_fall__14" },
  { bgm: null },
  { se: "flash" },
  { fx: "flash" },
  { hide: "all" },
  { text: "……ガラスの砕けるような音が、世界の何処か奥深くで、確かに響いた。", tid: "ch04__b05_sanctuary_fall__15" },
  { fade: "out" },

  { label: "b05_deicide_night" },
  { pov: null },
  { fx: "clear-red" },
  { bg: "arcadia_lower_night" },
  { fade: "in" },
  { bgm: "dark2" },
  { text: "その夜。拠点に戻った俺達が見上げた空に、上層は──無かった。支えを失った浮遊都市が軋み、傾いでいく。そして、世界中の空に、あの男の声が響き渡った。", tid: "ch04__b05_deicide_night__01" },
  { se: "rumble" },
  { fx: "red" },
  { name: "魔王の声", text: "──神は死んだ。｜穢れ《けがれ》を受け入れろ", tid: "ch04__b05_deicide_night__02" },
  { chara: [
      { slot: "left", id: "crocell", expr: "sad" },
      { slot: "center", id: "yamato", expr: "serious" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……神の加護が、消えていく。魔の者の力を縛る枷が……もう何処にも無い", tid: "ch04__b05_deicide_night__03" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "神は全能なんじゃないのかよ。世界の創造主が、たった一人死んだぐらいで……こんな簡単に、世界が傾くものなのか", tid: "ch04__b05_deicide_night__04" },
  { chara: { slot: "right", id: "el", expr: "normal" } },
  { name: "エル", who: "el", text: "そんなことはないよ。あの神はどこまでも無力だ。……少なくとも、今はね", tid: "ch04__b05_deicide_night__05" },
  { text: "ぽつりと零されたエルの声は、酷く穏やかで、それでいて妙に確信めいていた。何故お前がそんな事を知っている――そう問おうとして、俺は口を噤む。崩れゆく空を見上げるエルの横顔が、悲しんでいるようにも、ただ静かに諦めているようにも見えたからだ。", tid: "ch04__b05_deicide_night__06" },
  { name: "ヤマト", who: "yamato", text: "……お前、さっきから、何を知ってるんだ", tid: "ch04__b05_deicide_night__07" },
  { chara: { slot: "right", id: "el", expr: "blank" } },
  { name: "エル", who: "el", text: "さあ……どうだろうね。私はただ、知っているだけだよ。あの神様が、思っているほど大層な存在じゃないってことを", tid: "ch04__b05_deicide_night__08" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "世界は……終わってないだろ。なら、別に良い筈だ……俺はそう言った筈だ……", tid: "ch04__b05_deicide_night__09" },
  { text: "言葉が、喉の奥で乾いていく。加護を失った砂漠の聖都に、その夜、魔物の｜咆哮《ほうこう》が蘇った。結界の無い街。武装しない冒険者。戦力を持たない神の国は、一夜にして地獄と化した。", tid: "ch04__b05_deicide_night__10" },
  { se: "roar" },
  { fx: "shake" },
  { chara: { slot: "right", id: "tia", expr: "sad" } },
  { name: "ティア", who: "tia", text: "ヤマト……わたし、聞こえてたの。あのお爺さんの声……最後まで、神様を守ろうとしてたわ", tid: "ch04__b05_deicide_night__11" },
  { name: "ヤマト", who: "yamato", text: "……黙ってくれ", tid: "ch04__b05_deicide_night__12" },
  { chara: { slot: "left", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", text: "逃げるぞ、ご主人。何処へなりと……いや……", tid: "ch04__b05_deicide_night__13" },
  { text: "クロセルは言い掛けて、口を噤んだ。王国では犯罪者。帝国は魔王の｜傀儡《かいらい》。公国は滅び、そして教国は今、燃えている。──俺達に、もう逃げ込む場所はどこにもない。", tid: "ch04__b05_deicide_night__14" },
  { chara: { slot: "center", id: "yamato", expr: "sad" } },
  { name: "ヤマト", who: "yamato", text: "俺は……助ける義理の無い人間は、助けない。それだけの話だった筈なんだ。なのに、なんで……世界の方が、終わりやがるんだよ……", tid: "ch04__b05_deicide_night__15" },
  { chara: { slot: "right", id: "tia", expr: "sad" } },
  { name: "ティア", who: "tia", text: "ヤマト……わたし、勇者だから、分かるの。あのお爺さんは、最後まで聖域に行こうとしてた。あの人が生きてたら……きっと、神様は……", tid: "ch04__b05_deicide_night__16" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "やめろ。それ以上、言うな", tid: "ch04__b05_deicide_night__17" },
  { chara: { slot: "left", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", text: "ご主人。我は、お前を責めはしない。あの時、お前は仲間を守ろうとしただけだ。それは間違いではない。間違いでは、ない筈なのだ……", tid: "ch04__b05_deicide_night__18" },
  { name: "ヤマト", who: "yamato", text: "……だったら、なんでお前まで、そんな顔してるんだよ", tid: "ch04__b05_deicide_night__19" },
  { text: "クロセルは、答えなかった。答えられなかったのだろう。燃え上がる聖都の空を、黒い翼の群れが覆っていく。あの日、手を貸さなかった老人の体温を、俺はこの先ずっと、知らないままで生きていく。──生きて、いければの話だが。", tid: "ch04__b05_deicide_night__20" },
  { fade: "out" },
  { jump: "ending:bad_deicide" },

]);
